INSERT INTO `mdl_badge` VALUES
(1,'Chuyên gia Kỹ thuật CHAMSOC01','Huy hiệu công nhận hoàn thành xuất sắc khóa học Kỹ thuật Chăm sóc Cây trồng Công nghệ cao & Dinh dưỡng Tự động đạt từ 70% trở lên.',1794030409,1794030409,2,2,'Mầm Xanh LMS 2.0 - Nông nghiệp Công nghệ cao','https://moodle.lvh.me:8443','admin@mamxanh.vn',NULL,NULL,2,2,'Chúc mừng bạn đã đạt Huy hiệu Kỹ thuật Nông nghiệp Công nghệ cao!','Đã mở khóa Huy hiệu Kỹ thuật Mầm Xanh!',1,0,1,NULL,'2.0','vi','Mam Xanh AgTech','admin@mamxanh.vn','https://moodle.lvh.me:8443','CHAMSOC01'),
(2,'Chuyên gia Kỹ thuật CHEBIEN01','Huy hiệu công nhận hoàn thành xuất sắc khóa học Công nghệ Sơ chế, Chế biến Sâu & Bảo quản Lạnh Nông sản Xuất khẩu đạt từ 70% trở lên.',1794030410,1794030410,2,2,'Mầm Xanh LMS 2.0 - Nông nghiệp Công nghệ cao','https://moodle.lvh.me:8443','admin@mamxanh.vn',NULL,NULL,2,3,'Chúc mừng bạn đã đạt Huy hiệu Kỹ thuật Nông nghiệp Công nghệ cao!','Đã mở khóa Huy hiệu Kỹ thuật Mầm Xanh!',1,0,1,NULL,'2.0','vi','Mam Xanh AgTech','admin@mamxanh.vn','https://moodle.lvh.me:8443','CHEBIEN01'),
(3,'Chuyên gia Kỹ thuật IOTNHAMANG01','Huy hiệu công nhận hoàn thành xuất sắc khóa học Vận hành Nhà màng Thông minh & Trạm Cảm biến Vi khí hậu IoT đạt từ 70% trở lên.',1794030411,1794030411,2,2,'Mầm Xanh LMS 2.0 - Nông nghiệp Công nghệ cao','https://moodle.lvh.me:8443','admin@mamxanh.vn',NULL,NULL,2,4,'Chúc mừng bạn đã đạt Huy hiệu Kỹ thuật Nông nghiệp Công nghệ cao!','Đã mở khóa Huy hiệu Kỹ thuật Mầm Xanh!',1,0,1,NULL,'2.0','vi','Mam Xanh AgTech','admin@mamxanh.vn','https://moodle.lvh.me:8443','IOTNHAMANG01'),
(4,'Chuyên gia Kỹ thuật THUYCANH01','Huy hiệu công nhận hoàn thành xuất sắc khóa học Kỹ thuật Thủy canh Hồi lưu NFT & Giá thể Xơ dừa Chuẩn VietGAP đạt từ 70% trở lên.',1794030412,1794030412,2,2,'Mầm Xanh LMS 2.0 - Nông nghiệp Công nghệ cao','https://moodle.lvh.me:8443','admin@mamxanh.vn',NULL,NULL,2,5,'Chúc mừng bạn đã đạt Huy hiệu Kỹ thuật Nông nghiệp Công nghệ cao!','Đã mở khóa Huy hiệu Kỹ thuật Mầm Xanh!',1,0,1,NULL,'2.0','vi','Mam Xanh AgTech','admin@mamxanh.vn','https://moodle.lvh.me:8443','THUYCANH01'),
(5,'Chuyên gia Kỹ thuật SAURIENG01','Huy hiệu công nhận hoàn thành xuất sắc khóa học Quy trình Canh tác Sầu riêng Xuất khẩu, Mã số Vùng trồng & Xử lý Ra hoa đạt từ 70% trở lên.',1794030413,1794030413,2,2,'Mầm Xanh LMS 2.0 - Nông nghiệp Công nghệ cao','https://moodle.lvh.me:8443','admin@mamxanh.vn',NULL,NULL,2,6,'Chúc mừng bạn đã đạt Huy hiệu Kỹ thuật Nông nghiệp Công nghệ cao!','Đã mở khóa Huy hiệu Kỹ thuật Mầm Xanh!',1,0,1,NULL,'2.0','vi','Mam Xanh AgTech','admin@mamxanh.vn','https://moodle.lvh.me:8443','SAURIENG01'),
(6,'Chuyên gia Kỹ thuật PHANVISINH01','Huy hiệu công nhận hoàn thành xuất sắc khóa học Sản xuất Phân Hữu cơ Vi sinh, Nhân sinh khối Trichoderma & Cải tạo Đất đạt từ 70% trở lên.',1794030414,1794030414,2,2,'Mầm Xanh LMS 2.0 - Nông nghiệp Công nghệ cao','https://moodle.lvh.me:8443','admin@mamxanh.vn',NULL,NULL,2,7,'Chúc mừng bạn đã đạt Huy hiệu Kỹ thuật Nông nghiệp Công nghệ cao!','Đã mở khóa Huy hiệu Kỹ thuật Mầm Xanh!',1,0,1,NULL,'2.0','vi','Mam Xanh AgTech','admin@mamxanh.vn','https://moodle.lvh.me:8443','PHANVISINH01');
