INSERT INTO `mdl_course` VALUES
(1,0,1,'Hệ thống Tập huấn Kỹ thuật Canh tác Nông nghiệp Công nghệ cao - Mầm Xanh LMS 2.0','Mầm Xanh LMS 2.0','','Nền tảng đào tạo số hóa kỹ thuật nông nghiệp công nghệ cao, VietGAP, IoT nhà màng và truy xuất nguồn gốc nông sản.',0,'site',1,3,0,0,0,0,0,0,0,1,1,NULL,0,0,0,'','','',1794024533,1794024574,0,0,0,1795257526,NULL,0,NULL,NULL),
(2,2,20007,'Kỹ thuật Canh tác Nông nghiệp Công nghệ cao & Dinh dưỡng Tự động','CHAMSOC01','CHAMSOC01','<p>Học phần trang bị kiến thức chuyên sâu về vi khí hậu nhà màng, hệ thống tưới nhỏ giọt bù áp, quản lý dinh dưỡng khoáng pH/EC tự động, và phác đồ kiểm soát dịch hại sinh học (IPM) theo tiêu chuẩn VietGAP TCVN 11892-1:2017.</p>',1,'topics',1,1,1791438407,0,0,0,0,0,1,1,1,NULL,0,0,0,'','','',1794030407,1794030407,0,1,0,1795257526,NULL,1,1,NULL),
(3,2,20006,'Công nghệ Sơ chế, Chế biến Sâu & Bảo quản Lạnh Nông sản Xuất khẩu','CHEBIEN01','CHEBIEN01','<p>Làm chủ chuỗi giá trị sau thu hoạch: Hạ nhiệt đồng ruộng (Pre-cooling) trong 2 giờ vàng, công nghệ sấy lạnh bơm nhiệt giữ nguyên dưỡng chất, đóng gói khí quyển biến đổi MAP/CA, kho lạnh thông minh và cấp mã QR VietGAP.</p>',1,'topics',1,1,1791438409,0,0,0,0,0,1,1,1,NULL,0,0,0,'','','',1794030409,1794030409,0,1,0,1795257526,NULL,1,1,NULL),
(4,2,20005,'Vận hành Nhà màng Thông minh & Trạm Cảm biến Vi khí hậu IoT','IOTNHAMANG01','IOTNHAMANG01','<p>Làm chủ hệ thống cảm biến nhiệt-ẩm-ánh sáng PAR-CO2, chỉ số thiếu hụt áp suất hơi nước VPD, điều khiển tự động lưới cắt nắng, quạt đối lưu, màn mưa Cooling Pad và cảnh báo sự cố qua điện thoại.</p>',1,'topics',1,1,1791438410,0,0,0,0,0,1,1,1,NULL,0,0,0,'','','',1794030410,1794030410,0,1,0,1795257526,NULL,0,1,NULL),
(5,2,20004,'Kỹ thuật Thủy canh Hồi lưu NFT & Giá thể Xơ dừa Chuẩn VietGAP','THUYCANH01','THUYCANH01','<p>Thiết kế độ dốc máng thủy canh màng dinh dưỡng NFT 1:40, kiểm soát oxy hòa tan DO &gt;= 6 mg/L, làm mát bồn dinh dưỡng, xử lý xơ dừa xả chát Tanin/EC và kiểm soát nitrat an toàn trước thu hoạch.</p>',1,'topics',1,1,1791438411,0,0,0,0,0,1,1,1,NULL,0,0,0,'','','',1794030411,1794030411,0,1,0,1795257526,NULL,0,1,NULL),
(6,2,20003,'Quy trình Canh tác Sầu riêng Xuất khẩu, Mã số Vùng trồng & Xử lý Ra hoa','SAURIENG01','SAURIENG01','<p>Chuẩn hóa quy trình canh tác Sầu riêng Dona/Ri6 phục vụ Nghị định thư xuất khẩu chính ngạch: Quản lý cơi đọt, tạo khô hạn sinh lý ra hoa đồng loạt, đậu trái - tỉa trái, phòng chống Phytophthora &amp; Rệp sáp, quản lý Mã số vùng trồng (PUC) và kiểm soát tuyệt đối Cadimi/dư lượng.</p>',1,'topics',1,1,1791438412,0,0,0,0,0,1,1,1,NULL,0,0,0,'','','',1794030412,1794030412,0,1,0,1795257526,NULL,0,1,NULL),
(7,2,20002,'Sản xuất Phân Hữu cơ Vi sinh, Nhân sinh khối Trichoderma & Cải tạo Đất','PHANVISINH01','PHANVISINH01','<p>Biến phụ phẩm nông nghiệp (vỏ cà phê, phân chuồng, rơm rạ, phụ phẩm rau quả) thành vàng đen cho đất: Phối trộn tỷ lệ C/N = 25–30:1, kiểm soát đống ủ hiếu khí 55–65°C tiêu diệt mầm bệnh/hạt cỏ, nhân sinh khối Trichoderma - Bacillus - IMO bản địa phục hồi hệ vi sinh đất.</p>',1,'topics',1,1,1791438413,0,0,0,0,0,1,1,1,NULL,0,0,0,'','','',1794030413,1794030413,0,1,0,1795257526,NULL,0,1,NULL),
(8,2,20001,'[MẪU CHUẨN] Khung Chương trình Tập huấn Nông nghiệp Công nghệ cao (Master Template)','MASTER-AGRITECH-TPL','MASTER-AGRITECH-TPL','<p>Khóa học Mẫu chuẩn quốc gia thiết kế theo <strong>Lộ trình Học tập Tuần tự 4 Bước khép kín</strong>: (1) Video thực tế HD + Xem trực tiếp PDF kỹ thuật → (2) Học liệu tương tác H5P &amp; SCORM 1.2 → (3) Thực hành hiện trường tại vườn (QR + GPS + Rubric) → (4) Kiểm tra cuối khóa đạt &ge; 70% mở khóa Chứng nhận Số QR. Sẵn sàng nhân bản 1-Chạm cho mọi địa phương và Hợp tác xã!</p>',1,'topics',1,1,1793429722,0,0,0,0,0,1,0,1,NULL,0,0,0,'','','',1794034522,1794034522,0,1,0,1795257526,NULL,1,1,NULL),
(19,1,10002,'Kỹ thuật Canh tác Dâu tây & Hoa Cúc Công nghệ cao trong Nhà màng Đà Lạt','DAUTAY-CNC-01','','<p>Khóa học cung cấp kiến thức thực tiễn và quy chuẩn kỹ thuật sản xuất nông nghiệp công nghệ cao đối với hai cây trồng chủ lực của thành phố Đà Lạt (tỉnh Lâm Đồng): Dâu tây và Hoa cúc. Nội dung bao gồm quản lý vi khí hậu nhà màng, công nghệ tưới nhỏ giọt bù áp, quản lý dinh dưỡng khoáng tự động theo giai đoạn sinh trưởng, quản lý dịch hại tổng hợp (IPM) bằng giải pháp sinh học, truy xuất nguồn gốc số và thực hành quy trình nông nghiệp tốt VietGAP (TCVN 11892-1:2017).</p>',1,'topics',1,5,1794330000,1825866000,0,0,0,0,1,1,1,NULL,0,0,0,'','','',1794280654,1794280654,0,1,0,1795257526,NULL,1,1,NULL),
(21,1,10001,'Tập huấn Kỹ thuật Dâu tây & Hoa Cúc CNC - HTX Đơn Dương','DAUTAY-DONDUONG-01','DAUTAY-DONDUONG-01','<p>Khóa học cung cấp kiến thức thực tiễn và quy chuẩn kỹ thuật sản xuất nông nghiệp công nghệ cao đối với hai cây trồng chủ lực của thành phố Đà Lạt (tỉnh Lâm Đồng): Dâu tây và Hoa cúc. Nội dung bao gồm quản lý vi khí hậu nhà màng, công nghệ tưới nhỏ giọt bù áp, quản lý dinh dưỡng khoáng tự động theo giai đoạn sinh trưởng, quản lý dịch hại tổng hợp (IPM) bằng giải pháp sinh học, truy xuất nguồn gốc số và thực hành quy trình nông nghiệp tốt VietGAP (TCVN 11892-1:2017).</p>',1,'topics',1,5,1794330000,1825866000,0,0,0,0,1,1,1,NULL,0,0,0,'','','',1794280654,1794282025,0,1,0,1795257526,19,1,1,NULL);
