INSERT INTO `mdl_course_sections` VALUES
(1,2,0,'Thông tin chung & Đề cương học phần','<p>Đề cương chi tiết học phần, lịch trình tập huấn, điểm danh thực hành và tài liệu tham khảo chính thức chuẩn Bộ Nông nghiệp & Phát triển Nông thôn.</p>',1,'1,127,128',1,NULL,NULL,NULL,1794030407),
(2,2,1,'Chuyên đề 1: Vi khí hậu & Tiêu chuẩn Cây giống Nhà màng','<p>Nghiên cứu nguyên lý thông gió mái lùa, kiểm soát bức xạ nhiệt và tiêu chuẩn xuất vườn cây giống dưa lưới, cà chua bi.</p>',1,'2,37',1,NULL,NULL,NULL,1794030407),
(3,2,2,'Chuyên đề 2: Kỹ thuật Tưới nhỏ giọt & Tiết kiệm nước','<p>Tính toán thủy lực mạng lưới đường ống, béc nhỏ giọt bù áp và lập lịch tưới tiết kiệm theo giai đoạn phát triển của cây.</p>',1,'3,38,39,129,132',1,NULL,NULL,NULL,1794030407),
(4,2,3,'Chuyên đề 3: Cân bằng Dinh dưỡng pH/EC & Châm phân Fertigation','<p>Phác đồ hòa tan dinh dưỡng bồn A-B chống kết tủa, kiểm soát ngưỡng EC (độ dẫn điện) và pH qua hệ thống điều khiển tự động.</p>',1,'4,5,40,130',1,NULL,NULL,NULL,1794030407),
(5,2,4,'Chuyên đề 4: Quản lý Dịch hại Tổng hợp (IPM) & Kiểm soát Sinh học','<p>Phương pháp điều tra sinh thái đồng ruộng, bẫy dính màu, thiên địch và chế phẩm sinh học Beauveria bassiana thay thế thuốc hóa học độc hại.</p>',1,'131',1,NULL,NULL,NULL,1794030407),
(6,3,0,'Tổng quan Khóa học & Hướng dẫn Học tập Rảnh tay','<p>Làm chủ chuỗi giá trị sau thu hoạch: Hạ nhiệt đồng ruộng (Pre-cooling) trong 2 giờ vàng, công nghệ sấy lạnh bơm nhiệt giữ nguyên dưỡng chất, đóng gói khí quyển biến đổi MAP/CA, kho lạnh thông minh và cấp mã QR VietGAP.</p>',1,'7',1,NULL,NULL,NULL,1794030409),
(7,3,1,'Chuyên đề 1: Video Hướng dẫn Trực quan & Infographic Kỹ thuật Số','<p>Xem video phân đoạn thực địa và tra cứu bảng thông số chuẩn pH/EC, nhiệt ẩm.</p>',1,'8,41',1,NULL,NULL,NULL,1794030409),
(8,3,2,'Chuyên đề 2: Bài giảng Slide Tương tác (7 Slides) & Câu hỏi Tình huống','<p>Tương tác trực tiếp trên sơ đồ hệ thống kỹ thuật và trả lời nhanh tình huống tại vườn.</p>',1,'9,42,43',1,NULL,NULL,NULL,1794030409),
(9,3,3,'Chuyên đề 3: Thẻ lật Sâu bệnh IPM, Truy xuất QR VietGAP & Thực hành Vườn','<p>Lật thẻ chẩn đoán Gỉ sắt, Rệp sáp, Bọ trĩ, Nhện đỏ và điểm danh QR thực hành hiện trường.</p>',1,'10,11',1,NULL,NULL,NULL,1794030409),
(10,3,4,'Kiểm tra & Đánh giá','<p>Hệ thống điểm danh chuyên cần (Lý thuyết & Thực hành), thảo luận chuyên đề theo buổi học, bài kiểm tra trắc nghiệm và bài thu hoạch cuối khóa chấm theo tiêu chí Rubric.</p>',1,'140,141,142,143,144,145,12',1,NULL,NULL,NULL,1794755026),
(11,4,0,'Tổng quan Khóa học & Hướng dẫn Học tập Rảnh tay','<p>Làm chủ hệ thống cảm biến nhiệt-ẩm-ánh sáng PAR-CO2, chỉ số thiếu hụt áp suất hơi nước VPD, điều khiển tự động lưới cắt nắng, quạt đối lưu, màn mưa Cooling Pad và cảnh báo sự cố qua điện thoại.</p>',1,'13',1,NULL,NULL,NULL,1794030410),
(12,4,1,'Chuyên đề 1: Video Hướng dẫn Trực quan & Infographic Kỹ thuật Số','<p>Xem video phân đoạn thực địa và tra cứu bảng thông số chuẩn pH/EC, nhiệt ẩm.</p>',1,'14,176',1,NULL,NULL,NULL,1794030410),
(13,4,2,'Chuyên đề 2: Bài giảng Slide Tương tác (7 Slides) & Câu hỏi Tình huống','<p>Tương tác trực tiếp trên sơ đồ hệ thống kỹ thuật và trả lời nhanh tình huống tại vườn.</p>',1,'15,179',1,NULL,NULL,NULL,1794030410),
(14,4,3,'Chuyên đề 3: Thẻ lật Sâu bệnh IPM, Truy xuất QR VietGAP & Thực hành Vườn','<p>Lật thẻ chẩn đoán Gỉ sắt, Rệp sáp, Bọ trĩ, Nhện đỏ và điểm danh QR thực hành hiện trường.</p>',1,'16,17,180',1,NULL,NULL,NULL,1794030410),
(15,4,4,'Kiểm tra & Đánh giá','<p>Hệ thống điểm danh chuyên cần (Lý thuyết & Thực hành), thảo luận chuyên đề theo buổi học, bài kiểm tra trắc nghiệm và bài thu hoạch cuối khóa chấm theo tiêu chí Rubric.</p>',1,'18,177,178,181,182,183',1,NULL,NULL,NULL,1794755026),
(16,5,0,'Tổng quan Khóa học & Hướng dẫn Học tập Rảnh tay','<p>Thiết kế độ dốc máng thủy canh màng dinh dưỡng NFT 1:40, kiểm soát oxy hòa tan DO &gt;= 6 mg/L, làm mát bồn dinh dưỡng, xử lý xơ dừa xả chát Tanin/EC và kiểm soát nitrat an toàn trước thu hoạch.</p>',1,'19',1,NULL,NULL,NULL,1794030411),
(17,5,1,'Chuyên đề 1: Video Hướng dẫn Trực quan & Infographic Kỹ thuật Số','<p>Xem video phân đoạn thực địa và tra cứu bảng thông số chuẩn pH/EC, nhiệt ẩm.</p>',1,'20,184',1,NULL,NULL,NULL,1794030411),
(18,5,2,'Chuyên đề 2: Bài giảng Slide Tương tác (7 Slides) & Câu hỏi Tình huống','<p>Tương tác trực tiếp trên sơ đồ hệ thống kỹ thuật và trả lời nhanh tình huống tại vườn.</p>',1,'21,187',1,NULL,NULL,NULL,1794030411),
(19,5,3,'Chuyên đề 3: Thẻ lật Sâu bệnh IPM, Truy xuất QR VietGAP & Thực hành Vườn','<p>Lật thẻ chẩn đoán Gỉ sắt, Rệp sáp, Bọ trĩ, Nhện đỏ và điểm danh QR thực hành hiện trường.</p>',1,'22,23,188',1,NULL,NULL,NULL,1794030411),
(20,5,4,'Kiểm tra & Đánh giá','<p>Hệ thống điểm danh chuyên cần (Lý thuyết & Thực hành), thảo luận chuyên đề theo buổi học, bài kiểm tra trắc nghiệm và bài thu hoạch cuối khóa chấm theo tiêu chí Rubric.</p>',1,'24,185,186,189,190,191',1,NULL,NULL,NULL,1794755026),
(21,6,0,'Tổng quan Khóa học & Hướng dẫn Học tập Rảnh tay','<p>Chuẩn hóa quy trình canh tác Sầu riêng Dona/Ri6 phục vụ Nghị định thư xuất khẩu chính ngạch: Quản lý cơi đọt, tạo khô hạn sinh lý ra hoa đồng loạt, đậu trái - tỉa trái, phòng chống Phytophthora &amp; Rệp sáp, quản lý Mã số vùng trồng (PUC) và kiểm soát tuyệt đối Cadimi/dư lượng.</p>',1,'25',1,NULL,NULL,NULL,1794030412),
(22,6,1,'Chuyên đề 1: Video Hướng dẫn Trực quan & Infographic Kỹ thuật Số','<p>Xem video phân đoạn thực địa và tra cứu bảng thông số chuẩn pH/EC, nhiệt ẩm.</p>',1,'26,192',1,NULL,NULL,NULL,1794030412),
(23,6,2,'Chuyên đề 2: Bài giảng Slide Tương tác (7 Slides) & Câu hỏi Tình huống','<p>Tương tác trực tiếp trên sơ đồ hệ thống kỹ thuật và trả lời nhanh tình huống tại vườn.</p>',1,'27,195',1,NULL,NULL,NULL,1794030412),
(24,6,3,'Chuyên đề 3: Thẻ lật Sâu bệnh IPM, Truy xuất QR VietGAP & Thực hành Vườn','<p>Lật thẻ chẩn đoán Gỉ sắt, Rệp sáp, Bọ trĩ, Nhện đỏ và điểm danh QR thực hành hiện trường.</p>',1,'28,29,196',1,NULL,NULL,NULL,1794030412),
(25,6,4,'Kiểm tra & Đánh giá','<p>Hệ thống điểm danh chuyên cần (Lý thuyết & Thực hành), thảo luận chuyên đề theo buổi học, bài kiểm tra trắc nghiệm và bài thu hoạch cuối khóa chấm theo tiêu chí Rubric.</p>',1,'30,193,194,197,198,199',1,NULL,NULL,NULL,1794755026),
(26,7,0,'Tổng quan Khóa học & Hướng dẫn Học tập Rảnh tay','<p>Biến phụ phẩm nông nghiệp (vỏ cà phê, phân chuồng, rơm rạ, phụ phẩm rau quả) thành vàng đen cho đất: Phối trộn tỷ lệ C/N = 25–30:1, kiểm soát đống ủ hiếu khí 55–65°C tiêu diệt mầm bệnh/hạt cỏ, nhân sinh khối Trichoderma - Bacillus - IMO bản địa phục hồi hệ vi sinh đất.</p>',1,'31',1,NULL,NULL,NULL,1794030413),
(27,7,1,'Chuyên đề 1: Video Hướng dẫn Trực quan & Infographic Kỹ thuật Số','<p>Xem video phân đoạn thực địa và tra cứu bảng thông số chuẩn pH/EC, nhiệt ẩm.</p>',1,'32,200',1,NULL,NULL,NULL,1794030413),
(28,7,2,'Chuyên đề 2: Bài giảng Slide Tương tác (7 Slides) & Câu hỏi Tình huống','<p>Tương tác trực tiếp trên sơ đồ hệ thống kỹ thuật và trả lời nhanh tình huống tại vườn.</p>',1,'33,203',1,NULL,NULL,NULL,1794030413),
(29,7,3,'Chuyên đề 3: Thẻ lật Sâu bệnh IPM, Truy xuất QR VietGAP & Thực hành Vườn','<p>Lật thẻ chẩn đoán Gỉ sắt, Rệp sáp, Bọ trĩ, Nhện đỏ và điểm danh QR thực hành hiện trường.</p>',1,'34,35,204',1,NULL,NULL,NULL,1794030413),
(30,7,4,'Kiểm tra & Đánh giá','<p>Hệ thống điểm danh chuyên cần (Lý thuyết & Thực hành), thảo luận chuyên đề theo buổi học, bài kiểm tra trắc nghiệm và bài thu hoạch cuối khóa chấm theo tiêu chí Rubric.</p>',1,'36,201,202,205,206,207',1,NULL,NULL,NULL,1794755026),
(31,8,0,'Hướng dẫn Lộ trình Học tập Tuần tự 4 Bước','<p>Hoàn thành lần lượt từng bước để hệ thống tự động mở khóa chuyên đề tiếp theo.</p>',1,'44',1,NULL,NULL,NULL,1794034522),
(32,8,1,'Chuyên đề 1 (Bước 1): Video Kỹ thuật Thực tế HD & Xem Trực tiếp Sổ tay PDF','<p>Xem video thực địa có phụ đề tiếng Việt và đọc trực tiếp Sổ tay PDF ngay trên web để mở khóa Chuyên đề 2.</p>',1,'45,46',1,NULL,NULL,NULL,1794034522),
(33,8,2,'Chuyên đề 2 (Bước 2): Học liệu Tương tác Chuẩn Quốc tế H5P & Gói Bài giảng SCORM 1.2','<p>Yêu cầu mở khóa: Hoàn thành Chuyên đề 1. Thực hành trả lời H5P và gói bài giảng SCORM 1.2 đồng bộ điểm tự động.</p>',1,'47,48',1,'{\"op\":\"&\",\"c\":[{\"type\":\"completion\",\"cm\":45,\"e\":1},{\"type\":\"completion\",\"cm\":46,\"e\":1}],\"showc\":[true,true]}',NULL,NULL,1794034522),
(34,8,3,'Chuyên đề 3 (Bước 3): Thực hành Hiện trường tại Vườn (Điểm danh QR/GPS & Chấm Rubric)','<p>Yêu cầu mở khóa: Hoàn thành Chuyên đề 2. Điểm danh tại vườn mẫu và nhận điểm Rubric 4 tiêu chí.</p>',1,'49',1,'{\"op\":\"&\",\"c\":[{\"type\":\"completion\",\"cm\":47,\"e\":1},{\"type\":\"completion\",\"cm\":48,\"e\":1}],\"showc\":[true,true]}',NULL,NULL,1794034522),
(35,8,4,'Kiểm tra & Đánh giá','<p>Hệ thống điểm danh chuyên cần (Lý thuyết & Thực hành), thảo luận chuyên đề theo buổi học, bài kiểm tra trắc nghiệm và bài thu hoạch cuối khóa chấm theo tiêu chí Rubric.</p>',1,'146,147,148,149,150,151',1,'{\"op\":\"&\",\"c\":[{\"type\":\"completion\",\"cm\":49,\"e\":1}],\"showc\":[true]}',NULL,NULL,1794755026),
(86,2,5,'Kiểm tra & Đánh giá','<p>Hệ thống điểm danh chuyên cần (Lý thuyết & Thực hành), thảo luận chuyên đề theo buổi học, bài kiểm tra trắc nghiệm và bài thu hoạch cuối khóa chấm theo tiêu chí Rubric.</p>',1,'134,135,136,137,138,139,6',1,NULL,NULL,NULL,1794755026),
(87,19,0,'Thông tin chung & Tài liệu tham khảo','<p>Đề cương chi tiết học phần, lịch trình tập huấn lý thuyết - thực hành và tài liệu hướng dẫn kỹ thuật canh tác Dâu tây &amp; Hoa Cúc công nghệ cao đạt chuẩn VietGAP.</p>',1,'152,153',1,'{\"op\":\"&\",\"c\":[],\"showc\":[]}',NULL,NULL,1794754989),
(88,19,1,'Chuyên đề 1: Kỹ thuật Chăm sóc Cây trồng & Quản lý Vi khí hậu Nhà màng','<p>Tiêu chuẩn chọn cây giống cấy mô sạch bệnh, thiết kế thông gió nhà màng và kiểm soát bức xạ quang hợp PAR, nhiệt độ ngày/đêm và độ ẩm tương đối (RH).</p>',1,'160',1,'{\"op\":\"&\",\"c\":[],\"showc\":[]}',NULL,NULL,1794754989),
(89,19,2,'Chuyên đề 2: Kỹ thuật Tưới tiêu & Vận hành Hệ thống Tưới nhỏ giọt Bù áp','<p>Tính toán thủy lực đường ống, vận hành hệ thống tưới nhỏ giọt bù áp tự động và kiểm soát độ ẩm giá thể xơ dừa theo từng giai đoạn sinh trưởng.</p>',1,'154',1,'{\"op\":\"&\",\"c\":[],\"showc\":[]}',NULL,NULL,1794754989),
(90,19,3,'Chuyên đề 3: Quản lý Dinh dưỡng Khoáng & Châm phân Tự động (Fertigation)','<p>Phác đồ pha chế dung dịch dinh dưỡng bồn A-B, kiểm soát ngưỡng độ dẫn điện (EC 1,2 – 1,8 mS/cm) và độ pH (5,5 – 6,2) qua hệ thống châm phân Fertigation.</p>',1,'155,214',1,'{\"op\":\"&\",\"c\":[],\"showc\":[]}',NULL,NULL,1794754989),
(91,19,4,'Chuyên đề 4: Quản lý Dịch hại Tổng hợp (IPM) & Kiểm soát Sinh học','<p>Phương pháp điều tra sinh thái nhà màng, sử dụng bẫy dính sinh học, nhện bắt mồi thiên địch và chế phẩm nấm đối kháng <em>Trichoderma / Beauveria bassiana</em>.</p>',1,'212',1,'{\"op\":\"&\",\"c\":[],\"showc\":[]}',NULL,NULL,1794754989),
(92,19,5,'Kiểm tra & Đánh giá','<p>Hệ thống điểm danh chuyên cần (Lý thuyết & Thực hành), thảo luận chuyên đề theo buổi học, bài kiểm tra trắc nghiệm và bài thu hoạch cuối khóa chấm theo tiêu chí Rubric.</p>',1,'156,157,158,159,161,208,209',1,'{\"op\":\"&\",\"c\":[],\"showc\":[]}',NULL,NULL,1794755026),
(93,21,0,'Thông tin chung & Tài liệu tham khảo','<p>Đề cương chi tiết học phần, lịch trình tập huấn lý thuyết - thực hành và tài liệu hướng dẫn kỹ thuật canh tác Dâu tây &amp; Hoa Cúc công nghệ cao đạt chuẩn VietGAP.</p>',1,'162,163',1,'{\"op\":\"&\",\"c\":[],\"showc\":[]}',NULL,NULL,1794754989),
(94,21,1,'Chuyên đề 1: Kỹ thuật Chăm sóc Cây trồng & Quản lý Vi khí hậu Nhà màng','<p>Tiêu chuẩn chọn cây giống cấy mô sạch bệnh, thiết kế thông gió nhà màng và kiểm soát bức xạ quang hợp PAR, nhiệt độ ngày/đêm và độ ẩm tương đối (RH).</p>',1,'164',1,'{\"op\":\"&\",\"c\":[],\"showc\":[]}',NULL,NULL,1794754989),
(95,21,2,'Chuyên đề 2: Kỹ thuật Tưới tiêu & Vận hành Hệ thống Tưới nhỏ giọt Bù áp','<p>Tính toán thủy lực đường ống, vận hành hệ thống tưới nhỏ giọt bù áp tự động và kiểm soát độ ẩm giá thể xơ dừa theo từng giai đoạn sinh trưởng.</p>',1,'165',1,'{\"op\":\"&\",\"c\":[],\"showc\":[]}',NULL,NULL,1794754989),
(96,21,3,'Chuyên đề 3: Quản lý Dinh dưỡng Khoáng & Châm phân Tự động (Fertigation)','<p>Phác đồ pha chế dung dịch dinh dưỡng bồn A-B, kiểm soát ngưỡng độ dẫn điện (EC 1,2 – 1,8 mS/cm) và độ pH (5,5 – 6,2) qua hệ thống châm phân Fertigation.</p>',1,'166,215',1,'{\"op\":\"&\",\"c\":[],\"showc\":[]}',NULL,NULL,1794754989),
(97,21,4,'Chuyên đề 4: Quản lý Dịch hại Tổng hợp (IPM) & Kiểm soát Sinh học','<p>Phương pháp điều tra sinh thái nhà màng, sử dụng bẫy dính sinh học, nhện bắt mồi thiên địch và chế phẩm nấm đối kháng <em>Trichoderma / Beauveria bassiana</em>.</p>',1,'213',1,'{\"op\":\"&\",\"c\":[],\"showc\":[]}',NULL,NULL,1794754989),
(98,21,5,'Kiểm tra & Đánh giá','<p>Hệ thống điểm danh chuyên cần (Lý thuyết & Thực hành), thảo luận chuyên đề theo buổi học, bài kiểm tra trắc nghiệm và bài thu hoạch cuối khóa chấm theo tiêu chí Rubric.</p>',1,'167,168,169,170,171,210,211',1,'{\"op\":\"&\",\"c\":[],\"showc\":[]}',NULL,NULL,1794755026);
