INSERT INTO `mdl_favourite` VALUES
(1,'core_message','message_conversations',1,12,4,NULL,1794137864,1794137864);
INSERT INTO `mdl_fieldpractice` VALUES
(1,2,'Thực hành Tại vườn: Điểm danh QR & Rubric 4 Tiêu chí (CHAMSOC01)','<p>Buổi thực hành hiện trường tại <strong>Trạm Thực nghiệm Nhà màng Châm phân Tự động Đà Lạt</strong>. Học viên quét mã QR xoay vòng + định vị GPS để điểm danh; Cán bộ kỹ thuật chấm điểm trực tiếp theo Rubric 4 tiêu chí (100 điểm) đồng bộ thẳng vào Sổ điểm Gradebook.</p>',1,'Trạm Thực nghiệm Nhà màng Châm phân Tự động Đà Lạt','11.940419','108.458313',100,'MX2_QR_CHAMSOC01',1794030408,1794030408),
(2,3,'Thực hành Tại vườn: Điểm danh QR & Rubric 4 Tiêu chí (CHEBIEN01)','<p>Buổi thực hành hiện trường tại <strong>Xưởng Sơ chế Đóng gói &amp; Kho lạnh Chuẩn Xuất khẩu Mầm Xanh</strong>. Học viên quét mã QR xoay vòng + định vị GPS để điểm danh; Cán bộ kỹ thuật chấm điểm trực tiếp theo Rubric 4 tiêu chí (100 điểm) đồng bộ thẳng vào Sổ điểm Gradebook.</p>',1,'Xưởng Sơ chế Đóng gói & Kho lạnh Chuẩn Xuất khẩu Mầm Xanh','11.936200','108.462100',100,'MX2_QR_CHEBIEN01',1794030410,1794030410),
(3,4,'Thực hành Tại vườn: Điểm danh QR & Rubric 4 Tiêu chí (IOTNHAMANG01)','<p>Buổi thực hành hiện trường tại <strong>Trung tâm Nhà màng Tự động hóa IoT Công nghệ cao</strong>. Học viên quét mã QR xoay vòng + định vị GPS để điểm danh; Cán bộ kỹ thuật chấm điểm trực tiếp theo Rubric 4 tiêu chí (100 điểm) đồng bộ thẳng vào Sổ điểm Gradebook.</p>',1,'Trung tâm Nhà màng Tự động hóa IoT Công nghệ cao','11.948100','108.451200',100,'MX2_QR_IOTNHAMANG01',1794030411,1794030411),
(4,5,'Thực hành Tại vườn: Điểm danh QR & Rubric 4 Tiêu chí (THUYCANH01)','<p>Buổi thực hành hiện trường tại <strong>Khu Nhà màng Thủy canh Hồi lưu NFT Mầm Xanh</strong>. Học viên quét mã QR xoay vòng + định vị GPS để điểm danh; Cán bộ kỹ thuật chấm điểm trực tiếp theo Rubric 4 tiêu chí (100 điểm) đồng bộ thẳng vào Sổ điểm Gradebook.</p>',1,'Khu Nhà màng Thủy canh Hồi lưu NFT Mầm Xanh','11.952300','108.439500',100,'MX2_QR_THUYCANH01',1794030411,1794030411),
(5,6,'Thực hành Tại vườn: Điểm danh QR & Rubric 4 Tiêu chí (SAURIENG01)','<p>Buổi thực hành hiện trường tại <strong>Vườn Sầu riêng Chuẩn Mã số Xuất khẩu Tây Nguyên - Đông Nam Bộ</strong>. Học viên quét mã QR xoay vòng + định vị GPS để điểm danh; Cán bộ kỹ thuật chấm điểm trực tiếp theo Rubric 4 tiêu chí (100 điểm) đồng bộ thẳng vào Sổ điểm Gradebook.</p>',1,'Vườn Sầu riêng Chuẩn Mã số Xuất khẩu Tây Nguyên - Đông Nam Bộ','12.684210','108.214500',100,'MX2_QR_SAURIENG01',1794030412,1794030412),
