(9,'H5P.Chart','Chart',1,2,33,1,0,'iframe','chart.js, d3.js, pie.js, bar.js','chart.css','','[\n  {\n    \"name\": \"graphMode\",\n    \"type\": \"select\",\n    \"label\": \"Type of chart\",\n    \"importance\": \"high\",\n    \"options\": [\n      {\n        \"value\": \"pieChart\",\n        \"label\": \"Pie Chart\"\n      },\n      {\n        \"value\": \"barChart\",\n        \"label\": \"Bar Chart\"\n      }\n    ],\n    \"default\": \"pieChart\"\n  },\n  {\n    \"name\": \"listOfTypes\",\n    \"type\": \"list\",\n    \"label\": \"Data elements\",\n    \"importance\": \"high\",\n    \"entity\": \"option\",\n    \"min\": 1,\n    \"defaultNum\": 2,\n    \"field\": {\n      \"name\": \"type\",\n      \"type\": \"group\",\n      \"label\": \"Data element\",\n      \"importance\": \"high\",\n      \"fields\": [\n        {\n          \"name\": \"text\",\n          \"type\": \"text\",\n          \"label\": \"Name\",\n          \"importance\": \"medium\"\n        },\n        {\n          \"name\": \"value\",\n          \"type\": \"number\",\n          \"label\": \"Value\",\n          \"importance\": \"low\",\n          \"default\": 1,\n          \"min\": 0.0001,\n          \"decimals\": 4\n        },\n        {\n          \"name\": \"color\",\n          \"type\": \"text\",\n          \"widget\": \"colorSelector\",\n          \"label\": \"Color\",\n          \"importance\": \"low\",\n          \"default\": \"#000\",\n          \"optional\": true,\n          \"spectrum\": {\n            \"showInput\": true,\n            \"preferredFormat\": \"hex\"\n          }\n        },\n        {\n          \"name\": \"fontColor\",\n          \"type\": \"text\",\n          \"widget\": \"colorSelector\",\n          \"label\": \"Font Color\",\n          \"importance\": \"low\",\n          \"default\": \"#fff\",\n          \"optional\": true,\n          \"spectrum\": {\n            \"showInput\": true,\n            \"preferredFormat\": \"hex\"\n          }\n        }\n      ]\n    }\n  },\n  {\n    \"name\": \"figureDefinition\",\n    \"type\": \"text\",\n    \"label\": \"Text read by readspeakers defining the figure as a chart.\",\n    \"importance\": \"low\",\n    \"default\": \"Chart\",\n    \"common\": true\n  }\n]\n',NULL,1,28,NULL,'https://h5p.org/tutorial-chart','https://h5p.org/chart',1),
