(50,'H5P.ExportableTextArea','Exportable Text Area',1,3,22,0,0,'','dist/h5p-exportable-text-area.js','','','[\n  {\n    \"name\": \"label\",\n    \"type\": \"text\",\n    \"widget\": \"html\",\n    \"label\": \"Label\",\n    \"importance\": \"high\",\n    \"description\": \"Label/heading for answer when user exports all answers\",\n    \"enterMode\": \"p\",\n    \"tags\": [\n      \"strong\",\n      \"em\",\n      \"a\",\n      \"ul\",\n      \"ol\",\n      \"h2\",\n      \"h3\",\n      \"hr\",\n      \"pre\",\n      \"code\"\n    ]\n  },\n  {\n    \"name\": \"placeholderText\",\n    \"label\": \"Placeholder text\",\n    \"type\": \"text\",\n    \"description\": \"Example value or other placeholder text. Should not be used to replace the description of the input field.\",\n    \"importance\": \"low\",\n    \"optional\": true\n  },\n  {\n    \"name\": \"index\",\n    \"type\": \"number\",\n    \"label\": \"Index\",\n    \"widget\": \"none\"\n  },\n  {\n    \"name\": \"exportNotSupported\",\n    \"type\": \"text\",\n    \"importance\": \"low\",\n    \"label\": \"Export not supported label\",\n    \"default\": \"Export not supported on your device\",\n    \"common\": true\n  },\n  {\n    \"name\": \"exportComments\",\n    \"type\": \"boolean\",\n    \"importance\": \"low\",\n    \"label\": \"Include comments in the exported document\",\n    \"optional\": true,\n    \"default\": false\n  }\n]\n',NULL,1,28,'{\"disable\":false,\"disableExtraTitleField\":true}',NULL,NULL,1),
(51,'H5P.FreeTextQuestion','Free Text Question',1,0,22,0,0,'','h5p-free-text-question.js','h5p-free-text-question.css','','[\n  {\n    \"label\": \"Question\",\n    \"name\": \"question\",\n    \"type\": \"text\",\n    \"importance\": \"high\"\n  },\n  {\n    \"label\": \"Placeholder text\",\n    \"name\": \"placeholder\",\n    \"type\": \"text\",\n    \"importance\": \"high\",\n    \"default\": \"Enter your response here\",\n    \"description\": \"Text that initially will be shown in the input field. Will be removed automatically when the user starts writing.\"\n  },\n  {\n    \"label\": \"Max score\",\n    \"name\": \"maxScore\",\n    \"type\": \"number\",\n    \"importance\": \"high\",\n    \"description\": \"Used for grading and not shown to the learner\",\n    \"default\": 1\n  },\n  {\n    \"label\": \"Required\",\n    \"name\": \"isRequired\",\n    \"type\": \"boolean\",\n    \"importance\": \"high\",\n    \"description\": \"Learners must provide an answer in order to proceed\"\n  },\n  {\n    \"label\": \"Localize Free Text Question buttons\",\n    \"name\": \"i10n\",\n    \"type\": \"group\",\n    \"common\": true,\n    \"collapsed\": true,\n    \"importance\": \"low\",\n    \"fields\": [\n      {\n        \"label\": \"Required text label\",\n        \"name\": \"requiredText\",\n        \"type\": \"text\",\n        \"description\": \"Text shown to notify learner that input is required before proceeding\",\n        \"default\": \"required\",\n        \"importance\": \"low\"\n      },\n      {\n        \"label\": \"Required message\",\n        \"name\": \"requiredMessage\",\n        \"type\": \"text\",\n        \"importance\": \"low\",\n        \"default\": \"This question requires an answer\",\n        \"description\": \"Will display if this field is unanswered and required by a wrapper content type\"\n      },\n      {\n        \"label\": \"Skip button label\",\n        \"name\": \"skipButtonLabel\",\n        \"type\": \"text\",\n        \"default\": \"Skip