      {\n            \"value\": \"en-gb\",\n            \"label\": \"English (United Kingdom)\"\n          },\n          {\n            \"value\": \"en\",\n            \"label\": \"English\"\n          },\n          {\n            \"value\": \"eo\",\n            \"label\": \"Esperanto\"\n          },\n          {\n            \"value\": \"es-mx\",\n            \"label\": \"Spanish (Mexico)\"\n          },\n          {\n            \"value\": \"es\",\n            \"label\": \"Spanish (Spain)\"\n          },\n          {\n            \"value\": \"et\",\n            \"label\": \"Estonian\"\n          },\n          {\n            \"value\": \"eu\",\n            \"label\": \"Basque\"\n          },\n          {\n            \"value\": \"fa\",\n            \"label\": \"Farsi\"\n          },\n          {\n            \"value\": \"fi\",\n            \"label\": \"Finnish\"\n          },\n          {\n            \"value\": \"fo\",\n            \"label\": \"Faeroese\"\n          },\n          {\n            \"value\": \"fr-ca\",\n            \"label\": \"French (Canada)\"\n          },\n          {\n            \"value\": \"fr\",\n            \"label\": \"French (Standard)\"\n          },\n          {\n            \"value\": \"gl\",\n            \"label\": \"Galician\"\n          },\n          {\n            \"value\": \"gu\",\n            \"label\": \"Gujarati\"\n          },\n          {\n            \"value\": \"he\",\n            \"label\": \"Hebrew (modern)\"\n          },\n          {\n            \"value\": \"hi\",\n            \"label\": \"Hindi\"\n          },\n          {\n            \"value\": \"hr\",\n            \"label\": \"Croatian\"\n          },\n          {\n            \"value\": \"hu\",\n            \"label\": \"Hungarian\"\n          },\n          {\n            \"value\": \"id\",\n            \"label\": \"Indonesian\"\n          },\n          {\n            \"value\": \"is\",\n            \"label\": \"Icelandic\"\n          },\n          {\n            \"value\": \"it\",\n            \"label\": \"Italian (Standard)\"\n          },\n          {\n            \"value\": \"ja\",\n            \"label\": \"Japanese\"\n          },\n          {\n            \"value\": \"ka\",\n            \"label\": \"Georgian\"\n          },\n          {\n            \"value\": \"km\",\n            \"label\": \"Central Khmer\"\n          },\n          {\n            \"value\": \"ko\",\n            \"label\": \"Korean\"\n          },\n          {\n            \"value\": \"ku\",\n            \"label\": \"Kurdish\"\n          },\n          {\n            \"value\": \"lt\",\n            \"label\": \"Lithuanian\"\n          },\n          {\n            \"value\": \"lv\",\n            \"label\": \"Latvian\"\n          },\n          {\n            \"value\": \"mk\",\n            \"label\": \"Macedonian\"\n          },\n          {\n            \"value\": \"mn\",\n            \"label\": \"Mongolian\"\n          },\n          {\n            \"value\": \"ms\",\n            \"label\": \"Malay\"\n          },\n          {\n            \"value\": \"nb\",\n            \"label\": \"Norwegian Bokmål\"\n          },\n          {\n            \"value\": \"nl\",\n            \"label\": \"Dutch (Standard)\"\n          },\n          {\n            \"value\": \"no\",\n            \"label\": \"Norwegian\"\n          },\n          {\n            \"value\": \"oc\",\n            \"label\": \"Occitan\"\n          },\n          {\n            \"value\": \"pl\",\n            \"label\": \"Polish\"\n          },\n          {\n            \"value\": \"pt-br\",\n            \"label\": \"Portuguese (Brazil)\"\n          },\n          {\n            \"value\": \"pt\",\n            \"label\": \"Portuguese (Portugal)\"\n          },\n          {\n            \"value\": \"ro\",\n            \"label\": \"Romanian\"\n          },\n          {\n            \"value\": \"ru\",\n            \"label\": \"Russian\"\n          },\n          {\n            \"value\": \"si\",\n        