(75,'H5P.Shape','Shapes',1,0,5,0,0,'','js/h5p-shape.js','css/h5p-shape.css','','[\n  {\n    \"name\": \"type\",\n    \"type\": \"select\",\n    \"label\": \"Type\",\n    \"importance\": \"low\",\n    \"widget\": \"radioGroup\",\n    \"alignment\": \"horizontal\",\n    \"options\": [\n      {\n        \"value\": \"rectangle\",\n        \"label\": \"Rectangle\"\n      },\n      {\n        \"value\": \"circle\",\n        \"label\": \"Circle\"\n      },\n      {\n        \"value\": \"vertical-line\",\n        \"label\": \"Vertical line\"\n      },\n      {\n        \"value\": \"horizontal-line\",\n        \"label\": \"Horizontal line\"\n      }\n    ],\n    \"default\": \"rectangle\"\n  },\n  {\n    \"type\": \"group\",\n    \"name\": \"shape\",\n    \"widget\": \"showWhen\",\n    \"expanded\": true,\n    \"showWhen\": {\n      \"rules\": [\n        {\n          \"field\": \"type\",\n          \"equals\": [\n            \"rectangle\",\n            \"circle\"\n          ]\n        }\n      ]\n    },\n    \"fields\": [\n      {\n        \"name\": \"fillColor\",\n        \"type\": \"text\",\n        \"label\": \"Fill color\",\n        \"importance\": \"medium\",\n        \"optional\": true,\n        \"default\": \"#ffffff\",\n        \"widget\": \"colorSelector\",\n        \"showAplha\": true,\n        \"spectrum\": {\n          \"showInput\": true,\n          \"showAlpha\": true,\n          \"preferredFormat\": \"rgb\"\n        },\n        \"optional\": true\n      },\n      {\n        \"name\": \"borderColor\",\n        \"type\": \"text\",\n        \"label\": \"Border color\",\n        \"importance\": \"medium\",\n        \"optional\": true,\n        \"default\": \"#000000\",\n        \"widget\": \"colorSelector\",\n        \"spectrum\": {\n          \"showInput\": true,\n          \"showAlpha\": true,\n          \"preferredFormat\": \"rgb\"\n        },\n        \"optional\": true\n      },\n      {\n        \"name\": \"borderWidth\",\n        \"type\": \"select\",\n    