": \"text\",\n        \"label\": \"Line color\",\n        \"importance\": \"medium\",\n        \"optional\": true,\n        \"default\": \"#000000\",\n        \"widget\": \"colorSelector\",\n        \"optional\": true,\n        \"spectrum\": {\n          \"showInput\": true,\n          \"showAlpha\": true,\n          \"preferredFormat\": \"rgb\"\n        }\n      },\n      {\n        \"name\": \"borderWidth\",\n        \"type\": \"select\",\n        \"label\": \"Line width\",\n        \"importance\": \"low\",\n        \"default\": \"1\",\n        \"optional\": false,\n        \"options\": [\n          {\n            \"value\": \"1\",\n            \"label\": \"1\"\n          },\n          {\n            \"value\": \"2\",\n            \"label\": \"2\"\n          },\n          {\n            \"value\": \"3\",\n            \"label\": \"3\"\n          },\n          {\n            \"value\": \"4\",\n            \"label\": \"4\"\n          },\n          {\n            \"value\": \"5\",\n            \"label\": \"5\"\n          },\n          {\n            \"value\": \"6\",\n            \"label\": \"6\"\n          },\n          {\n            \"value\": \"7\",\n            \"label\": \"7\"\n          },\n          {\n            \"value\": \"8\",\n            \"label\": \"8\"\n          },\n          {\n            \"value\": \"9\",\n            \"label\": \"9\"\n          },\n          {\n            \"value\": \"10\",\n            \"label\": \"10\"\n          },\n          {\n            \"value\": \"11\",\n            \"label\": \"11\"\n          },\n          {\n            \"value\": \"12\",\n            \"label\": \"12\"\n          },\n          {\n            \"value\": \"13\",\n            \"label\": \"13\"\n          },\n          {\n            \"value\": \"14\",\n            \"label\": \"14\"\n          },\n          {\n            \"value\": \"15\",\n            \"label\": \"15\"\n          },\n          {\n            \"value\": \"16\",\n            \"label\": \