(84,'H5P.Timeline','Timeline',1,1,27,1,1,'iframe','timeline.js','timeline.css','','[\n  {\n    \"name\": \"timeline\",\n    \"label\": \"Timeline\",\n    \"importance\": \"high\",\n    \"type\": \"group\",\n    \"expanded\": true,\n    \"fields\": [\n      {\n        \"name\": \"headline\",\n        \"type\": \"text\",\n        \"label\": \"Headline\",\n        \"importance\": \"high\",\n        \"description\": \"Main timeline heading goes here (first page)\"\n      },\n      {\n        \"name\": \"text\",\n        \"type\": \"text\",\n        \"label\": \"Body Text\",\n        \"importance\": \"medium\",\n        \"widget\": \"html\",\n        \"description\": \"The main timeline body goes here (first page).\",\n        \"optional\": true,\n        \"tags\": [\n          \"strong\",\n          \"em\",\n          \"del\",\n          \"a\",\n          \"ul\",\n          \"ol\",\n          \"hr\",\n          \"code\"\n        ]\n      },\n      {\n        \"name\": \"defaultZoomLevel\",\n        \"type\": \"text\",\n        \"label\": \"Default zoom level\",\n        \"importance\": \"low\",\n        \"default\": \"0\",\n        \"optional\": true,\n        \"description\": \"This will tweak the default zoom level. Equivilent to pressing the zoom in or zoom out button the specified number of times. Negative numbers zoom out. default is 0\"\n      },\n      {\n        \"name\": \"backgroundImage\",\n        \"type\": \"image\",\n        \"label\": \"Background image\",\n        \"importance\": \"low\",\n        \"optional\": true,\n        \"description\": \"An image to display as background.\"\n      },\n      {\n        \"name\": \"height\",\n        \"type\": \"number\",\n        \"label\": \"Height\",\n        \"importance\": \"low\",\n        \"description\": \"The height in pixels\",\n        \"default\": 600\n      },\n      {\n        \"name\": \"asset\",\n        \"type\": \"group\",\n        \"label\": \"Asset\",\n        \"importance\": \"low\",\n        \"description\": \"Here you can add an asset to your timeline \\\"front page\\\"\",\n        \"optional\": true,\n        \"fields\": [\n          {\n            \"name\": \"media\",\n            \"type\": \"text\",\n            \"label\": \"Media\",\n            \"importance\": \"low\",\n            \"description\": \"Link to media URL (Twitter, YouTube, Flickr, Vimeo, Google Maps and SoundCloud are currently supported)\",\n            \"optional\": true\n          },\n          {\n            \"name\": \"credit\",\n            \"type\": \"text\",\n            \"label\": \"Credits\",\n            \"importance\": \"low\",\n            \"description\": \"Credits to the media\",\n            \"optional\": true\n          },\n          {\n            \"name\": \"caption\",\n            \"type\": \"text\",\n            \"label\": \"Caption\",\n            \"importance\": \"low\",\n            \"description\": \"Caption description goes here\",\n            \"optional\": true\n          }\n        ]\n      },\n      {\n        \"name\": \"date\",\n        \"type\": \"list\",\n        \"label\": \"Dates\",\n        \"importance\": \"medium\",\n        \"min\": 1,\n        \"description\": \"Add some dates to your timeline!\",\n        \"field\": {\n          \"name\": \"adate\",\n          \"type\": \"group\",\n          \"label\": \"Date\",\n          \"importance\": \"medium\",\n          \"description\": \"Date\",\n          \"fields\": [\n            {\n              \"name\": \"startDate\",\n              \"type\": \"text\",\n              \"label\": \"Start date\",\n              \"importance\": \"medium\",\n              \"description\": \"YYYY,MM,DD (Minimum YYYY required)\",\n              \"regexp\": {\n                \"pattern\": \"^-?\\\\d{1,}(,(1[012]|[0]?[1-9])(,([12][0-9]|3[01]|[0]?[1-9]))?)?$\"\n              }\n            },\n            {\n              \"name\": \"endDate\",\n              \"type\": \"text\",\n              \"label\": \"End date\",\n              \"importance\": \"medium\",\n              \"description\": \"YYYY,MM,DD (Minimum YYYY required)\",\n              \"optional\": true,\n              \"regexp\": {\n                \"pattern\": \"^-?\\\\d{1,}(,(1[012]|[0]?[1-9])(,([12][0-9]|3[01]|[0]?[1-9]))?)?$\"\n              }\n            },\n            {\n              \"name\": \"headline\",\n              \"type\": \"text\",\n              \"label\": \"Headline\",\n              \"importance\": \"medium\",\n              \"description\": \"Headline for the date entry\"\n            },\n            {\n              \"name\": \"text\",\n              \"type\": \"text\",\n              \"label\": \"Body text\",\n              \"importance\": \"medium\",\n              \"widget\": \"html\",\n              \"optional\": true,\n              \"description\": \"Body for the date entry\",\n              \"tags\": [\n                \"strong\",\n                \"em\",\n                \"del\",\n                \"a\",\n                \"ul\",\n                \"ol\",\n                \"h2\",\n                \"h3\",\n                \"hr\",\n                \"pre\",\n                \"code\"\n              ]\n            },\n            {\n              \"name\": \"tag\",\n              \"type\": \"text\",\n              \"label\": \"Tags\",\n              \"importance\": \"medium\",\n              \"description\": \"Enter Tags (categories)\",\n              \"optional\": true\n            },\n            {\n              \"name\": \"asset\",\n              \"type\": \"group\",\n              \"label\": \"Asset\",\n              \"importance\": \"low\",\n              \"description\": \"\",\n              \"optional\": true,\n              \"fields\": [\n                {\n                  \"name\": \"media\",\n                  \"type\": \"text\",\n                  \"label\": \"Media\",\n                  \"importance\": \"low\",\n                  \"description\": \"URL to the media (Twitter, YouTube, Flickr, Vimeo, Wikipedia, Google Maps and SoundCloud are currently supported).\",\n                  \"optional\": true\n                },\n                {\n                  \"name\": \"thumbnail\",\n                  \"type\": \"image\",\n                  \"label\": \"Thumbnail\",\n                  \"importance\": \"low\",\n                  \"description\": \"Add a thumbnail if needed, 32x32\",\n                  \"optional\": true\n                },\n                {\n                  \"name\": \"credit\",\n                  \"type\": \"text\",\n                  \"label\": \"Credit\",\n                  \"importance\": \"low\",\n                  \"description\": \"Credits to the media\",\n                  \"optional\": true\n                },\n                {\n                  \"name\": \"caption\",\n                  \"type\": \"text\",\n                  \"label\": \"Caption\",\n                  \"importance\": \"low\",\n                  \"description\": \"Caption text\",\n                  \"optional\": true\n                }\n              ]\n            }\n          ]\n        }\n      },\n      {\n        \"name\": \"era\",\n        \"type\": \"list\",\n        \"label\": \"Eras\",\n        \"importance\": \"medium\",\n        \"description\": \"Add an era to your timeline\",\n        \"min\": 0,\n        \"optional\": true,\n        \"field\": {\n          \"name\": \"anera\",\n          \"type\": \"group\",\n          \"label\": \"Era\",\n          \"importance\": \"medium\",\n          \"description\": \"\",\n          \"fields\": [\n            {\n              \"name\": \"startDate\",\n              \"type\": \"text\",\n              \"label\": \"Start date\",\n              \"importance\": \"medium\",\n              \"description\": \"YYYY,MM,DD (Minimum YYYY required)\",\n              \"regexp\": {\n                \"pattern\": \"^-?\\\\d{1,}(,(1[012]|[0]?[1-9])(,([12][0-9]|3[01]|[0]?[1-9]))?)?$\"\n              }\n            },\n            {\n              \"name\": \"endDate\",\n              \"type\": \"text\",\n              \"label\": \"End date\",\n              \"importance\": \"medium\",\n              \"description\": \"YYYY,MM,DD (Minimum YYYY required)\",\n              \"optional\": true,\n              \"regexp\": {\n                \"pattern\": \"^-?\\\\d{1,}(,(1[012]|[0]?[1-9])(,([12][0-9]|3[01]|[0]?[1-9]))?)?$\"\n              }\n            },\n            {\n              \"name\": \"headline\",\n              \"type\": \"text\",\n              \"label\": \"Headline\",\n              \"importance\": \"medium\",\n              \"description\": \"Era headline\"\n            },\n            {\n              \"name\": \"text\",\n              \"type\": \"text\",\n              \"label\": \"Text\",\n              \"importance\": \"medium\",\n              \"widget\": \"html\",\n              \"optional\": true,\n              \"description\": \"Era body\",\n              \"tags\": [\n                \"strong\",\n                \"em\",\n                \"del\",\n                \"a\",\n                \"ul\",\n                \"ol\",\n                \"hr\",\n                \"code\"\n              ]\n            },\n            {\n              \"name\": \"tag\",\n              \"type\": \"text\",\n              \"label\": \"Tag\",\n              \"importance\": \"medium\",\n              \"description\": \"Era tags (categories)\",\n              \"optional\": true\n            }\n          ]\n        }\n      },\n      {\n        \"name\": \"language\",\n        \"type\": \"select\",\n        \"label\": \"Language\",\n        \"importance\": \"medium\",\n        \"optional\": true,\n        \"description\": \"The language of the user interface\",\n        \"options\": [\n          {\n            \"value\": \"af\",\n            \"label\": \"Afrikaans\"\n          },\n          {\n            \"value\": \"ar\",\n            \"label\": \"Arabic\"\n          },\n          {\n  