(93,'H5P.PersonalityQuiz','Personality Quiz',1,0,8,1,0,'iframe','js/personalityQuiz.js, js/wheelAnimation.js','css/personalityQuiz.css','','[\n    {\n        \"name\": \"titleScreen\",\n        \"type\": \"group\",\n        \"label\": \"Title Screen\",\n        \"expanded\": true,\n        \"fields\": [\n            {\n                \"name\": \"title\",\n                \"type\": \"group\",\n                \"label\": \"Title\",\n                \"expanded\": true,\n                \"fields\": [\n                    {\n                        \"name\": \"text\",\n                        \"type\": \"text\",\n                        \"label\": \"Title\"\n                    },\n                    {\n                        \"name\": \"display\",\n                        \"type\": \"boolean\",\n                        \"label\": \"Display Title\",\n                        \"description\": \"Wether or not to show the title as a headline at the start of the personality quiz.\",\n                        \"default\": true\n                    }\n                ]\n            },\n            {\n                \"name\": \"image\",\n                \"type\": \"group\",\n                \"label\": \"Optional: Image\",\n                \"optional\": true,\n                \"fields\": [\n                    {\n                        \"name\": \"file\",\n                        \"type\": \"image\",\n                        \"label\": \"File\"\n                    },\n                    {\n                        \"name\": \"alt\",\n                        \"type\": \"text\",\n                        \"label\": \"Alt text\",\n                        \"description\": \"Alternative text if the browser is unable to load the image.\"\n                    }\n                ]\n            },\n            {\n                \"name\": \"skip\",\n                \"label\": \"Skip\",\n                \"type\": \"boolean\",\n                \"description\": \"Select if you want the quiz to start on the first question instead of the title screen.\",\n                \"default\": false\n            }\n        ]\n    },\n    {\n        \"name\": \"resultScreen\",\n        \"type\": \"group\",\n        \"label\": \"Result screen\",\n        \"fields\": [\n            {\n                \"name\": \"animation\",\n                \"type\": \"select\",\n                \"label\": \"Animation\",\n                \"description\": \"The Wheel of Fortune animation will only use the images associated with personalities if ALL personalities has an image associated with them.\",\n                \"default\": \"none\",\n                \"options\": [\n                    {\n                        \"label\": \"None\",\n                        \"value\": \"none\"\n                    },\n                    {\n                        \"label\": \"Fade in\",\n                        \"value\": \"fade-in\"\n                    },\n                    {\n                        \"label\": \"Wheel of Fortune\",\n                        \"value\": \"wheel\"\n                    }\n                ]\n            },\n            {\n                \"name\": \"displayTitle\",\n                \"type\": \"boolean\",\n                \"label\": \"Display personality title?\",\n                \"default\": true\n            },\n            {\n                \"name\": \"displayDescription\",\n                \"type\": \"boolean\",\n                \"label\": \"Display description?\",\n                \"default\": true\n            },\n            {\n                \"name\": \"imagePosition\",\n                \"type\": \"select\",\n                \"label\": \"Personality Image Position\",\n                \"description\": \"Choose how to display the image, if there is any, of the result personality. Background will fill the entire H5P container and center the image. Inline will put the image as an image element between the result personality name and description.\",\n                \"default\": \"background\",\n                \"options\": [\n                    {\n                        \"value\": \"background\",\n                        \"label\": \"Background\"\n                    },\n                    {\n                        \"value\": \"inline\",\n                        \"label\": \"Inline\"\n                    }\n                ]\n            }\n        ]\n    },\n    {\n        \"name\": \"personalities\",\n        \"type\": \"list\",\n        \"label\": \"Personality\",\n        \"entity\": \"personality\",\n        \"min\": 2,\n        \"max\": 10,\n        \"field\": {\n            \"name\": \"personality\",\n            \"type\": \"group\",\n            \"label\": \"Personality\",\n            \"fields\": [\n                {\n                    \"name\": \"name\",\n                    \"type\": \"text\",\n                    \"label\": \"Personality name\",\n                    \"description\": \"The personality name will be used to associate answers with their respective personalities.\"\n                },\n                {\n                    \"name\": \"description\",\n                    \"type\": \"text\",\n                    \"label\": \"Description\",\n                    \"maxLength\": 450,\n                    \"widget\": \"textarea\"\n                },\n                {\n                    \"name\": \"image\",\n                    \"type\": \"group\",\n                    \"label\": \"Optional: Image\",\n                    \"optional\": true,\n                    \"fields\": [\n                        {\n                            \"name\": \"file\",\n                            \"type\": \"image\",\n                            \"label\": \"Image\",\n                            \"description\": \"An image to display on the result screen.\"\n                        },\n                        {\n                            \"name\": \"alt\",\n                            \"type\": \"text\",\n                            \"label\": \"Alt text\",\n                            \"description\": \"Alternative text if the browser is unable to load the image.\"\n                        }\n                    ]\n                }\n            ]\n        }\n    },\n    {\n        \"name\": \"questions\",\n        \"type\": \"list\",\n        \"label\": \"Questions\",\n        \"entity\": \"question\",\n        \"field\": {\n            \"name\": \"question\",\n            \"type\": \"group\",\n            \"label\": \"Question\",\n            \"fields\": [\n                {\n                    \"name\": \"text\",\n                    \"type\": \"text\",\n                    \"label\": \"Question\"\n                },\n                {\n                    \"name\": \"image\",\n                    \"type\": \"group\",\n                    \"label\": \"Optional: Image\",\n                    \"description\": \"Image displayed at the top of the screen above or below the question text.\",\n                    \"optional\": true,\n                    \"fields\": [\n                        {\n                            \"name\": \"file\",\n                            \"type\": \"image\",\n                            \"label\": \"File\"\n                        },\n                        {\n                            \"name\": \"alt\",\n                            \"type\": \"text\",\n                            \"label\": \"Alt text\",\n                            \"description\": \"Alternative text if the browser is unable to load the image.\"\n                        }\n                    ]\n                },\n                {\n                    \"name\": \"answers\",\n                    \"type\": \"list\",\n                    \"label\": \"Answers\",\n                    \"entity\": \"answer\",\n                    \"min\": 2,\n                    \"max\": 6,\n                    \"field\": {\n                        \"name\": \"answer\",\n                        \"type\": \"group\",\n                        \"label\": \"Answer\",\n                        \"fields\": [\n                            {\n                                \"name\": \"text\",\n                                \"type\": \"text\",\n                                \"label\": \"text\"\n                            },\n                            {\n                                \"name\": \"personality\",\n                                \"type\": \"text\",\n                                \"label\": \"Personalities\",\n                                \"description\": \"A comma separated list of personality names associated with this answer.\"\n                            },\n                            {\n                                \"name\": \"image\",\n                                \"type\": \"group\",\n                                \"description\": \"Images associated with answers will not show up unless all answers associated with a question has an image attached.\",\n                                \"label\": \"Optional: Image\",\n                                \"optional\": true,\n                                \"fields\": [\n                                    {\n                                        \"name\": \"file\",\n                                        \"type\": \"image\",\n                                        \"label\": \"File\"\n                                    },\n                                    {\n                                        \"name\": \"alt\",\n                                        \"type\": \"text\",\n                                        \"label\": \"Alt text\",\n                                        \"description\": \"Alternative text if the browser is unable to load the image.\"\n                                    }\n                                ]\n                            }\n                        ]\n                    }\n                }\n            ]\n        }\n    },\n    {\n        \"label\": \"Start\",\n        \"name\": \"startText\",\n        \"type\": \"text\",\n        \"default\": \"Start\",\n        \"description\": \"Text displayed on the start quiz button on the title card.\"\n    },\n    {\n        \"label\": \"Progress text\",\n        \"name\": \"progressText\",\n        \"type\": \"text\",\n        \"default\": \"@question of @total\",\n        \"description\": \"Progress text, variables available: @question and @total. Example: \'@question of @total\'\"\n    },\n    {\n        \"name\": \"retakeText\",\n        \"label\": \"Retake\",\n        \"type\": \"text\",\n        \"default\": \"Retake the quiz\",\n        \"description\": \"Retake text\"\n    },\n    {\n        \"name\": \"animation\",\n        \"type\": \"boolean\",\n        \"label\": \"Animation\",\n        \"default\": true,\n        \"description\": \"Uncheck to turn off all animation\"\n    },\n    {\n        \"name\": \"buttonColor\",\n        \"type\": \"text\",\n        \"label\": \"Button Accent\",\n        \"description\": \"Change the color of the button borders and the animation color fill\",\n        \"default\": \"4D5DAA\",\n        \"widget\": \"colorSelector\"\n    },\n    {\n        \"name\": \"progressbarColor\",\n        \"type\": \"text\",\n        \"label\": \"Progressbar Color\",\n        \"description\": \"Determines the color of the progress bar\",\n        \"default\": \"38B755\",\n        \"widget\": \"colorSelector\"\n    }\n]\n',NULL,NULL,NULL,NULL,NULL,'https://h5p.org/personality-quiz',1),
(94,'H5P.AdvancedBlanks','Complex fill the blanks',1,2,7,1,0,'iframe','dist/ractive.min.js, dist/h5p-advanced-blanks.js','','','[\n  {\n    \"name\": \"media\",\n    \"type\": \"group\",\n    \"label\": \"Media\",\n    \"importance\": \"medium\",\n    \"fields\": [\n      {\n        \"name\": \"type\",\n        \"type\": \"library\",\n        \"label\": \"Type\",\n        \"options\": [\n          \"H5P.Image 1.1\",\n          \"H5P.Video 1.6\"\n        ],\n        \"optional\": true,\n        \"description\": \"Optional media to display above the question.\"\n      },\n      {\n        \"label\": \"Disable image zooming for question image\",\n        \"importance\": \"low\",\n        \"name\": \"disableImageZooming\",\n        \"type\": \"boolean\",\n        \"default\": false,\n        \"optional\": true,\n        \"widget\": \"showWhen\",\n        \"showWhen\": {\n          \"rules\": [\n            {\n              \"field\": \"type\",\n              \"equals\": \"H5P.Image 1.1\"\n            }\n          ]\n        }\n      }\n    ]\n  },\n  {\n    \"name\": \"content\",\n    \"type\": \"group\",\n    \"label\": \"Blank content\",\n    \"importance\": \"medium\",\n    \"expanded\": true,\n    \"fields\": [\n      {\n        \"label\": \"Task description\",\n        \"importance\": \"high\",\n        \"name\": \"task\",\n        \"type\": \"text\",\n        \"widget\": \"html\",\n        \"default\": \"Fill in the missing words.\",\n        \"description\": \"A guide telling the user how to answer this task.\",\n        \"enterMode\": \"p\",\n        \"tags\": [\n          \"strong\",\n          \"em\",\n          \"u\",\n          \"a\",\n          \"ul\",\n          \"ol\",\n          \"h1\",\n          \"h2\",\n          \"h3\",\n          \"hr\"\n        ]\n      },\n      {\n        \"name\": \"blanksText\",\n        \"type\": \"text\",\n        \"widget\": \"html\",\n        \"label\": \"Text with blanks\",\n        \"importance\": \"high\",\n        \"enterMode\": \"p\",\n        \"important\": {\n          \"description\": \"<ul><li>Blanks must be marked with __________ (three or more underscores).</li><li>Do not put the solutions into the text.</li></ul>\",\n          \"example\": \"I have _________ wanted to visit Norway.\"\n        },\n        \"tags\": [\n          \"strong\",\n          \"em\",\n          \"u\",\n          \"strike\",\n          \"ul\",\n          \"ol\",\n          \"table\",\n          \"h1\",\n          \"h2\",\n          \"h3\",\n          \"hr\",\n          \"sub\",\n          \"sup\"\n        ],\n        \"font\": {\n          \"size\": true,\n          \"family\": true,\n          \"color\": true,\n          \"background\": true\n        }\n      },\n      {\n        \"name\": \"blanksList\",\n        \"type\": \"list\",\n        \"label\": \"Blanks used in the text\",\n        \"importance\": \"high\",\n        \"entity\": \"blank\",\n        \"min\": 1,\n        \"widgets\": [\n          {\n            \"name\": \"VerticalTabs\",\n            \"label\": \"Default\"\n          }\n        ],\n        \"field\": {\n          \"name\": \"blankGroup\",\n          \"type\": \"group\",\n          \"label\": \"Blank\",\n          \"fields\": [\n            {\n              \"name\": \"correctAnswerText\",\n              \"type\": \"text\",\n              \"label\": \"Correct answer\",\n              \"description\": \"You can separate alternative answers with a slash (/).\"\n            },\n            {\n              \"name\": \"hint\",\n              \"type\": \"text\",\n              \"label\": \"Hint\",\n              \"optional\": true\n            },\n            {\n              \"name\": \"incorrectAnswersList\",\n              \"type\": \"list\",\n              \"label\": \"Incorrect answers\",\n              \"entity\": \"incorrect answer\",\n              \"optional\": true,\n              \"min\": 0,\n              \"field\": {\n                \"name\": \"incorrectAnswerGroup\",\n                \"type\": \"group\",\n                \"label\": \"Incorrect answer\",\n                \"description\": \"You can separate alternative answers with a slash (/).\",\n                \"fields\": [\n                  {\n                    \"name\": \"incorrectAnswerText\",\n                    \"type\": \"text\",\n                    \"label\": \"Incorrect answer text\"\n                  },\n                  {\n                    \"name\": \"incorrectAnswerFeedback\",\n                    \"type\": \"text\",\n                    \"label\": \"Feedback\",\n                    \"optional\": true,\n                    \"description\": \"The feedback should help the user find the correct answer and ideally be tailored to the answer the user has entered.\",\n                    \"widget\": \"html\",\n                    \"tags\": [\n                      \"strong\",\n                      \"em\",\n                      \"u\",\n                      \"a\",\n                      \"ul\",\n                      \"ol\",\n                      \"sub\",\n                      \"sup\"\n                    ]\n                  },\n                  {\n                    \"name\": \"showHighlight\",\n                    \"type\": \"boolean\",\n                    \"label\": \"Show highlight in the text when feedback is shown\",\n                    \"description\": \"Put !! before and after a piece of text to mark it as a highlight. (e.g. This is !!a highlight!!)\",\n                    \"default\": false,\n                    \"optional\": false\n                  },\n                  {\n                    \"name\": \"highlight\",\n                    \"type\": \"select\",\n                    \"label\": \"Highlight position relative to blank:\",\n                    \"widget\": \"showWhen\",\n                    \"showWhen\": {\n                      \"rules\": [\n                        {\n                          \"field\": \"showHighlight\",\n                          \"equals\": true\n                        }\n                      ]\n                    },\n                    \"options\": [\n                      {\n                        \"value\": \"-1\",\n                        \"label\": \"- 1 (right before the blank)\"\n                      },\n                      {\n                        \"value\": \"-2\",\n                        \"label\": \"- 2 (two highlights before the blank)\"\n                      },\n                      {\n                        \"value\": \"-3\",\n                        \"label\": \"- 3 (three highlights before the blank)\"\n                      },\n                      {\n                        \"value\": \"1\",\n                        \"label\": \"+ 1 (right after the blank)\"\n                      },\n                      {\n                        \"value\": \"2\",\n                        \"label\": \"+ 2 (two highlights after the blank)\"\n                      },\n                      {\n                        \"value\": \"3\",\n                        \"label\": \"+ 3 (three highlights after the blank)\"\n                      }\n                    ],\n                    \"default\": \"-1\"\n                  }\n                ]\n              }\n            }\n          ]\n        }\n      }\n    ]\n  },\n  {\n    \"name\": \"snippets\",\n    \"type\": \"group\",\n    \"label\": \"Snippets\",\n    \"importance\": \"medium\",\n    \"fields\": [\n      {\n        \"name\": \"list\",\n        \"type\": \"list\",\n        \"label\": \"Snippet list\",\n        \"importance\": \"high\",\n        \"description\": \"Snippets are texts that can be reused in feedback texts by inserting @snippetname into the it.\",\n        \"entity\": \"snippet\",\n        \"optional\": true,\n        \"min\": 0,\n        \"field\": {\n          \"name\": \"snippetGroup\",\n          \"type\": \"group\",\n          \"label\": \"Snippet\",\n          \"fields\": [\n            {\n              \"name\": \"snippetName\",\n              \"type\": \"text\",\n              \"label\": \"Name\",\n              \"description\": \"You can only use letters and numbers for the snippet name.\",\n              \"regexp\": {\n                \"pattern\": \"^[\\\\w\\\\d]*$\"\n              }\n            },\n            {\n              \"name\": \"snippetText\",\n              \"type\": \"text\",\n              \"label\": \"Text\",\n              \"widget\": \"html\",\n              \"tags\": [\n                \"strong\",\n                \"em\",\n                \"u\",\n                \"a\",\n                \"ul\",\n                \"ol\",\n                \"sub\",\n                \"sup\"\n              ]\n            }\n          ]\n        }\n      }\n    ]\n  },\n  {\n    \"name\": \"overallFeedback\",\n    \"type\": \"group\",\n    \"label\": \"Overall Feedback\",\n    \"importance\": \"low\",\n    \"expanded\": true,\n    \"fields\": [\n      {\n        \"name\": \"overallFeedback\",\n        \"type\": \"list\",\n        \"widgets\": [\n          {\n            \"name\": \"RangeList\",\n            \"label\": \"Default\"\n          }\n        ],\n        \"importance\": \"high\",\n        \"label\": \"Define custom feedback for any score range\",\n        \"description\": \"Click the \\\"Add range\\\" button to add as many ranges as you need. Example: 0-20% Bad score, 21-91% Average Score, 91-100% Great Score!\",\n        \"entity\": \"range\",\n        \"min\": 1,\n        \"defaultNum\": 1,\n        \"optional\": true,\n        \"field\": {\n          \"name\": \"overallFeedback\",\n          \"type\": \"group\",\n          \"importance\": \"low\",\n          \"fields\": [\n            {\n              \"name\": \"from\",\n              \"type\": \"number\",\n              \"label\": \"Score Range\",\n              \"min\": 0,\n              \"max\": 100,\n              \"default\": 0,\n              \"unit\": \"%\"\n            },\n            {\n              \"name\": \"to\",\n              \"type\": \"number\",\n              \"min\": 0,\n              \"max\": 100,\n              \"default\": 100,\n              \"unit\": \"%\"\n            },\n            {\n              \"name\": \"feedback\",\n              \"type\": \"text\",\n              \"label\": \"Feedback for defined score range\",\n              \"importance\": \"low\",\n              \"placeholder\": \"Fill in the feedback\",\n              \"optional\": true\n            }\n          ]\n        }\n      }\n    ]\n  },\n  {\n    \"name\": \"behaviour\",\n    \"type\": \"group\",\n    \"label\": \"Behavioural settings\",\n    \"importance\": \"low\",\n    \"description\": \"These options will let you control how the task behaves.\",\n    \"optional\": false,\n    \"fields\": [\n      {\n        \"name\": \"mode\",\n        \"type\": \"select\",\n        \"label\": \"Answer mode\",\n        \"description\": \"Indicates in what way the user gives answers.\",\n        \"optional\": false,\n        \"options\": [\n          {\n            \"value\": \"selection\",\n            \"label\": \"The users selects from options.\"\n          },\n          {\n            \"value\": \"typing\",\n            \"label\": \"The users types in the answers.\"\n          }\n        ],\n        \"default\": \"typing\"\n      },\n      {\n        \"name\": \"selectAlternatives\",\n        \"type\": \"select\",\n        \"label\": \"Alternatives offered for selection\",\n        \"optional\": false,\n        \"widget\": \"showWhen\",\n        \"showWhen\": {\n          \"rules\": [\n            {\n              \"field\": \"mode\",\n              \"equals\": \"selection\"\n            }\n          ]\n        },\n        \"options\": [\n          {\n            \"value\": \"alternatives\",\n            \"label\": \"The incorrect answers entered for the blank\"\n          },\n          {\n            \"value\": \"all\",\n            \"label\": \"The correct answers of all other blanks\"\n          }\n        ],\n        \"default\": \"alternatives\"\n      },\n      {\n        \"name\": \"selectAlternativeRestriction\",\n        \"type\": \"number\",\n        \"label\": \"Maximum number of alternatives of other blanks offered for selection\",\n        \"description\": \"Enter 0 to set no limit.\",\n        \"min\": 0,\n        \"step\": 1,\n        \"default\": 5,\n        \"widget\": \"showWhen\",\n        \"showWhen\": {\n          \"rules\": [\n            {\n              \"field\": \"mode\",\n              \"equals\": \"selection\"\n            }\n          ]\n        }\n      },\n      {\n        \"name\": \"spellingErrorBehaviour\",\n        \"type\": \"select\",\n        \"label\": \"Behaviour when user makes a spelling error\",\n        \"importance\": \"low\",\n        \"options\": [\n          {\n            \"value\": \"accept\",\n            \"label\": \"Accept it as a correct answer\"\n          },\n          {\n            \"value\": \"warn\",\n            \"label\": \"Warn the user about the error\"\n          },\n          {\n            \"value\": \"mistake\",\n            \"label\": \"Consider it a regular mistake\"\n          }\n        ],\n        \"default\": \"mistake\",\n        \"widget\": \"showWhen\",\n        \"showWhen\": {\n          \"rules\": [\n            {\n              \"field\": \"mode\",\n              \"equals\": \"typing\"\n            }\n          ]\n        }\n      },\n      {\n        \"name\": \"caseSensitive\",\n        \"importance\": \"low\",\n        \"type\": \"boolean\",\n        \"default\": false,\n        \"label\": \"Case sensitive\",\n        \"description\": \"If enabled, capitalization that is different from the solution is considered an error.\",\n        \"widget\": \"showWhen\",\n        \"showWhen\": {\n          \"rules\": [\n            {\n              \"field\": \"mode\",\n              \"equals\": \"typing\"\n            }\n          ]\n        }\n      },\n      {\n        \"label\": \"Automatically check answers after input\",\n        \"importance\": \"low\",\n        \"name\": \"autoCheck\",\n        \"type\": \"boolean\",\n        \"default\": false,\n        \"optional\": true\n      },\n      {\n        \"label\": \"Enable \\\"Show solutions\\\" button\",\n        \"importance\": \"low\",\n        \"name\": \"enableSolutionsButton\",\n        \"type\": \"boolean\",\n        \"default\": true,\n        \"optional\": true\n      },\n      {\n        \"label\": \"Require all fields to be answered before the solution can be viewed\",\n        \"importance\": \"low\",\n        \"name\": \"showSolutionsRequiresInput\",\n        \"type\": \"boolean\",\n        \"default\": true,\n        \"optional\": true\n      },\n      {\n        \"label\": \"Enable \\\"Retry\\\"\",\n        \"importance\": \"low\",\n        \"name\": \"enableRetry\",\n        \"type\": \"boolean\",\n        \"default\": true,\n        \"optional\": true\n      },\n      {\n        \"name\": \"enableCheckButton\",\n        \"type\": \"boolean\",\n        \"label\": \"Enable \\\"Check\\\" button\",\n        \"widget\": \"none\",\n        \"importance\": \"low\",\n        \"default\": true,\n        \"optional\": true\n      },\n      {\n        \"label\": \"Show confirmation dialog on \\\"Check\\\"\",\n        \"importance\": \"low\",\n        \"name\": \"confirmCheckDialog\",\n        \"type\": \"boolean\",\n        \"default\": false\n      },\n      {\n        \"label\": \"Show confirmation dialog on \\\"Retry\\\"\",\n        \"importance\": \"low\",\n        \"name\": \"confirmRetryDialog\",\n        \"type\": \"boolean\",\n        \"default\": false\n      }\n    ]\n  },\n  {\n    \"label\": \"Text for \\\"Show solutions\\\" button\",\n    \"name\": \"showSolutions\",\n    \"type\": \"text\",\n    \"default\": \"Show solution\",\n    \"common\": true,\n    \"optional\": true\n  },\n  {\n    \"label\": \"Text for \\\"Retry\\\" button\",\n    \"importance\": \"low\",\n    \"name\": \"tryAgain\",\n    \"type\": \"text\",\n    \"default\": \"Retry\",\n    \"common\": true,\n    \"optional\": true\n  },\n  {\n    \"label\": \"Text for \\\"Check\\\" button\",\n    \"importance\": \"low\",\n    \"name\": \"checkAnswer\",\n    \"type\": \"text\",\n    \"default\": \"Check\",\n    \"common\": true,\n    \"optional\": true\n  },\n  {\n    \"label\": \"Text for \\\"Submit\\\" button\",\n    \"importance\": \"low\",\n    \"name\": \"submitAnswer\",\n    \"type\": \"text\",\n    \"default\": \"Submit\",\n    \"common\": true,\n    \"optional\": true\n  },\n  {\n    \"label\": \"Text for \\\"Not filled out\\\" message\",\n    \"importance\": \"low\",\n    \"name\": \"notFilledOut\",\n    \"type\": \"text\",\n    \"default\": \"Please fill in all blanks to view solution\",\n    \"common\": true,\n    \"optional\": true\n  },\n  {\n    \"label\": \"Tip icon label\",\n    \"importance\": \"low\",\n    \"name\": \"tipLabel\",\n    \"type\": \"text\",\n    \"default\": \"Tip\",\n    \"common\": true,\n    \"optional\": true\n  },\n  {\n    \"label\": \"Spelling mistake warning\",\n    \"description\": \"This is the message shown to users when they make a spelling mistake. Insert @mistake to show them what they did wrong.\",\n    \"importance\": \"low\",\n    \"name\": \"spellingMistakeWarning\",\n    \"type\": \"text\",\n    \"default\": \"Check your spelling: @mistake\",\n    \"common\": true,\n    \"optional\": true\n  },\n  {\n    \"label\": \"Check confirmation dialog\",\n    \"importance\": \"low\",\n    \"name\": \"confirmCheck\",\n    \"type\": \"group\",\n    \"common\": true,\n    \"fields\": [\n      {\n        \"label\": \"Header text\",\n        \"importance\": \"low\",\n        \"name\": \"header\",\n        \"type\": \"text\",\n        \"default\": \"Finish?\"\n      },\n      {\n        \"label\": \"Body text\",\n        \"importance\": \"low\",\n        \"name\": \"body\",\n        \"type\": \"text\",\n        \"default\": \"Are you sure you wish to finish?\",\n        \"widget\": \"html\",\n        \"enterMode\": \"p\",\n        \"tags\": [\n          \"strong\",\n          \"em\",\n          \"del\",\n          \"u\"\n        ]\n      },\n      {\n        \"label\": \"Cancel button label\",\n        \"importance\": \"low\",\n        \"name\": \"cancelLabel\",\n        \"type\": \"text\",\n        \"default\": \"Cancel\"\n      },\n      {\n        \"label\": \"Confirm button label\",\n        \"importance\": \"low\",\n        \"name\": \"confirmLabel\",\n        \"type\": \"text\",\n        \"default\": \"Finish\"\n      }\n    ]\n  },\n  {\n    \"label\": \"Retry confirmation dialog\",\n    \"importance\": \"low\",\n    \"name\": \"confirmRetry\",\n    \"type\": \"group\",\n    \"common\": true,\n    \"fields\": [\n      {\n        \"label\": \"Header text\",\n        \"importance\": \"low\",\n        \"name\": \"header\",\n        \"type\": \"text\",\n        \"default\": \"Retry?\"\n      },\n      {\n        \"label\": \"Body text\",\n        \"importance\": \"low\",\n        \"name\": \"body\",\n        \"type\": \"text\",\n        \"default\": \"Are you sure you wish to retry?\",\n        \"widget\": \"html\",\n        \"enterMode\": \"p\",\n        \"tags\": [\n          \"strong\",\n          \"em\",\n          \"del\",\n          \"u\"\n        ]\n      },\n      {\n        \"label\": \"Cancel button label\",\n        \"importance\": \"low\",\n        \"name\": \"cancelLabel\",\n        \"type\": \"text\",\n        \"default\": \"Cancel\"\n      },\n      {\n        \"label\": \"Confirm button label\",\n        \"importance\": \"low\",\n        \"name\": \"confirmLabel\",\n        \"type\": \"text\",\n        \"default\": \"Confirm\"\n      }\n    ]\n  },\n  {\n    \"name\": \"scoreBarLabel\",\n    \"type\": \"text\",\n    \"label\": \"Textual representation of the score bar for those using a readspeaker\",\n    \"default\": \"You got :num out of :