(124,'H5P.KewArCode','KewAr Code',1,2,2,1,0,'iframe','dist/h5p-kewar-code.js','dist/h5p-kewar-code.css','','[\n  {\n    \"name\": \"introduction\",\n    \"type\": \"text\",\n    \"widget\": \"html\",\n    \"label\": \"Introductory text\",\n    \"importance\": \"medium\",\n    \"optional\": true,\n    \"description\": \"This text can optionally be presented along with your code.\",\n    \"enterMode\": \"div\",\n    \"tags\": [\n      \"sub\",\n      \"sup\",\n      \"strong\",\n      \"em\",\n      \"p\",\n      \"code\",\n      \"u\",\n      \"del\",\n      \"a\",\n      \"ul\",\n      \"ol\",\n      \"h1\",\n      \"h2\",\n      \"h3\",\n      \"h4\",\n      \"h5\",\n      \"h6\",\n      \"pre\",\n      \"hr\",\n      \"table\"\n    ],\n    \"font\": {\n      \"size\": true,\n      \"color\": true,\n      \"background\": true\n    }\n  },\n  {\n    \"name\": \"codeType\",\n    \"type\": \"select\",\n    \"label\": \"Code type\",\n    \"description\": \"Select what kind of code you want to generate\",\n    \"options\": [\n      {\n        \"value\": \"contact\",\n        \"label\": \"Contact\"\n      },\n      {\n        \"value\": \"event\",\n        \"label\": \"Event\"\n      },\n      {\n        \"value\": \"email\",\n        \"label\": \"Email address\"\n      },\n      {\n        \"value\": \"h5p\",\n        \"label\": \"H5P\"\n      },\n      {\n        \"value\": \"location\",\n        \"label\": \"Location\"\n      },\n      {\n        \"value\": \"phone\",\n        \"label\": \"Phone number\"\n      },\n      {\n        \"value\": \"sms\",\n        \"label\": \"SMS\"\n      },\n      {\n        \"value\": \"text\",\n        \"label\": \"Text\"\n      },\n      {\n        \"value\": \"url\",\n        \"label\": \"URL\"\n      }\n    ],\n    \"default\": \"url\",\n    \"widget\": \"editorKewArCode\"\n  },\n  {\n    \"name\": \"contact\",\n    \"type\": \"group\",\n    \"label\": \"Contact\",\n    \"importance\": \"high\",\n    \"expanded\": true,\n    \"fields\": [\n      {\n        \"name\": \"name\",\n        \"type\": \"text\",\n        \"label\": \"Name\",\n        \"placeholder\": \"John Smith\",\n        \"maxLength\": 150\n      },\n      {\n        \"name\": \"organization\",\n        \"type\": \"text\",\n        \"label\": \"Organization\",\n        \"placeholder\": \"H5P fan club\",\n        \"optional\": true,\n        \"maxLength\": 150\n      },\n      {\n        \"name\": \"title\",\n        \"type\": \"text\",\n        \"label\": \"Title\",\n        \"placeholder\": \"Master of None\",\n        \"optional\": true,\n        \"maxLength\": 100\n      },\n      {\n        \"name\": \"number\",\n        \"type\": \"text\",\n        \"label\": \"Phone number\",\n        \"description\": \"Phone number (please use the format +12 345 67890)\",\n        \"placeholder\": \"+12 345 67890\",\n        \"optional\": true,\n        \"regexp\": {\n          \"pattern\": \"^\\\\+[0-9]{1,3}[\\\\ ]?[0-9]{1,4}[\\\\ ]?[0-9]{1,8}$\",\n          \"modifiers\": \"\"\n        }\n      },\n      {\n        \"name\": \"email\",\n        \"type\": \"text\",\n        \"label\": \"Email address\",\n        \"description\": \"Email address to write message to\",\n        \"placeholder\": \"john@fictional-h5p-fan-club.org\",\n        \"optional\": true,\n        \"maxLength\": 150,\n        \"regexp\": {\n          \"pattern\": \"^[A-Z0-9\\\\._%+-]+@[A-Z0-9.-]+\\\\.[A-Z]{2,}$\",\n          \"modifiers\": \"i\"\n        }\n      },\n      {\n        \"name\": \"address\",\n        \"type\": \"group\",\n        \"label\": \"Address\",\n        \"importance\": \"medium\",\n        \"expanded\": true,\n        \"fields\": [\n          {\n            \"name\": \"extended\",\n            \"type\": \"text\",\n            \"label\": \"Extended address\",\n            \"description\": \"c/o information, etc.\",\n            \"placeholder\": \"c/o H5P Fan Club\",\n            \"optional\": true,\n            \"maxLength\": 150\n          },\n          {\n            \"name\": \"street\",\n            \"type\": \"text\",\n            \"label\": \"Street\",\n            \"description\": \"Street including number\",\n            \"placeholder\": \"1308 W. Dayton Street\",\n            \"optional\": true,\n            \"maxLength\": 150\n          },\n          {\n            \"name\": \"locality\",\n            \"type\": \"text\",\n            \"label\": \"Locality\",\n            \"description\": \"City name, etc.\",\n            \"placeholder\": \"Madison\",\n            \"optional\": true,\n            \"maxLength\": 100\n          },\n          {\n            \"name\": \"region\",\n            \"type\": \"text\",\n            \"label\": \"Region\",\n            \"description\": \"Federal state, county, etc.\",\n            \"placeholder\": \"WI\",\n            \"optional\": true,\n            \"maxLength\": 100\n          },\n          {\n            \"name\": \"zip\",\n            \"type\": \"text\",\n            \"label\": \"ZIP code\",\n            \"description\": \"ZIP code\",\n            \"placeholder\": \"53715\",\n            \"optional\": true,\n            \"maxLength\": 50\n          },\n          {\n            \"name\": \"country\",\n            \"type\": \"text\",\n            \"label\": \"Country\",\n            \"description\": \"Country\",\n            \"placeholder\": \"USA\",\n            \"optional\": true,\n            \"maxLength\": 100\n          }\n        ]\n      },\n      {\n        \"name\": \"url\",\n        \"type\": \"text\",\n        \"label\": \"Website\",\n        \"description\": \"Website to link to (must start with https:// or http://)\",\n        \"placeholder\": \"https://fictional-h5p-fan-club.org\",\n        \"regexp\": {\n          \"pattern\": \"https?://([0-9a-z.-]+).[a-z.]{2,}([0-9a-z.-_]*)*/?\",\n          \"modifiers\": \"i\"\n        },\n        \"optional\": true,\n        \"maxLength\": 300\n      },\n      {\n        \"name\": \"note\",\n        \"type\": \"text\",\n        \"label\": \"Note\",\n        \"description\": \"Note\",\n        \"placeholder\": \"John loves H5P.\",\n        \"optional\": true,\n        \"maxLength\": 500\n      }\n    ],\n    \"widget\": \"showWhen\",\n    \"showWhen\": {\n      \"rules\": [\n        {\n          \"field\": \"codeType\",\n          \"equals\": \"contact\"\n        }\n      ]\n    }\n  },\n  {\n    \"name\": \"event\",\n    \"type\": \"group\",\n    \"label\": \"Event\",\n    \"importance\": \"high\",\n    \"expanded\": true,\n    \"fields\": [\n      {\n        \"name\": \"title\",\n        \"type\": \"text\",\n        \"label\": \"Title\",\n        \"description\": \"Title for the calendar event\",\n        \"placeholder\": \"H5P Conference 2020\",\n        \"maxLength\": 200\n      },\n      {\n        \"name\": \"allDay\",\n        \"type\": \"boolean\",\n        \"label\": \"All day event\",\n        \"description\": \"Check if event will be valid all day long\"\n      },\n      {\n        \"name\": \"dateStart\",\n        \"type\": \"text\",\n        \"label\": \"Start date\",\n        \"description\": \"Start date of the event (please use the format yyyy/mm/dd)\",\n        \"placeholder\": \"2020/05/18\",\n        \"regexp\": {\n          \"pattern\": \"^[0-9]{4,}/0*([1-9]|1[0-2])/0*([1-9]|[12][0-9]|3[01])$\",\n          \"modifiers\": \"\"\n        }\n      },\n      {\n        \"name\": \"timeStart\",\n        \"type\": \"text\",\n        \"label\": \"Start time\",\n        \"description\": \"Start time of the event (please use the format hh:mm)\",\n        \"placeholder\": \"09:00\",\n        \"regexp\": {\n          \"pattern\": \"^0*([1-9]|1[0-9]|2[0-3]):0*([0-9]|[1-4][0-9]|5[0-9])$\",\n          \"modifiers\": \"\"\n        },\n        \"widget\": \"showWhen\",\n        \"showWhen\": {\n          \"rules\": [\n            {\n              \"field\": \"allDay\",\n              \"equals\": false\n            }\n          ]\n        }\n      },\n      {\n        \"name\": \"dateEnd\",\n        \"type\": \"text\",\n        \"label\": \"End date\",\n        \"description\": \"End date of the event (please use the format yyyy/mm/dd)\",\n        \"placeholder\": \"2020/05/20\",\n        \"regexp\": {\n          \"pattern\": \"^[0-9]{4,}/0*([1-9]|1[0-2])/0*([1-9]|[12][0-9]|3[01])$\",\n          \"modifiers\": \"\"\n        }\n      },\n      {\n        \"name\": \"timeEnd\",\n        \"type\": \"text\",\n        \"label\": \"End time\",\n        \"description\": \"End time of the event (please use the format hh:mm)\",\n        \"placeholder\": \"16:00\",\n        \"regexp\": {\n          \"pattern\": \"^0*([1-9]|1[0-9]|2[0-3]):0*([0-9]|[1-4][0-9]|5[0-9])$\",\n          \"modifiers\": \"\"\n        },\n        \"widget\": \"showWhen\",\n        \"showWhen\": {\n          \"rules\": [\n            {\n              \"field\": \"allDay\",\n              \"equals\": false\n            }\n          ]\n        }\n      },\n      {\n        \"name\": \"timezone\",\n        \"type\": \"select\",\n        \"label\": \"Timezone\",\n        \"description\": \"Select the time zone the event is supposed to take place in\",\n        \"options\": [\n          {\n            \"value\": \"-12:00\",\n            \"label\": \"UTC-12:00\"\n          },\n          {\n            \"value\": \"-11:00\",\n            \"label\": \"UTC-11:00\"\n          },\n          {\n            \"value\": \"-10:00\",\n            \"label\": \"UTC-10:00\"\n          },\n          {\n            \"value\": \"-9:30\",\n            \"label\": \"UTC-9:30\"\n          },\n          {\n            \"value\": \"-9:00\",\n            \"label\": \"UTC-9:00\"\n          },\n          {\n            \"value\": \"-8:00\",\n            \"label\": \"UTC-8:00\"\n          },\n          {\n            \"value\": \"-7:00\",\n            \"label\": \"UTC-7:00\"\n          },\n          {\n            \"value\": \"-6:00\",\n            \"label\": \"UTC-6:00\"\n          },\n          