(151,'H5P.InteractiveVideo','Interactive Video',1,27,9,1,1,'iframe','dist/h5p-interactive-video.js','dist/h5p-interactive-video.css','','[\n  {\n    \"name\": \"interactiveVideo\",\n    \"type\": \"group\",\n    \"widget\": \"wizard\",\n    \"label\": \"Interactive Video Editor\",\n    \"importance\": \"high\",\n    \"fields\": [\n      {\n        \"name\": \"video\",\n        \"type\": \"group\",\n        \"label\": \"Upload/embed video\",\n        \"importance\": \"high\",\n        \"fields\": [\n          {\n            \"name\": \"files\",\n            \"type\": \"video\",\n            \"label\": \"Add a video\",\n            \"importance\": \"high\",\n            \"description\": \"Click below to add a video you wish to use in your interactive video. You can add a video link or upload video files. It is possible to add several versions of the video with different qualities. To ensure maximum support in browsers at least add a version in webm and mp4 formats.\",\n            \"extraAttributes\": [\n              \"metadata\"\n            ],\n            \"enableCustomQualityLabel\": true\n          },\n          {\n            \"name\": \"startScreenOptions\",\n            \"type\": \"group\",\n            \"label\": \"Start screen options (unsupported for YouTube videos)\",\n            \"importance\": \"low\",\n            \"fields\": [\n              {\n                \"name\": \"title\",\n                \"type\": \"text\",\n                \"label\": \"The title of this interactive video\",\n                \"importance\": \"low\",\n                \"maxLength\": 60,\n                \"default\": \"Interactive Video\",\n                \"description\": \"Used in summaries, statistics etc.\"\n              },\n              {\n                \"name\": \"hideStartTitle\",\n                \"type\": \"boolean\",\n                \"label\": \"Hide title on video start screen\",\n                \"importance\": \"low\",\n                \"optional\": true,\n                \"default\": false\n              },\n              {\n                \"name\": \"shortStartDescription\",\n                \"type\": \"text\",\n                \"label\": \"Short description (Optional)\",\n                \"importance\": \"low\",\n                \"optional\": true,\n                \"maxLength\": 120,\n                \"description\": \"Optional. Display a short description text on the video start screen. Does not work for YouTube videos.\"\n              },\n              {\n                \"name\": \"poster\",\n                \"type\": \"image\",\n                \"label\": \"Poster image\",\n                \"importance\": \"low\",\n                \"optional\": true,\n                \"description\": \"Image displayed before the user launches the video. Does not work for YouTube Videos.\"\n              }\n            ]\n          },\n          {\n            \"name\": \"textTracks\",\n            \"type\": \"group\",\n            \"label\": \"Text tracks (unsupported for YouTube videos)\",\n            \"importance\": \"low\",\n            \"fields\": [\n              {\n                \"name\": \"videoTrack\",\n                \"type\": \"list\",\n                \"label\": \"Available text tracks\",\n                \"importance\": \"low\",\n                \"optional\": true,\n                \"entity\": \"Track\",\n                \"min\": 0,\n                \"defaultNum\": 1,\n                \"field\": {\n                  \"name\": \"track\",\n                  \"type\": \"group\",\n                  \"label\": \"Track\",\n                  \"importance\": \"low\",\n                  \"expanded\": false,\n                  \"fields\": [\n                    {\n                      \"name\": \"label\",\n                      \"type\": \"text\",\n                      \"label\": \"Track label\",\n                      \"description\": \"Used if you offer multiple tracks and the user has to choose a track. For instance \'Spanish subtitles\' could be the label of a Spanish subtitle track.\",\n                      \"importance\": \"low\",\n                      \"default\": \"Subtitles\",\n                      \"optional\": true\n                    },\n                    {\n                      \"name\": \"kind\",\n                      \"type\": \"select\",\n                      \"label\": \"Type of text track\",\n                      \"importance\": \"low\",\n                      \"default\": \"subtitles\",\n                      \"options\": [\n                        {\n                          \"value\": \"subtitles\",\n                          \"label\": \"Subtitles\"\n                        },\n                        {\n                          \"value\": \"captions\",\n                          \"label\": \"Captions\"\n                        },\n                        {\n                          \"value\": \"descriptions\",\n                          \"label\": \"Descriptions\"\n                        }\n                      ]\n                    },\n                    {\n                      \"name\": \"srcLang\",\n                      \"type\": \"text\",\n                      \"label\": \"Source language, must be defined for subtitles\",\n                      \"importance\": \"low\",\n                      \"default\": \"en\",\n                      \"description\": \"Must be a valid BCP 47 language tag. If \'Subtitles\' is the type of text track selected, the source language of the track must be defined.\"\n                    },\n                    {\n                      \"name\": \"track\",\n                      \"type\": \"file\",\n                      \"label\": \"Track source (WebVTT file)\",\n                      \"importance\": \"low\"\n                    }\n                  ]\n                }\n              },\n              {\n                \"name\": \"defaultTrackLabel\",\n                \"type\": \"text\",\n                \"label\": \"Default text track\",\n                \"description\": \"If left empty or not matching any of the text tracks the first text track will be used as the default.\",\n                \"importance\": \"low\",\n                \"optional\": true\n              }\n            ]\n          }\n        ]\n      },\n      {\n        \"name\": \"assets\",\n        \"type\": \"group\",\n        \"label\": \"Add interactions\",\n        \"importance\": \"high\",\n        \"widget\": \"interactiveVideo\",\n        \"video\": \"video/files\",\n        \"poster\": \"video/startScreenOptions/poster\",\n        \"fields\": [\n          {\n            \"name\": \"interactions\",\n            \"type\": \"list\",\n            \"field\": {\n              \"name\": \"interaction\",\n              \"type\": \"group\",\n              \"fields\": [\n                {\n                  \"name\": \"duration\",\n                  \"type\": \"group\",\n                  \"widget\": \"duration\",\n                  \"label\": \"Display time\",\n                  \"importance\": \"low\",\n                  \"fields\": [\n                    {\n                      \"name\": \"from\",\n                      \"type\": \"number\"\n                    },\n                    {\n                      \"name\": \"to\",\n                      \"type\": \"number\"\n                    }\n                  ]\n                },\n                {\n                  \"name\": \"pause\",\n                  \"label\": \"Pause video\",\n                  \"importance\": \"low\",\n                  \"type\": \"boolean\"\n                },\n                {\n                  \"name\": \"displayType\",\n                  \"label\": \"Display as\",\n                  \"importance\": \"low\",\n                  \"description\": \"<b>Button</b> is a collapsed interaction the user must press to open. <b>Poster</b> is an expanded interaction displayed directly on top of the video\",\n                  \"type\": \"select\",\n                  \"widget\": \"imageRadioButtonGroup\",\n                  \"options\": [\n                    {\n                      \"value\": \"button\",\n                      \"label\": \"Button\"\n                    },\n                    {\n                      \"value\": \"poster\",\n                      \"label\": \"Poster\"\n                    }\n                  ],\n                  \"default\": \"button\"\n                },\n                {\n                  \"name\": \"buttonOnMobile\",\n                  \"label\": \"Turn into button on small screens\",\n                  \"importance\": \"low\",\n                  \"type\": \"boolean\",\n                  \"default\": false\n                },\n                {\n                  \"name\": \"label\",\n                  \"type\": \"text\",\n                  \"widget\": \"html\",\n                  \"label\": \"Label\",\n                  \"importance\": \"low\",\n                  \"description\": \"Label displayed next to interaction icon.\",\n                  \"optional\": true,\n                  \"enterMode\": \"p\",\n                  \"tags\": [\n                    \"p\"\n                  ]\n                },\n                {\n                  \"name\": \"x\",\n                  \"type\": \"number\",\n                  \"importance\": \"low\",\n                  \"widget\": \"none\"\n                },\n                {\n                  \"name\": \"y\",\n                  \"type\": \"number\",\n                  \"importance\": \"low\",\n                  \"widget\": \"none\"\n                },\n                {\n                  \"name\": \"width\",\n                  \"type\": \"number\",\n                  \"widget\": \"none\",\n                  \"importance\": \"low\",\n                  \"optional\": true\n                },\n                {\n                  \"name\": \"height\",\n                  \"type\": \"number\",\n                  \"widget\": \"none\",\n                  \"importance\": \"low\",\n                  \"optional\": true\n                },\n                {\n                  \"name\": \"libraryTitle\",\n                  \"type\": \"text\",\n                  \"importance\": \"low\",\n                  \"optional\": true,\n                  \"widget\": \"none\"\n                },\n                {\n                  \"name\": \"action\",\n                  \"type\": \"library\",\n                  \"importance\": \"low\",\n                  \"options\": [\n                    \"H5P.Nil 1.0\",\n                    \"H5P.Text 1.1\",\n                    \"H5P.Table 1.2\",\n                    \"H5P.Link 1.3\",\n                    \"H5P.Image 1.1\",\n                    \"H5P.Summary 1.10\",\n                    \"H5P.SingleChoiceSet 1.11\",\n                    \"H5P.MultiChoice 1.16\",\n                    \"H5P.TrueFalse 1.8\",\n                    \"H5P.Blanks 1.14\",\n                    \"H5P.DragQuestion 1.14\",\n                    \"H5P.MarkTheWords 1.11\",\n                    \"H5P.DragText 1.10\",\n                    \"H5P.GoToQuestion 1.3\",\n                    \"H5P.IVHotspot 1.2\",\n                    \"H5P.Questionnaire 1.3\",\n                    \"H5P.FreeTextQuestion 1.0\",\n                    \"H5P.MultiMediaChoice 0.3\"\n                  ]\n                },\n                {\n                  \"name\": \"adaptivity\",\n                  \"type\": \"group\",\n                  \"label\": \"Adaptivity\",\n                  \"importance\": \"low\",\n                  \"optional\": true,\n                  \"fields\": [\n                    {\n                      \"name\": \"correct\",\n                      \"type\": \"group\",\n                      \"label\": \"Action on all correct\",\n                      \"fields\": [\n                        {\n                          \"name\": \"seekTo\",\n                          \"type\": \"number\",\n                          \"widget\": \"timecode\",\n                          \"label\": \"Seek to\",\n                          \"description\": \"Enter timecode in the format M:SS\"\n                        },\n                        {\n                          \"name\": \"allowOptOut\",\n                          \"type\": \"boolean\",\n                          \"label\": \"Allow the user to opt out and continue\"\n                        },\n                        {\n                          \"name\": \"message\",\n                          \"type\": \"text\",\n                          \"widget\": \"html\",\n                          \"enterMode\": \"p\",\n                          \"tags\": [\n                            \"strong\",\n                            \"em\",\n                            \"del\",\n                            \"a\",\n                            \"code\"\n                          ],\n                          \"label\": \"Message\"\n                        },\n                        {\n                          \"name\": \"seekLabel\",\n                          \"type\": \"text\",\n                          \"label\": \"Label for seek button\"\n                        }\n                      ]\n                    },\n                    {\n                      \"name\": \"wrong\",\n                      \"type\": \"group\",\n                      \"label\": \"Action on wrong\",\n                      \"fields\": [\n                        {\n                          \"name\": \"seekTo\",\n                          \"type\": \"number\",\n                          \"widget\": \"timecode\",\n                          \"label\": \"Seek to\",\n                          \"description\": \"Enter timecode in the format M:SS\"\n                        },\n                        {\n                          \"name\": \"allowOptOut\",\n                          \"type\": \"boolean\",\n                          \"label\": \"Allow the user to opt out and continue\"\n                        },\n                        {\n                          \"name\": \"message\",\n                          \"type\": \"text\",\n                          \"widget\": \"html\",\n                          \"enterMode\": \"p\",\n                          \"tags\": [\n                            \"strong\",\n                            \"em\",\n                            \"del\",\n                            \"a\",\n                            \"code\"\n                          ],\n                          \"label\": \"Message\"\n                        },\n                        {\n                          \"name\": \"seekLabel\",\n                          \"type\": \"text\",\n                          \"label\": \"Label for seek button\"\n                        }\n                      ]\n                    },\n                    {\n                      \"name\": \"requireCompletion\",\n                      \"type\": \"boolean\",\n                      \"label\": \"Require full score for task before proceeding\",\n                      \"description\": \"For best functionality this option should be used in conjunction with the \\\"Disable navigation forward in a video\\\" option of Interactive Video.\"\n                    }\n                  ]\n                },\n                {\n                  \"name\": \"visuals\",\n                  \"label\": \"Visuals\",\n                  \"importance\": \"low\",\n                  \"type\": \"group\",\n                  \"fields\": [\n                    {\n                      \"name\": \"backgroundColor\",\n                      \"type\": \"text\",\n                      \"label\": \"Background color\",\n                      \"widget\": \"colorSelector\",\n                      \"default\": \"rgb(255, 255, 255)\",\n                      \"spectrum\": {\n                        \"showInput\": true,\n                        \"showAlpha\": true,\n                        \"preferredFormat\": \"rgb\",\n                        \"showPalette\": true,\n                        \"palette\": [\n                          [\n                            \"rgba(0, 0, 0, 0)\"\n                          ],\n                          [\n                            \"rgb(67, 67, 67)\",\n                            \"rgb(102, 102, 102)\",\n                            \"rgb(204, 204, 204)\",\n                            \"rgb(217, 217, 217)\",\n                            \"rgb(255, 255, 255)\"\n                          ],\n                          [\n                            \"rgb(152, 0, 0)\",\n                            \"rgb(255, 0, 0)\",\n                            \"rgb(255, 153, 0)\",\n                            \"rgb(255, 255, 0)\",\n                            \"rgb(0, 255, 0)\",\n                            \"rgb(0, 255, 255)\",\n                            \"rgb(74, 134, 232)\",\n                            \"rgb(0, 0, 255)\",\n                            \"rgb(153, 0, 255)\",\n                            \"rgb(255, 0, 255)\"\n                          ],\n                          [\n                            \"rgb(230, 184, 175)\",\n                            \"rgb(244, 204, 204)\",\n                            \"rgb(252, 229, 205)\",\n                            \"rgb(255, 242, 204)\",\n                            \"rgb(217, 234, 211)\",\n                            \"rgb(208, 224, 227)\",\n                            \"rgb(201, 218, 248)\",\n                            \"rgb(207, 226, 243)\",\n                            \"rgb(217, 210, 233)\",\n                            \"rgb(234, 209, 220)\",\n                            \"rgb(221, 126, 107)\",\n                            \"rgb(234, 153, 153)\",\n                            \"rgb(249, 203, 156)\",\n                            \"rgb(255, 229, 153)\",\n                            \"rgb(182, 215, 168)\",\n                            \"rgb(162, 196, 201)\",\n                            \"rgb(164, 194, 244)\",\n                            \"rgb(159, 197, 232)\",\n                            \"rgb(180, 167, 214)\",\n                            \"rgb(213, 166, 189)\",\n                            \"rgb(204, 65, 37)\",\n                            \"rgb(224, 102, 102)\",\n                            \"rgb(246, 178, 107)\",\n                            \"rgb(255, 217, 102)\",\n                            \"rgb(147, 196, 125)\",\n                            \"rgb(118, 165, 175)\",\n                            \"rgb(109, 158, 235)\",\n                            \"rgb(111, 168, 220)\",\n                            \"rgb(142, 124, 195)\",\n                            \"rgb(194, 123, 160)\",\n                            \"rgb(166, 28, 0)\",\n                            \"rgb(204, 0, 0)\",\n                            \"rgb(230, 145, 56)\",\n                            \"rgb(241, 194, 50)\",\n                            \"rgb(106, 168, 79)\",\n                            \"rgb(69, 129, 142)\",\n                            \"rgb(60, 120, 216)\",\n                            \"rgb(61, 133, 198)\",\n                            \"rgb(103, 78, 167)\",\n                            \"rgb(166, 77, 121)\",\n                            \"rgb(91, 15, 0)\",\n                            \"rgb(102, 0, 0)\",\n                            \"rgb(120, 63, 4)\",\n                            \"rgb(127, 96, 0)\",\n                            \"rgb(39, 78, 19)\",\n                            \"rgb(12, 52, 61)\",\n                            \"rgb(28, 69, 135)\",\n                            \"rgb(7, 55, 99)\",\n                            \"rgb(32, 18, 77)\",\n                            \"rgb(76, 17, 48)\"\n                          ]\n                        ]\n                      }\n                    },\n                    {\n                      \"name\": \"boxShadow\",\n                      \"type\": \"boolean\",\n                      \"label\": \"Box shadow\",\n                      \"default\": true,\n                      \"description\": \"Adds a subtle shadow around the interaction. You might want to disable this for completely transparent interactions\"\n                    }\n                  ]\n                },\n                {\n                  \"name\": \"goto\",\n                  \"label\": \"Go to on click\",\n                  \"importance\": \"low\",\n                  \"type\": \"group\",\n                  \"fields\": [\n                    {\n                      \"name\": \"type\",\n                      \"label\": \"Type\",\n                      \"type\": \"select\",\n                      \"widget\": \"selectToggleFields\",\n                      \"options\": [\n                        {\n                          \"value\": \"timecode\",\n                          \"label\": \"Timecode\",\n                          \"hideFields\": [\n                            \"url\"\n                          ]\n                        },\n                        {\n                          \"value\": \"url\",\n                          \"label\": \"Another page (URL)\",\n                          \"hideFields\": [\n                            \"time\"\n                          ]\n                        }\n                      ],\n                      \"optional\": true\n                    },\n                    {\n                      \"name\": \"time\",\n                      \"type\": \"number\",\n                      \"widget\": \"timecode\",\n                      \"label\": \"Go To\",\n                      \"description\": \"The target time the user will be taken to upon pressing the hotspot. Enter timecode in the format M:SS.\",\n                      \"optional\": true\n                    },\n                    {\n                      \"name\": \"url\",\n                      \"type\": \"group\",\n                      \"label\": \"URL\",\n                      \"widget\": \"linkWidget\",\n                      \"optional\": true,\n                      \"fields\": [\n                        {\n                          \"name\": \"protocol\",\n                          \"type\": \"select\",\n                          \"label\": \"Protocol\",\n                          \"options\": [\n                            {\n                              \"value\": \"http://\",\n                              \"label\": \"http://\"\n                            },\n                            {\n                              \"value\": \"https://\",\n                              \"label\": \"https://\"\n                            },\n                            {\n                              \"value\": \"/\",\n                              \"label\": \"(root relative)\"\n                            },\n                            {\n                              \"value\": \"other\",\n                              \"label\": \"other\"\n                            }\n                          ],\n                          \"optional\": true,\n                          \"default\": \"http://\"\n                        },\n                        {\n                          \"name\": \"url\",\n                          \"type\": \"text\",\n                          \"label\": \"URL\",\n                          \"optional\": true\n                        }\n                      ]\n                    },\n                    {\n                      \"name\": \"visualize\",\n                      \"type\": \"boolean\",\n                      \"label\": \"Visualize\",\n                      \"description\": \"Show that interaction can be clicked by adding a border and an icon\"\n                    }\n                  ]\n                }\n              ]\n            }\n          },\n          {\n            \"name\": \"bookmarks\",\n            \"importance\": \"low\",\n            \"type\": \"list\",\n            \"field\": {\n              \"name\": \"bookmark\",\n              \"type\": \"group\",\n              \"fields\": [\n                {\n                  \"name\": \"time\",\n                  \"type\": \"number\"\n                },\n                {\n                  \"name\": \"label\",\n                  \"type\": \"text\"\n                }\n              ]\n            }\n          },\n          {\n            \"name\": \"endscreens\",\n            \"importance\": \"low\",\n            \"type\": \"list\",\n            \"field\": {\n              \"name\": \"endscreen\",\n              \"type\": \"group\",\n              \"fields\": [\n                {\n                  \"name\": \"time\",\n                  \"type\": \"number\"\n                },\n                {\n                  \"name\": \"label\",\n                  \"type\": \"text\"\n                }\n              ]\n            }\n          }\n        ]\n      },\n      {\n        \"name\": \"summary\",\n        \"type\": \"group\",\n        \"label\": \"Summary task\",\n        \"importance\": \"high\",\n        \"fields\": [\n          {\n            \"name\": \"task\",\n            \"type\": \"library\",\n            \"options\": [\n              \"H5P.Summary 1.10\"\n            ],\n            \"default\": {\n              \"library\": \"H5P.Summary 1.10\",\n              \"params\": {}\n            }\n          },\n          {\n            \"name\": \"displayAt\",\n            \"type\": \"number\",\n            \"label\": \"Display at\",\n            \"description\": \"Number of seconds before the video ends.\",\n            \"default\": 3\n          }\n        ]\n      }\n    ]\n  },\n  {\n    \"name\": \"override\",\n    \"type\": \"group\",\n    \"label\": \"Behavioural settings\",\n    \"importance\": \"low\",\n    \"optional\": true,\n    \"fields\": [\n      {\n        \"name\": \"startVideoAt\",\n        \"type\": \"number\",\n        \"widget\": \"timecode\",\n        \"label\": \"Start video at\",\n        \"importance\": \"low\",\n        \"optional\": true,\n        \"description\": \"Enter timecode in the format M:SS\"\n      },\n      {\n        \"name\": \"autoplay\",\n        \"type\": \"boolean\",\n        \"label\": \"Auto-play video\",\n        \"default\": false,\n        \"optional\": true,\n        \"description\": \"Start playing the video automatically\"\n      },\n      {\n        \"name\": \"loop\",\n        \"type\": \"boolean\",\n        \"label\": \"Loop the video\",\n        \"default\": false,\n        \"optional\": true,\n        \"description\": \"Check if video should run in a loop\"\n      },\n      {\n        \"name\": \"showSolutionButton\",\n        \"type\": \"select\",\n        \"label\": \"Override \\\"Show Solution\\\" button\",\n        \"importance\": \"low\",\n        \"description\": \"This option determines if the \\\"Show Solution\\\" button will be shown for all questions, disabled for all or configured for each question individually.\",\n        \"optional\": true,\n        \"options\": [\n          {\n            \"value\": \"on\",\n            \"label\": \"Enabled\"\n          },\n          {\n            \"value\": \"off\",\n            \"label\": \"Disabled\"\n          }\n        ]\n      },\n      {\n        \"name\": \"retryButton\",\n        \"type\": \"select\",\n        \"label\": \"Override \\\"Retry\\\" button\",\n        \"importance\": \"low\",\n        \"description\": \"This option determines if the \\\"Retry\\\" button will be shown for all questions, disabled for all or configured for each question individually.\",\n        \"options\": [\n          {\n            \"value\": \"on\",\n            \"label\": \"Enabled\"\n          },\n          {\n            \"value\": \"off\",\n            \"label\": \"Disabled\"\n          }\n        ]\n      },\n      {\n        \"name\": \"showBookmarksmenuOnLoad\",\n        \"type\": \"boolean\",\n        \"label\": \"Start with bookmarks menu open\",\n        \"importance\": \"low\",\n        \"default\": false,\n        \"description\": \"This function is not available on iPad when using YouTube as video source.\"\n      },\n      {\n        \"name\": \"showRewind10\",\n        \"type\": \"boolean\",\n        \"label\": \"Show button for rewinding 10 seconds\",\n        \"importance\": \"low\",\n        \"default\": false\n      },\n      {\n        \"name\": \"preventSkippingMode\",\n        \"type\": \"select\",\n        \"label\": \"Disable navigation\",\n        \"importance\": \"low\",\n        \"description\": \"These options will disable user video navigation as specified.\",\n        \"optional\": true,\n        \"options\": [\n          {\n            \"label\": \"None\",\n            \"value\": \"none\"\n          },\n          {\n            \"label\": \"Forward\",\n            \"value\": \"forward\"\n          },\n          {\n            \"label\": \"Forward and backward\",\n            \"value\": \"both\"\n          }\n        ],\n        \"default\": \"none\"\n      },\n      {\n        \"name\": \"deactivateSound\",\n        \"type\": \"boolean\",\n        \"default\": false,\n        \"label\": \"Deactivate sound\",\n        \"importance\": \"low\",\n        \"description\": \"Enabling this option will deactivate the video\'s sound and prevent it from being switched on.\"\n      }\n    ]\n  },\n  {\n    \"name\": \"l10n\",\n    \"type\": \"group\",\n    \"label\": \"Localize\",\n    \"importance\": \"low\",\n    \"common\": true,\n    \"optional\": true,\n    \"fields\": [\n      {\n        \"name\": \"interaction\",\n        \"type\": \"text\",\n        \"label\": \"Interaction title\",\n        \"importance\": \"low\",\n        \"default\": \"Interaction\",\n        \"optional\": true\n      },\n      {\n        \"name\": \"play\",\n        \"type\": \"text\",\n        \"label\": \"Play title\",\n        \"importance\": \"low\",\n        \"default\": \"Play\",\n        \"optional\": true\n      },\n      {\n        \"name\": \"pause\",\n        \"type\": \"text\",\n        \"label\": \"Pause title\",\n        \"importance\": \"low\",\n        \"default\": \"Pause\",\n        \"optional\": true\n      },\n      {\n        \"name\": \"mute\",\n        \"type\": \"text\",\n        \"label\": \"Mute title\",\n        \"importance\": \"low\",\n        \"default\": \"Mute, currently unmuted\",\n        \"optional\": true\n      },\n      {\n        \"name\": \"unmute\",\n        \"type\": \"text\",\n        \"label\": \"Unmute title\",\n        \"importance\": \"low\",\n        \"default\": \"Unmute, currently muted\",\n        \"optional\": true\n      },\n      {\n        \"name\": \"quality\",\n        \"type\": \"text\",\n        \"label\": \"Video quality title\",\n        \"importance\": \"low\",\n        \"default\": \"Video Quality\",\n        \"optional\": true\n      },\n      {\n        \"name\": \"captions\",\n        \"type\": \"text\",\n        \"label\": \"Video captions title\",\n        \"importance\": \"low\",\n        \"default\": \"Captions\",\n        \"optional\": true\n      },\n      {\n        \"name\": \"close\",\n        \"type\": \"text\",\n        \"label\": \"Close button text\",\n        \"importance\": \"low\",\n        \"default\": \"Close\",\n        \"optional\": true\n      },\n      {\n        \"name\": \"fullscreen\",\n        \"type\": \"text\",\n        \"label\": \"Fullscreen title\",\n        \"importance\": \"low\",\n        \"default\": \"Fullscreen\",\n        \"optional\": true\n      },\n      {\n        \"name\": \"exitFullscreen\",\n        \"type\": \"text\",\n        \"label\": \"Exit fullscreen title\",\n        \"importance\": \"low\",\n        \"default\": \"Exit Fullscreen\",\n        \"optional\": true\n      },\n      {\n        \"name\": \"summary\",\n        \"type\": \"text\",\n        \"label\": \"Summary title\",\n        \"importance\": \"low\",\n        \"default\": \"Open summary dialog\",\n        \"optional\": true\n      },\n      {\n        \"name\": \"bookmarks\",\n        \"type\": \"text\",\n        \"label\": \"Bookmarks title\",\n        \"importance\": \"low\",\n        \"default\": \"Bookmarks\",\n        \"optional\": true\n      },\n      {\n        \"name\": \"endscreen\",\n        \"type\": \"text\",\n        \"label\": \"Submit screen title\",\n        \"importance\": \"low\",\n        \"default\": \"Submit screen\",\n        \"optional\": true\n      },\n      {\n        \"name\": \"defaultAdaptivitySeekLabel\",\n        \"type\": \"text\",\n        \"label\": \"Default label for adaptivity seek button\",\n        \"importance\": \"low\",\n        \"default\": \"Continue\",\n        \"optional\": true\n      },\n      {\n        \"name\": \"continueWithVideo\",\n        \"type\": \"text\",\n        \"label\": \"Default label for continue video button\",\n        \"importance\": \"low\",\n        \"default\": \"Continue with video\",\n        \"optional\": true\n      },\n      {\n        \"name\": \"more\",\n        \"type\": \"text\",\n        \"label\": \"Default label for more player options\",\n        \"importance\": \"low\",\n        \"default\": \"More player options\",\n        \"optional\": true\n      },\n      {\n        \"name\": \"playbackRate\",\n        \"type\": \"text\",\n        \"label\": \"Set playback rate\",\n        \"importance\": \"low\",\n        \"default\": \"Playback Rate\",\n        \"optional\": true\n      },\n      {\n        \"name\": \"rewind10\",\n        \"type\": \"text\",\n        \"label\": \"Rewind 10 Seconds\",\n        \"importance\": \"low\",\n        \"default\": \"Rewind 10 Seconds\",\n        \"optional\": true\n      },\n      {\n        \"name\": \"navDisabled\",\n        \"type\": \"text\",\n        \"label\": \"Navigation is disabled text\",\n        \"importance\": \"low\",\n        \"default\": \"Navigation is disabled\",\n        \"optional\": true\n      },\n      {\n        \"name\": \"navForwardDisabled\",\n        \"type\": \"text\",\n        \"label\": \"Navigating forward is disabled text\",\n        \"importance\": \"low\",\n        \"default\": \"Navigating forward is disabled\",\n        \"optional\": true\n      },\n      {\n        \"name\": \"sndDisabled\",\n        \"type\": \"text\",\n        \"label\": \"Sound is disabled text\",\n        \"importance\": \"low\",\n        \"default\": \"Sound is disabled\",\n        \"optional\": true\n      },\n      {\n        \"name\": \"requiresCompletionWarning\",\n        \"type\": \"text\",\n        \"label\": \"Warning that the user must answer the question correctly before continuing\",\n        \"importance\": \"low\",\n        \"default\": \"You need to answer all the questions correctly before continuing.\",\n        \"optional\": true\n      },\n      {\n        \"name\": \"back\",\n        \"type\": \"text\",\n        \"label\": \"Back button\",\n        \"importance\": \"low\",\n        \"default\": \"Back\",\n        \"optional\": true\n      },\n      {\n        \"name\": \"hours\",\n        \"type\": \"text\",\n        \"label\": \"Passed time hours\",\n        \"importance\": \"low\",\n        \"default\": \"Hours\",\n        \"optional\": true\n      },\n      {\n        \"name\": \"minutes\",\n        \"type\": \"text\",\n        \"label\": \"Passed time minutes\",\n        \"importance\": \"low\",\n        \"default\": \"Minutes\",\n        \"optional\": true\n      },\n      {\n        \"name\": \"seconds\",\n        \"type\": \"text\",\n        \"label\": \"Passed time seconds\",\n        \"importance\": \"low\",\n        \"default\": \"Seconds\",\n        \"optional\": true\n      },\n      {\n        \"name\": \"currentTime\",\n        \"type\": \"text\",\n        \"label\": \"Label for current time\",\n        \"importance\": \"low\",\n        \"default\": \"Current time:\",\n        \"optional\": true\n      },\n      {\n        \"name\": \"totalTime\",\n        \"type\": \"text\",\n        \"label\": \"Label for total time\",\n        \"importance\": \"low\",\n        \"default\": \"Total time:\",\n        \"optional\": true\n      },\n      {\n        \"name\": \"singleInteractionAnnouncement\",\n        \"type\": \"text\",\n        \"label\": \"Text explaining that a single interaction with a name has come into view\",\n        \"importance\": \"low\",\n        \"default\": \"Interaction appeared:\",\n        \"optional\": true\n      },\n      {\n        \"name\": \"multipleInteractionsAnnouncement\",\n        \"type\": \"text\",\n        \"label\": \"Text for explaining that multiple interactions have come into view\",\n        \"importance\": \"low\",\n        \"default\": \"Multiple interactions appeared.\",\n        \"optional\": true\n      },\n      {\n        \"name\": \"videoPausedAnnouncement\",\n        \"type\": \"text\",\n        \"label\": \"Video is paused announcement\",\n        \"importance\": \"low\",\n        \"default\": \"Video is paused\",\n        \"optional\": true\n      },\n      {\n        \"name\": \"content\",\n        \"type\": \"text\",\n        \"label\": \"Content label\",\n        \"importance\": \"low\",\n        \"default\": \"Content\",\n        \"optional\": true\n      },\n      {\n        \"name\": \"answered\",\n        \"type\": \"text\",\n        \"label\": \"Answered message (@answered will be replaced with the number of answered questions)\",\n        \"importance\": \"low\",\n        \"default\": \"@answered answered\",\n        \"optional\": true\n      },\n      {\n        \"name\": \"endcardTitle\",\n        \"type\": \"text\",\n        \"label\": \"Submit screen title\",\n        \"importance\": \"low\",\n        \"default\": \"@answered Question(s) answered\",\n        \"description\": \"@answered will be replaced by the number of answered questions.\",\n        \"optional\": true\n      },\n      {\n        \"name\": \"endcardInformation\",\n        \"type\": \"text\",\n        \"label\": \"Submit screen information\",\n        \"importance\": \"low\",\n        \"default\": \"You have answered @answered questions, click below to submit your answers.\",\n        \"description\": \"@answered will be replaced by the number of answered questions.\",\n        \"optional\": true\n      },\n      {\n        \"name\": \"endcardInformationOnSubmitButtonDisabled\",\n        \"type\": \"text\",\n        \"label\": \"Submit screen information when submit button is disabled\",\n        \"importance\": \"low\",\n        \"default\": \"You have answered @answered questions.\",\n        \"description\": \"@answered will be replaced by the number of answered questions.\",\n        \"optional\": true\n      },\n      {\n        \"name\": \"endcardInformationNoAnswers\",\n        \"type\": \"text\",\n        \"label\": \"Submit screen information for missing answers\",\n        \"importance\": \"low\",\n        \"default\": \"You have not answered any questions.\",\n        \"optional\": true\n      },\n      {\n        \"name\": \"endcardInformationMustHaveAnswer\",\n        \"type\": \"text\",\n        \"label\": \"Submit screen information for answer needed\",\n        \"importance\": \"low\",\n        \"default\": \"You have to answer at least one question before you can submit your answers.\",\n        \"optional\": true\n      },\n      {\n        \"name\": \"endcardSubmitButton\",\n        \"type\": \"text\",\n        \"label\": \"Submit screen submit button\",\n        \"importance\": \"low\",\n        \"default\": \"Submit Answers\",\n        \"optional\": true\n      },\n      {\n        \"name\": \"endcardSubmitMessage\",\n        \"type\": \"text\",\n        \"label\": \"Submit screen submit message\",\n        \"importance\": \"low\",\n        \"default\": \"Your answers have been submitted!\",\n        \"optional\": true\n      },\n      {\n        \"name\": \"endcardTableRowAnswered\",\n        \"type\": \"text\",\n        \"label\": \"Submit screen table row title: Answered questions\",\n        \"importance\": \"low\",\n        \"default\": \"Answered questions\",\n        \"optional\": true\n      },\n      {\n        \"name\": \"endcardTableRowScore\",\n        \"type\": \"text\",\n        \"label\": \"Submit screen table row title: Score\",\n        \"importance\": \"low\",\n        \"default\": \"Score\",\n        \"optional\": true\n      },\n      {\n        \"name\": \"endcardAnsweredScore\",\n        \"type\": \"text\",\n        \"label\": \"Submit screen answered score\",\n        \"importance\": \"low\",\n        \"default\": \"answered\",\n        \"optional\": true\n      },\n      {\n        \"name\": \"endCardTableRowSummaryWithScore\",\n        \"type\": \"text\",\n        \"label\": \"Submit screen row summary including score (for readspeakers)\",\n        \"importance\": \"low\",\n        \"default\": \"You got @score out of @total points for the @question that appeared after @minutes minutes and @seconds seconds.\",\n        \"optional\": true\n      },\n      {\n        \"name\": \"endCardTableRowSummaryWithoutScore\",\n        \"type\": \"text\",\n        \"label\": \"Submit screen row summary for no score (for readspeakers)\",\n        \"importance\": \"low\",\n        \"default\": \"You have answered the @question that appeared after @minutes minutes and @seconds seconds.\",\n        \"optional\": true\n      },\n      {\n        \"name\": \"videoProgressBar\",\n        \"type\": \"text\",\n        \"label\": \"Video Progressbar\",\n        \"importance\": \"low\",\n        \"default\": \"Video progress\",\n        \"optional\": true\n      },\n      {\n        \"name\": \"howToCreateInteractions\",\n        \"type\": \"text\",\n        \"label\": \"Information on how to start creating interactions\",\n        \"importance\": \"low\",\n        \"default\": \"Play the video to start creating interactions\",\n        \"optional\": true\n      }\n    ]\n  }\n]',NULL,1,27,NULL,NULL,NULL,1);
