INSERT INTO `mdl_h5pactivity` VALUES
(1,2,'Bài tập H5P Tương tác: Chẩn đoán Dinh dưỡng pH/EC & Sâu bệnh Sinh học IPM',1794034521,1794034521,'<p>Hoạt động <strong>H5P Question Set</strong> chuẩn quốc tế (<code>mod_h5pactivity</code>): trả lời trực tiếp 3 tình huống kỹ thuật và tự động đồng bộ điểm số vào Sổ điểm Moodle Gradebook.</p>',1,100,15,1,1,1),
(2,2,'Cẩm nang H5P Accordion: An toàn Sinh học Nước tưới & Nấm đối kháng Trichoderma',1794034521,1794034521,'<p>Học liệu tương tác <strong>H5P Accordion</strong> giúp tra cứu nhanh quy chuẩn lọc đĩa 120 Mesh, ủ <em>Trichoderma</em> và ghi nhật ký truy xuất QR.</p>',1,100,15,1,1,1),
(3,3,'Bài giảng H5P Course Presentation: Công nghệ Pre-cooling, Sấy lạnh & Bảo quản MAP/CA',1794034521,1794034521,'<p>Bài trình chiếu tương tác <strong>H5P Course Presentation</strong> tích hợp câu hỏi kiểm tra ngay trên slide và lưu điểm trực tiếp vào Moodle Gradebook.</p>',1,100,15,1,1,1),
(4,8,'Bước 2.1 — Tương tác H5P (Question Set): Chẩn đoán pH/EC & Phác đồ Sinh học IPM',1794034522,1794034522,'<p>Hoạt động H5P chấm điểm tự động vào Gradebook.</p>',1,100,15,1,1,1),
(14,19,'Bài tập Tương tác H5P: Chẩn đoán Dinh dưỡng pH/EC & Phác đồ IPM',1794280861,1794280861,'',1,100,15,1,1,1),
(15,21,'Bài tập Tương tác H5P: Chẩn đoán Dinh dưỡng pH/EC & Phác đồ IPM',1794280861,1794280861,'',1,100,15,1,1,1),
(16,4,'Bài tập Tương tác H5P: Chẩn đoán Thông số Kỹ thuật & Xử lý Tình huống (IOTNHAMANG01)',1794751931,1794751931,'<p>Hoàn thành bài tập tương tác H5P để kiểm tra kỹ năng chẩn đoán nhanh thông số kỹ thuật hiện trường.</p>',1,100,15,1,1,1),
(17,5,'Bài tập Tương tác H5P: Chẩn đoán Thông số Kỹ thuật & Xử lý Tình huống (THUYCANH01)',1794751931,1794751931,'<p>Hoàn thành bài tập tương tác H5P để kiểm tra kỹ năng chẩn đoán nhanh thông số kỹ thuật hiện trường.</p>',1,100,15,1,1,1),
(18,6,'Bài tập Tương tác H5P: Chẩn đoán Thông số Kỹ thuật & Xử lý Tình huống (SAURIENG01)',1794751931,1794751931,'<p>Hoàn thành bài tập tương tác H5P để kiểm tra kỹ năng chẩn đoán nhanh thông số kỹ thuật hiện trường.</p>',1,100,15,1,1,1),
(19,7,'Bài tập Tương tác H5P: Chẩn đoán Thông số Kỹ thuật & Xử lý Tình huống (PHANVISINH01)',1794751932,1794751932,'<p>Hoàn thành bài tập tương tác H5P để kiểm tra kỹ năng chẩn đoán nhanh thông số kỹ thuật hiện trường.</p>',1,100,15,1,1,1);
