INSERT INTO `mdl_question_attempts` VALUES
(457,39,1,'deferredfeedback',1,1,1.0000000,0.0000000,1.0000000,0,'Khoảng pH dung dịch dinh dưỡng tối ưu giúp rễ cây trồng giá thể/nhà màng hấp thu cân đối đa-trung-vi lượng là bao nhiêu?\n: 5.8 – 6.2; 3.5 – 4.2; 7.5 – 8.5; 8.5 – 9.2','5.8 – 6.2','5.8 – 6.2',1794030797),
(458,39,2,'deferredfeedback',2,1,1.0000000,0.0000000,1.0000000,0,'Vì sao tuyệt đối KHÔNG pha chung đậm đặc phân Canxi Nitrat (Bồn A) với phân chứa gốc Sunfat/Photphat (Bồn B)?\n: Gây kết tủa CaSO4 / Ca3(PO4)2 làm mất dinh dưỡng và tắc béc nhỏ giọt; Làm dung dịch bay hơi hết nước; Làm giảm nhiệt độ nhà màng xuống 0°C; Không có ảnh hưởng gì','Gây kết tủa CaSO4 / Ca3(PO4)2 làm mất dinh dưỡng và tắc béc nhỏ giọt','Gây kết tủa CaSO4 / Ca3(PO4)2 làm mất dinh dưỡng và tắc béc nhỏ giọt',1794030797),
(459,39,3,'deferredfeedback',3,1,1.0000000,0.0000000,1.0000000,0,'Khi trời nắng gắt nhiệt độ >33°C, người trồng cần điều chỉnh chế độ tưới Fertigation như thế nào là đúng kỹ thuật?\n: Chia nhiều lần tưới ngắn hơn và giảm nhẹ EC 0.2–0.3 mS/cm để tránh sốc mặn vùng rễ; Tăng gấp đôi EC lên 5.0 mS/cm; Ngừng tưới hoàn toàn từ sáng đến tối; Chỉ tưới 1 lần duy nhất lúc 21h đêm','Chia nhiều lần tưới ngắn hơn và giảm nhẹ EC 0.2–0.3 mS/cm để tránh sốc mặn vùng rễ','Chia nhiều lần tưới ngắn hơn và giảm nhẹ EC 0.2–0.3 mS/cm để tránh sốc mặn vùng rễ',1794030797),
(460,39,4,'deferredfeedback',4,1,1.0000000,0.0000000,1.0000000,0,'Tỷ lệ nước rỉ thoát đáy bầu giá thể (Drainage %) tiêu chuẩn trong canh tác nhà màng nhằm ngăn tích tụ muối là bao nhiêu?\n: 15% – 25%; 0% (không cho chảy giọt nào); 80% – 95%; 100%','15% – 25%','15% – 25%',1794030797),
(461,39,5,'deferredfeedback',5,1,1.0000000,0.0000000,1.0000000,0,'Triệu chứng cháy khô mép lá non xà lách (Tipburn) và thối đít trái cà chua/dưa lưới liên quan trực tiếp đến thiếu hụt nguyên tố nào?\n: Canxi (Ca); Đạm (N); Clo (Cl); Natri (Na)','Canxi (Ca)','Canxi (Ca)',1794030797),
(462,39,6,'deferredfeedback',6,1,1.0000000,0.0000000,1.0000000,0,'Bộ lọc đĩa trong hệ thống tưới nhỏ giọt công nghệ cao cần cấp độ mịn tối thiểu bao nhiêu để bảo vệ đầu nhỏ giọt bù áp?\n: 120 – 150 mesh; 10 mesh; 20 mesh; Không cần lắp bộ lọc','120 – 150 mesh','120 – 150 mesh',1794030797),
(463,39,7,'deferredfeedback',7,1,1.0000000,0.0000000,1.0000000,0,'Biện pháp giám sát và phòng trừ sinh học hiệu quả nhất đối với Bọ trĩ (Thrips) hại đọt non trong nhà màng là gì?\n: Treo bẫy dính xanh dương/vàng kết hợp phun nấm ký sinh Beauveria/Metarhizium và dầu Neem; Phun thuốc diệt cỏ liều cao; Đóng kín toàn bộ quạt thông gió tăng nhiệt lên 48°C; Tưới nước mặn vào ngọn cây','Treo bẫy dính xanh dương/vàng kết hợp phun nấm ký sinh Beauveria/Metarhizium và dầu Neem','Treo bẫy dính xanh dương/vàng kết hợp phun nấm ký sinh Beauveria/Metarhizium và dầu Neem',1794030797),
(464,39,8,'deferredfeedback',8,1,1.0000000,0.0000000,1.0000000,0,'Để xử lý lớp sáp trắng bảo vệ trên cơ thể Rệp sáp theo hướng an toàn VietGAP, nên phối hợp vật tư sinh học nào?\n: Dầu khoáng sinh học 0.3% kết hợp nấm trắng Beauveria bassiana và chặn kiến cộng sinh; Bón thật nhiều phân Urê vào lá; Tưới nước đá lạnh buổi trưa; Chỉ phun nước lã không cần vệ sinh cành','Dầu khoáng sinh học 0.3% kết hợp nấm trắng Beauveria bassiana và chặn kiến cộng sinh','Dầu khoáng sinh học 0.3% kết hợp nấm trắng Beauveria bassiana và chặn kiến cộng sinh',1794030797),
(465,39,9,'deferredfeedback',9,1,1.0000000,0.0000000,1.0000000,0,'Nấm đối kháng Trichoderma spp. phát huy hiệu quả tốt nhất khi xử lý bệnh nào vùng rễ?\n: Phòng trừ nấm đất Phytophthora, Fusarium, Pythium gây lở cổ rễ và thối rễ; Trị sâu đục quả trưởng thành bay trên ngọn; Thay thế hoàn toàn phân Kali; Làm chín ép trái cây trong 2 giờ','Phòng trừ nấm đất Phytophthora, Fusarium, Pythium gây lở cổ rễ và thối rễ','Phòng trừ nấm đất Phytophthora, Fusarium, Pythium gây lở cổ rễ và thối rễ',1794030797),
(466,39,10,'deferredfeedback',10,1,1.0000000,0.0000000,1.0000000,0,'Vì sao nên kết thúc chu kỳ tưới nhỏ giọt cuối cùng trong ngày trước 15:30–16:00 chiều đối với dưa lưới/cà chua?\n: Để giá thể thông thoáng đủ oxy cho rễ ban đêm, hạn chế ẩm độ cao gây nấm và nứt trái; Vì máy bơm không hoạt động buổi chiều; Để tăng EC vùng rễ lên 10 mS/cm; Để lá cây héo rũ qua đêm','Để giá thể thông thoáng đủ oxy cho rễ ban đêm, hạn chế ẩm độ cao gây nấm và nứt trái','Để giá thể thông thoáng đủ oxy cho rễ ban đêm, hạn chế ẩm độ cao gây nấm và nứt trái',1794030797),
(467,39,11,'deferredfeedback',11,1,1.0000000,0.0000000,1.0000000,0,'Theo quy định VietGAP, chỉ số PHI (Pre-Harvest Interval) trên nhật ký canh tác có ý nghĩa là gì?\n: Thời gian cách ly an toàn từ lần phun cuối cùng đến khi được phép thu hoạch; Tổng diện tích nhà màng tính bằng ha; Áp suất đường ống chính tính bằng bar; Số lượng béc tưới trên một hàng','Thời gian cách ly an toàn từ lần phun cuối cùng đến khi được phép thu hoạch','Thời gian cách ly an toàn từ lần phun cuối cùng đến khi được phép thu hoạch',1794030797),
(468,39,12,'deferredfeedback',12,1,1.0000000,0.0000000,1.0000000,0,'Tiêu chuẩn cây giống khỏe trước khi đem trồng ra nhà màng công nghệ cao gồm đặc điểm nào sau đây?\n: Thân mập thẳng, bầu rễ trắng phát triển mạnh, sạch sâu bệnh và đã huấn luyện thích nghi ánh sáng; Rễ thâm nâu có mùi chua và lá non xoăn vàng; Cây vươn lóng dài yếu ớt do thiếu sáng; Giá thể nhiễm mặn EC > 4.0 mS/cm','Thân mập thẳng, bầu rễ trắng phát triển mạnh, sạch sâu bệnh và đã huấn luyện thích nghi ánh sáng','Rễ thâm nâu có mùi chua và lá non xoăn vàng',1794030797),
(469,40,1,'deferredfeedback',25,1,1.0000000,0.0000000,1.0000000,0,'Chỉ số VPD (Vapor Pressure Deficit) tối ưu cho giai đoạn sinh trưởng và nuôi trái trong nhà màng nằm trong khoảng nào?\n: 0.8 – 1.2 kPa; 0.0 – 0.1 kPa; 3.5 – 5.0 kPa; 8.0 – 10.0 kPa','0.8 – 1.2 kPa','0.8 – 1.2 kPa',1794030797),
(470,40,2,'deferredfeedback',26,1,1.0000000,0.0000000,1.0000000,0,'Vị trí lắp đặt cảm biến nhiệt độ - ẩm độ trong nhà màng như thế nào là đúng chuẩn kỹ thuật?\n: Đặt trong hộp chắn bức xạ thông gió ở ngang tầm ngọn cây đang phát triển; Phơi trần trực tiếp dưới nắng trưa sát mái nilon; Ngâm ngập dưới đáy bể chứa nước; Đặt bên ngoài nhà văn phòng cách vườn 500m','Đặt trong hộp chắn bức xạ thông gió ở ngang tầm ngọn cây đang phát triển','Đặt trong hộp chắn bức xạ thông gió ở ngang tầm ngọn cây đang phát triển',1794030797),
(471,40,3,'deferredfeedback',27,1,1.0000000,0.0000000,1.0000000,0,'Mục đích thiết kế buồng đệm 2 cửa so le (Double-door airlock) ở lối vào nhà màng là gì?\n: Ngăn côn trùng chích hút (bọ trĩ, bọ phấn) bay theo người lao động xâm nhập vào nhà màng; Để trang trí cho đẹp mắt; Để giữ nhiệt độ nhà màng luôn ở 45°C; Thay thế hoàn toàn hệ thống tưới','Ngăn côn trùng chích hút (bọ trĩ, bọ phấn) bay theo người lao động xâm nhập vào nhà màng','Ngăn côn trùng chích hút (bọ trĩ, bọ phấn) bay theo người lao động xâm nhập vào nhà màng',1794030797),
(472,40,4,'deferredfeedback',28,1,1.0000000,0.0000000,1.0000000,0,'Cấp độ mắt lưới chắn côn trùng tiêu chuẩn dùng cho vách nhà màng trồng dưa lưới/rau công nghệ cao để chặn bọ trĩ là bao nhiêu?\n: 50 mesh; 4 mesh; 10 mesh; Không dùng lưới vách','50 mesh','50 mesh',1794030797),
(473,40,5,'deferredfeedback',29,1,1.0000000,0.0000000,1.0000000,0,'Khi ẩm độ trong nhà màng lên quá cao >92% vào sáng sớm (VPD < 0.3 kPa), nguy cơ lớn nhất đối với cây trồng là gì?\n: Đọng sương trên lá làm bùng phát nấm Sương mai, Gỉ sắt, Mốc xám Botrytis và giảm hút Canxi; Cây hút quá nhiều Canxi; Béc tưới chạy nhanh gấp đôi; Độ đường trái tăng đột biến','Đọng sương trên lá làm bùng phát nấm Sương mai, Gỉ sắt, Mốc xám Botrytis và giảm hút Canxi','Đọng sương trên lá làm bùng phát nấm Sương mai, Gỉ sắt, Mốc xám Botrytis và giảm hút Canxi',1794030797),
(474,40,6,'deferredfeedback',30,1,1.0000000,0.0000000,1.0000000,0,'Hệ thống rèm lưới cắt nắng tự động nên được lập trình đóng lại khi nào?\n: Khi bức xạ nắng trưa vượt ngưỡng cao (>45.000 Lux / nhiệt >33°C) và mở ra khi nắng dịu; Đóng kín suốt 24/24 giờ cả ngày lẫn đêm; Chỉ đóng vào ban đêm lúc 22h; Chỉ đóng khi trời mưa râm mát','Khi bức xạ nắng trưa vượt ngưỡng cao (>45.000 Lux / nhiệt >33°C) và mở ra khi nắng dịu','Khi bức xạ nắng trưa vượt ngưỡng cao (>45.000 Lux / nhiệt >33°C) và mở ra khi nắng dịu',1794030797),
(475,40,7,'deferredfeedback',31,1,1.0000000,0.0000000,1.0000000,0,'Ưu điểm của hệ thống phun sương cao áp (70 bar, hạt <10 micron) so với vòi phun nước hạt lớn thông thường là gì?\n: Hạt sương siêu mịn bay hơi làm mát không khí tức thì mà không làm đọng nước ướt lá gây bệnh; Làm ngập sũng lối đi nhà màng; Tốn nước gấp 10 lần tưới tràn; Không làm giảm nhiệt độ','Hạt sương siêu mịn bay hơi làm mát không khí tức thì mà không làm đọng nước ướt lá gây bệnh','Hạt sương siêu mịn bay hơi làm mát không khí tức thì mà không làm đọng nước ướt lá gây bệnh',1794030797),
(476,40,8,'deferredfeedback',32,1,1.0000000,0.0000000,1.0000000,0,'Trong tủ điện điều khiển nhà màng IoT, vì sao bắt buộc phải thiết kế công tắc chuyển mạch AUTO - OFF - MANUAL?\n: Đảm bảo vẫn vận hành tay được bơm tưới và quạt thông gió an toàn khi mất mạng hoặc bảo trì PLC; Để tăng tiền điện hàng tháng; Để vô hiệu hóa cảm biến vĩnh viễn; Chỉ dùng để bật đèn chiếu sáng văn phòng','Đảm bảo vẫn vận hành tay được bơm tưới và quạt thông gió an toàn khi mất mạng hoặc bảo trì PLC','Đảm bảo vẫn vận hành tay được bơm tưới và quạt thông gió an toàn khi mất mạng hoặc bảo trì PLC',1794030797),
(477,40,9,'deferredfeedback',33,1,1.0000000,0.0000000,1.0000000,0,'Nếu nhà màng đóng kín hoàn toàn không trao đổi khí suốt buổi sáng nắng đẹp, yếu tố nào giảm mạnh làm chậm quang hợp?\n: Nồng độ khí CO2 trong nhà màng sụt giảm dưới ngưỡng tự nhiên (<250 ppm); Khí Nitơ biến mất hoàn toàn; Độ pH nước tăng lên 14; Trọng lực giảm','Nồng độ khí CO2 trong nhà màng sụt giảm dưới ngưỡng tự nhiên (<250 ppm)','Nồng độ khí CO2 trong nhà màng sụt giảm dưới ngưỡng tự nhiên (<250 ppm)',1794030797),
(478,40,10,'deferredfeedback',34,1,1.0000000,0.0000000,1.0000000,0,'Cài đặt khoảng trễ (Hysteresis, ví dụ bật quạt ở 31°C và tắt ở 29.5°C) trong bộ điều khiển tự động nhằm mục đích gì?\n: Chống đóng/ngắt rơ-le liên tục (chattering) giúp bảo vệ tuổi thọ động cơ quạt và khởi động từ; Làm hỏng cảm biến nhanh hơn; Tăng sai số đo nhiệt độ lên 10°C; Tắt toàn bộ cảnh báo điện thoại','Chống đóng/ngắt rơ-le liên tục (chattering) giúp bảo vệ tuổi thọ động cơ quạt và khởi động từ','Chống đóng/ngắt rơ-le liên tục (chattering) giúp bảo vệ tuổi thọ động cơ quạt và khởi động từ',1794030797),
(479,40,11,'deferredfeedback',35,1,1.0000000,0.0000000,1.0000000,0,'Bao lâu cần vệ sinh bụi bẩn bám trên mái màng PE nhà màng để duy trì hiệu suất truyền ánh sáng PAR?\n: Định kỳ mỗi 3–6 tháng (đặc biệt trong mùa khô bụi) để giữ độ truyền sáng >85%; Không bao giờ rửa trong 10 năm; Sơn đen kín toàn bộ mái màng PE; Mỗi giờ rửa 1 lần bằng axit đặc','Định kỳ mỗi 3–6 tháng (đặc biệt trong mùa khô bụi) để giữ độ truyền sáng >85%','Định kỳ mỗi 3–6 tháng (đặc biệt trong mùa khô bụi) để giữ độ truyền sáng >85%',1794030797),
(480,40,12,'deferredfeedback',36,1,1.0000000,0.0000000,1.0000000,0,'Khi nhận tin nhắn cảnh báo mất áp suất đường ống chính từ bộ điều khiển IoT lúc đang tưới, cần kiểm tra ngay điều gì?\n: Kiểm tra nguồn nước cấp, rò rỉ vỡ ống chính hoặc nghẹt bầu lọc đĩa đầu nguồn; Xóa ứng dụng cảnh báo trên điện thoại; Bón thêm phân đạm vào gốc; Cắt bỏ toàn bộ lá non','Kiểm tra nguồn nước cấp, rò rỉ vỡ ống chính hoặc nghẹt bầu lọc đĩa đầu nguồn','Xóa ứng dụng cảnh báo trên điện thoại',1794030797),
(481,41,1,'deferredfeedback',37,1,1.0000000,0.0000000,1.0000000,0,'Độ dốc lắp đặt tiêu chuẩn của máng thủy canh hồi lưu NFT để tạo màng dinh dưỡng chảy đều không đọng vũng là bao nhiêu?\n: 2.0% – 2.5% (tỷ lệ khoảng 1:40); 0% (nằm ngang hoàn toàn đọng đầy nước); 45% (dốc đứng); 80%','2.0% – 2.5% (tỷ lệ khoảng 1:40)','2.0% – 2.5% (tỷ lệ khoảng 1:40)',1794030798),
(482,41,2,'deferredfeedback',38,1,1.0000000,0.0000000,1.0000000,0,'Hàm lượng Oxy hòa tan (DO) tối thiểu cần duy trì trong dung dịch thủy canh để bộ rễ trắng khỏe không bị thối ngạt là bao nhiêu?\n: >= 6.0 mg/L; 0.0 mg/L; 0.5 mg/L; Chỉ cần khí CO2 không cần Oxy','>= 6.0 mg/L','>= 6.0 mg/L',1794030798),
(483,41,3,'deferredfeedback',39,1,1.0000000,0.0000000,1.0000000,0,'Vì sao chiều dài mỗi máng thủy canh NFT thương mại không nên vượt quá 12–15 mét?\n: Tránh chênh lệch nhiệt độ tăng cao và cạn kiệt oxy hòa tan ở các hốc cây cuối máng; Vì ống nhựa không thể nối dài hơn 2m; Để giảm ánh sáng mặt trời; Vì cây đầu máng không hút được nước','Tránh chênh lệch nhiệt độ tăng cao và cạn kiệt oxy hòa tan ở các hốc cây cuối máng','Tránh chênh lệch nhiệt độ tăng cao và cạn kiệt oxy hòa tan ở các hốc cây cuối máng',1794030798),
(484,41,4,'deferredfeedback',40,1,1.0000000,0.0000000,1.0000000,0,'Khi xử lý giá thể mụn xơ dừa trước khi trồng dưa lưới/cà chua, chỉ số EC nước xả cuối cùng cần đạt mức nào?\n: EC < 0.5 mS/cm và đã ngâm đệm loại bỏ Tanin/muối Na+; EC > 5.0 mS/cm; Giữ nguyên toàn bộ muối chát tự nhiên; Trộn thêm muối ăn NaCl vào xơ dừa','EC < 0.5 mS/cm và đã ngâm đệm loại bỏ Tanin/muối Na+','EC < 0.5 mS/cm và đã ngâm đệm loại bỏ Tanin/muối Na+',1794030798),
(485,41,5,'deferredfeedback',41,1,1.0000000,0.0000000,1.0000000,0,'Nguyên nhân hàng đầu làm bùng phát nấm nước Pythium gây thối tuột rễ trên giàn thủy canh vào mùa nắng nóng là gì?\n: Nhiệt độ dung dịch dinh dưỡng tăng cao (>30°C) làm giảm mạnh nồng độ oxy hòa tan DO; Nhiệt độ nước mát 22°C giàu oxy; Độ pH ổn định ở 6.0; Ánh sáng buổi sáng dịu nhẹ','Nhiệt độ dung dịch dinh dưỡng tăng cao (>30°C) làm giảm mạnh nồng độ oxy hòa tan DO','Nhiệt độ dung dịch dinh dưỡng tăng cao (>30°C) làm giảm mạnh nồng độ oxy hòa tan DO',1794030798),
(486,41,6,'deferredfeedback',42,1,1.0000000,0.0000000,1.0000000,0,'Vi lượng nào đóng vai trò thiết yếu cấu tạo enzyme Nitrate Reductase giúp cây rau chuyển hóa Nitrat (NO3-) giảm tồn dư trong lá?\n: Molypden (Mo) kết hợp đủ ánh sáng quang hợp; Chì (Pb); Thủy ngân (Hg); Nhôm (Al)','Molypden (Mo) kết hợp đủ ánh sáng quang hợp','Molypden (Mo) kết hợp đủ ánh sáng quang hợp',1794030798),
(487,41,7,'deferredfeedback',43,1,1.0000000,0.0000000,1.0000000,0,'Máng nhựa dùng trong hệ thống thủy canh rau ăn lá chuẩn VietGAP phải đáp ứng yêu cầu vật liệu nào?\n: Nhựa uPVC chuyên dụng an toàn thực phẩm, không thôi nhiễm chì/kim loại nặng, lòng tối chống rêu; Ống nhựa tái chế phế thải công nghiệp chứa chì; Máng tôn gỉ sét; Máng gỗ mục tẩm dầu nhớt','Nhựa uPVC chuyên dụng an toàn thực phẩm, không thôi nhiễm chì/kim loại nặng, lòng tối chống rêu','Nhựa uPVC chuyên dụng an toàn thực phẩm, không thôi nhiễm chì/kim loại nặng, lòng tối chống rêu',1794030798),
(488,41,8,'deferredfeedback',44,1,1.0000000,0.0000000,1.0000000,0,'Để giảm thiểu hàm lượng Nitrat tự do trong rau thủy canh trước khi thu hoạch 3–5 ngày, kỹ thuật nào được áp dụng?\n: Hạ nhẹ nồng độ EC dung dịch (0.8–1.0 mS/cm) và đảm bảo cây nhận đủ ánh sáng chuyển hóa đạm; Tăng gấp 3 lần đạm Urê vào bồn trước giờ cắt 1 tiếng; Che tối đen toàn bộ giàn rau 5 ngày; Ngâm ngập lá rau vào dung dịch Bồn A','Hạ nhẹ nồng độ EC dung dịch (0.8–1.0 mS/cm) và đảm bảo cây nhận đủ ánh sáng chuyển hóa đạm','Hạ nhẹ nồng độ EC dung dịch (0.8–1.0 mS/cm) và đảm bảo cây nhận đủ ánh sáng chuyển hóa đạm',1794030798),
(489,41,9,'deferredfeedback',45,1,1.0000000,0.0000000,1.0000000,0,'Hiện tượng rêu tảo xanh phát triển dày đặc trong bồn chứa và rãnh máng thủy canh gây tác hại gì?\n: Cạnh tranh oxy hòa tan, làm biến động pH, bít nghẹt bơm lọc và sinh độc tố hại rễ non; Giúp cây lớn nhanh gấp 3 lần; Thay thế hoàn toàn phân bón A-B; Tự động làm lạnh dung dịch','Cạnh tranh oxy hòa tan, làm biến động pH, bít nghẹt bơm lọc và sinh độc tố hại rễ non','Cạnh tranh oxy hòa tan, làm biến động pH, bít nghẹt bơm lọc và sinh độc tố hại rễ non',1794030798),
(490,41,10,'deferredfeedback',46,1,1.0000000,0.0000000,1.0000000,0,'Lưu lượng cấp dung dịch dinh dưỡng tiêu chuẩn ở đầu mỗi máng thủy canh NFT là khoảng bao nhiêu?\n: 1.5 – 2.0 Lít/phút; 0.01 Lít/ngày; 500 Lít/phút xối bật gốc cây; Chỉ cấp 1 lần duy nhất mỗi tháng','1.5 – 2.0 Lít/phút','1.5 – 2.0 Lít/phút',1794030798),
(491,41,11,'deferredfeedback',47,1,1.0000000,0.0000000,1.0000000,0,'Biện pháp thiết kế nào giúp giữ dung dịch thủy canh luôn mát mẻ ổn định ở 22–25°C trong điều kiện khí hậu Việt Nam?\n: Hạ ngầm bồn chứa dinh dưỡng dưới mặt đất có nắp đậy kín cách nhiệt và mái máng trắng phản xạ nhiệt; Đặt bồn nhựa màu đen ngoài trời nắng trưa không mái che; Đun nóng bồn dinh dưỡng bằng điện trở; Dùng máng kim loại hấp nhiệt','Hạ ngầm bồn chứa dinh dưỡng dưới mặt đất có nắp đậy kín cách nhiệt và mái máng trắng phản xạ nhiệt','Hạ ngầm bồn chứa dinh dưỡng dưới mặt đất có nắp đậy kín cách nhiệt và mái máng trắng phản xạ nhiệt',1794030798),
(492,41,12,'deferredfeedback',48,1,1.0000000,0.0000000,1.0000000,0,'Khi cây con xà lách mới gieo bị vươn cổ thân dài mảnh yếu ớt (leggy), nguyên nhân kỹ thuật là do đâu?\n: Thiếu ánh sáng ngay sau khi hạt nứt nanh nảy mầm hoặc nhiệt độ ươm quá cao; Đủ nắng sáng sớm thông thoáng; Độ pH nước tưới chuẩn 6.0; Mút xốp sạch vô trùng','Thiếu ánh sáng ngay sau khi hạt nứt nanh nảy mầm hoặc nhiệt độ ươm quá cao','Thiếu ánh sáng ngay sau khi hạt nứt nanh nảy mầm hoặc nhiệt độ ươm quá cao',1794030798),
(493,42,1,'deferredfeedback',49,1,1.0000000,0.0000000,1.0000000,0,'Loại phân Kali nào bắt buộc sử dụng ở giai đoạn nuôi cơm sầu riêng để cơm vàng ráo, ngọt béo và tránh hiện tượng sượng nước?\n: Kali Sunfat (K2SO4) không chứa Clo; Kali Clorua (KCl - phân muối ớt chứa nhiều Clo); Muối ăn NaCl; Chỉ bón thuần phân đạm Urê','Kali Sunfat (K2SO4) không chứa Clo','Kali Sunfat (K2SO4) không chứa Clo',1794030799),
(494,42,2,'deferredfeedback',50,1,1.0000000,0.0000000,1.0000000,0,'Hoa sầu riêng nở rộ và tiếp nhận hạt phấn tốt nhất vào khung giờ nào trong ngày để thực hiện thụ phấn bổ sung giúp trái tròn đều 5 hộc?\n: Ban đêm từ 19:30 – 21:30; Giữa trưa nắng 12:00 – 13:00; Sáng sớm 05:00 khi hoa đã rụng; Không bao giờ mở cánh hoa','Ban đêm từ 19:30 – 21:30','Ban đêm từ 19:30 – 21:30',1794030799),
(495,42,3,'deferredfeedback',51,1,1.0000000,0.0000000,1.0000000,0,'Nguyên nhân sinh lý phổ biến nhất gây rụng trái non hàng loạt khi trái sầu riêng mới bằng quả trứng gà là gì?\n: Cây phóng cơi đọt non mạnh cạnh tranh dinh dưỡng/Canxi-Bo với trái non hoặc sốc nước mưa đầu mùa; Bộ lá già khỏe mạnh quang hợp tốt; Thụ phấn chéo ban đêm đầy đủ; Độ pH đất ổn định 6.2','Cây phóng cơi đọt non mạnh cạnh tranh dinh dưỡng/Canxi-Bo với trái non hoặc sốc nước mưa đầu mùa','Cây phóng cơi đọt non mạnh cạnh tranh dinh dưỡng/Canxi-Bo với trái non hoặc sốc nước mưa đầu mùa',1794030799),
(496,42,4,'deferredfeedback',52,1,1.0000000,0.0000000,1.0000000,0,'Đối tượng dịch hại kiểm dịch thực vật hàng đầu trên trái sầu riêng xuất khẩu cần làm sạch tuyệt đối 100% là loài nào?\n: Rệp sáp phấn trắng (Planococcus / Pseudococcus) và sâu đục quả/hạt; Giun đất có ích trong đất; Ong mật thụ phấn; Vi khuẩn cố định đạm','Rệp sáp phấn trắng (Planococcus / Pseudococcus) và sâu đục quả/hạt','Rệp sáp phấn trắng (Planococcus / Pseudococcus) và sâu đục quả/hạt',1794030799),
(497,42,5,'deferredfeedback',53,1,1.0000000,0.0000000,1.0000000,0,'Biện pháp canh tác căn cơ giúp giảm độ linh động và ngăn rễ sầu riêng hấp thu kim loại nặng Cadimi (Cd) vượt ngưỡng là gì?\n: Nâng pH đất lên 5.8–6.5, tăng chất hữu cơ vi sinh cố định Cd và chọn phân lân sạch kiểm định Cd; Hạ pH đất thật chua xuống 3.8; Ngưng bón toàn bộ phân hữu cơ; Tưới nước thải công nghiệp chưa xử lý','Nâng pH đất lên 5.8–6.5, tăng chất hữu cơ vi sinh cố định Cd và chọn phân lân sạch kiểm định Cd','Nâng pH đất lên 5.8–6.5, tăng chất hữu cơ vi sinh cố định Cd và chọn phân lân sạch kiểm định Cd',1794030799),
(498,42,6,'deferredfeedback',54,1,1.0000000,0.0000000,1.0000000,0,'Tác nhân nấm nguy hiểm nhất gây bệnh nứt thân xì mủ và thối rễ vàng lá trên cây sầu riêng mùa mưa là loài nào?\n: Phytophthora palmivora; Nấm men Saccharomyces; Nấm đối kháng Trichoderma; Nấm rơm Volvariella','Phytophthora palmivora','Phytophthora palmivora',1794030799),
(499,42,7,'deferredfeedback',55,1,1.0000000,0.0000000,1.0000000,0,'Chỉ tiêu hàm lượng chất khô tối thiểu trong cơm sầu riêng Dona (Monthong) để đảm bảo đủ độ già chín sinh lý khi thu hoạch xuất khẩu là bao nhiêu?\n: Đạt tối thiểu >= 32%; Chỉ cần 12% (trái non trắng); 5%; 98% khô cứng như đá','Đạt tối thiểu >= 32%','Đạt tối thiểu >= 32%',1794030799),
(500,42,8,'deferredfeedback',56,1,1.0000000,0.0000000,1.0000000,0,'Mỗi trái sầu riêng thương phẩm 3 kg cần trung bình bao nhiêu lá trưởng thành khỏe mạnh trên cành để nuôi trái đạt chuẩn?\n: Khoảng 300 – 400 lá khỏe mạnh không sâu bệnh; Chỉ cần 3 lá trên cả cây; Vặt trụi hết lá để trái phơi nắng; 10 lá','Khoảng 300 – 400 lá khỏe mạnh không sâu bệnh','Khoảng 300 – 400 lá khỏe mạnh không sâu bệnh',1794030799),
(501,42,9,'deferredfeedback',57,1,1.0000000,0.0000000,1.0000000,0,'Khi sử dụng nấm đối kháng Trichoderma tưới gốc phòng bệnh thối rễ sầu riêng, cần lưu ý nguyên tắc nào?\n: Đất đủ ẩm, giàu mùn hữu cơ và cách ly việc rải vôi nóng hoặc tưới thuốc nấm hóa học gốc đồng ít nhất 10–14 ngày; Pha chung trực tiếp với thuốc trừ nấm gốc đồng đậm đặc trong cùng một phi; Rải trên mặt bê tông khô nắng gắt 45°C; Chỉ phun lên ngọn lá lúc 12h trưa','Đất đủ ẩm, giàu mùn hữu cơ và cách ly việc rải vôi nóng hoặc tưới thuốc nấm hóa học gốc đồng ít nhất 10–14 ngày','Đất đủ ẩm, giàu mùn hữu cơ và cách ly việc rải vôi nóng hoặc tưới thuốc nấm hóa học gốc đồng ít nhất 10–14 ngày',1794030799),
(502,42,10,'deferredfeedback',58,1,1.0000000,0.0000000,1.0000000,0,'Mã số vùng trồng (PUC - Production Unit Code) của vườn sầu riêng xuất khẩu có thể bị đình chỉ thu hồi trong trường hợp nào?\n: Vi phạm kiểm dịch thực vật (nhiễm rệp sáp), vượt dư lượng BVTV/Cadimi hoặc gian lận mượn mã vùng trồng; Ghi chép nhật ký VietGAP đầy đủ chính xác; Áp dụng tưới tiết kiệm và IPM sinh học; Thu hoạch đúng độ chín chuẩn','Vi phạm kiểm dịch thực vật (nhiễm rệp sáp), vượt dư lượng BVTV/Cadimi hoặc gian lận mượn mã vùng trồng','Vi phạm kiểm dịch thực vật (nhiễm rệp sáp), vượt dư lượng BVTV/Cadimi hoặc gian lận mượn mã vùng trồng',1794030799),
(503,42,11,'deferredfeedback',59,1,1.0000000,0.0000000,1.0000000,0,'Vì sao khi trồng sầu riêng ở vùng đất thấp hoặc mưa nhiều bắt buộc phải đắp mô nổi và xẻ rãnh thoát nước?\n: Bộ rễ sầu riêng rất mẫn cảm ngập úng thiếu oxy; đọng nước làm thối rễ tơ và kích hoạt nấm Phytophthora; Vì sầu riêng là cây thủy sinh ưa ngập nước sâu; Để không phải tưới nước mùa khô; Để ngăn ánh sáng chiếu vào tán cây','Bộ rễ sầu riêng rất mẫn cảm ngập úng thiếu oxy; đọng nước làm thối rễ tơ và kích hoạt nấm Phytophthora','Bộ rễ sầu riêng rất mẫn cảm ngập úng thiếu oxy; đọng nước làm thối rễ tơ và kích hoạt nấm Phytophthora',1794030799),
(504,42,12,'deferredfeedback',60,1,1.0000000,0.0000000,1.0000000,0,'Khoảng thời gian cách ly và nguyên tắc ghi nhật ký đối với vườn sầu riêng có Mã số vùng trồng xuất khẩu là gì?\n: Chỉ dùng hoạt chất được nước nhập khẩu cho phép, ghi chép đầy đủ 100% và tuân thủ nghiêm ngặt thời gian cách ly PHI; Phun bất kỳ thuốc cấm nào sát ngày cắt trái; Không cần lưu hồ sơ vật tư đầu vào; Thu gom trái không rõ nguồn gốc đóng chung lô','Chỉ dùng hoạt chất được nước nhập khẩu cho phép, ghi chép đầy đủ 100% và tuân thủ nghiêm ngặt thời gian cách ly PHI','Chỉ dùng hoạt chất được nước nhập khẩu cho phép, ghi chép đầy đủ 100% và tuân thủ nghiêm ngặt thời gian cách ly PHI',1794030799),
(505,43,1,'deferredfeedback',1,1,1.0000000,0.0000000,1.0000000,0,'Khoảng pH dung dịch dinh dưỡng tối ưu giúp rễ cây trồng giá thể/nhà màng hấp thu cân đối đa-trung-vi lượng là bao nhiêu?\n: 5.8 – 6.2; 3.5 – 4.2; 7.5 – 8.5; 8.5 – 9.2','5.8 – 6.2','5.8 – 6.2',1794030799),
(506,43,2,'deferredfeedback',2,1,1.0000000,0.0000000,1.0000000,0,'Vì sao tuyệt đối KHÔNG pha chung đậm đặc phân Canxi Nitrat (Bồn A) với phân chứa gốc Sunfat/Photphat (Bồn B)?\n: Gây kết tủa CaSO4 / Ca3(PO4)2 làm mất dinh dưỡng và tắc béc nhỏ giọt; Làm dung dịch bay hơi hết nước; Làm giảm nhiệt độ nhà màng xuống 0°C; Không có ảnh hưởng gì','Gây kết tủa CaSO4 / Ca3(PO4)2 làm mất dinh dưỡng và tắc béc nhỏ giọt','Gây kết tủa CaSO4 / Ca3(PO4)2 làm mất dinh dưỡng và tắc béc nhỏ giọt',1794030799),
(507,43,3,'deferredfeedback',3,1,1.0000000,0.0000000,1.0000000,0,'Khi trời nắng gắt nhiệt độ >33°C, người trồng cần điều chỉnh chế độ tưới Fertigation như thế nào là đúng kỹ thuật?\n: Chia nhiều lần tưới ngắn hơn và giảm nhẹ EC 0.2–0.3 mS/cm để tránh sốc mặn vùng rễ; Tăng gấp đôi EC lên 5.0 mS/cm; Ngừng tưới hoàn toàn từ sáng đến tối; Chỉ tưới 1 lần duy nhất lúc 21h đêm','Chia nhiều lần tưới ngắn hơn và giảm nhẹ EC 0.2–0.3 mS/cm để tránh sốc mặn vùng rễ','Chia nhiều lần tưới ngắn hơn và giảm nhẹ EC 0.2–0.3 mS/cm để tránh sốc mặn vùng rễ',1794030799),
(508,43,4,'deferredfeedback',4,1,1.0000000,0.0000000,1.0000000,0,'Tỷ lệ nước rỉ thoát đáy bầu giá thể (Drainage %) tiêu chuẩn trong canh tác nhà màng nhằm ngăn tích tụ muối là bao nhiêu?\n: 15% – 25%; 0% (không cho chảy giọt nào); 80% – 95%; 100%','15% – 25%','15% – 25%',1794030799),
(509,43,5,'deferredfeedback',5,1,1.0000000,0.0000000,1.0000000,0,'Triệu chứng cháy khô mép lá non xà lách (Tipburn) và thối đít trái cà chua/dưa lưới liên quan trực tiếp đến thiếu hụt nguyên tố nào?\n: Canxi (Ca); Đạm (N); Clo (Cl); Natri (Na)','Canxi (Ca)','Canxi (Ca)',1794030799),
(510,43,6,'deferredfeedback',6,1,1.0000000,0.0000000,1.0000000,0,'Bộ lọc đĩa trong hệ thống tưới nhỏ giọt công nghệ cao cần cấp độ mịn tối thiểu bao nhiêu để bảo vệ đầu nhỏ giọt bù áp?\n: 120 – 150 mesh; 10 mesh; 20 mesh; Không cần lắp bộ lọc','120 – 150 mesh','120 – 150 mesh',1794030799),
(511,43,7,'deferredfeedback',7,1,1.0000000,0.0000000,1.0000000,0,'Biện pháp giám sát và phòng trừ sinh học hiệu quả nhất đối với Bọ trĩ (Thrips) hại đọt non trong nhà màng là gì?\n: Treo bẫy dính xanh dương/vàng kết hợp phun nấm ký sinh Beauveria/Metarhizium và dầu Neem; Phun thuốc diệt cỏ liều cao; Đóng kín toàn bộ quạt thông gió tăng nhiệt lên 48°C; Tưới nước mặn vào ngọn cây','Treo bẫy dính xanh dương/vàng kết hợp phun nấm ký sinh Beauveria/Metarhizium và dầu Neem','Treo bẫy dính xanh dương/vàng kết hợp phun nấm ký sinh Beauveria/Metarhizium và dầu Neem',1794030799),
(512,43,8,'deferredfeedback',8,1,1.0000000,0.0000000,1.0000000,0,'Để xử lý lớp sáp trắng bảo vệ trên cơ thể Rệp sáp theo hướng an toàn VietGAP, nên phối hợp vật tư sinh học nào?\n: Dầu khoáng sinh học 0.3% kết hợp nấm trắng Beauveria bassiana và chặn kiến cộng sinh; Bón thật nhiều phân Urê vào lá; Tưới nước đá lạnh buổi trưa; Chỉ phun nước lã không cần vệ sinh cành','Dầu khoáng sinh học 0.3% kết hợp nấm trắng Beauveria bassiana và chặn kiến cộng sinh','Dầu khoáng sinh học 0.3% kết hợp nấm trắng Beauveria bassiana và chặn kiến cộng sinh',1794030799),
(513,43,9,'deferredfeedback',9,1,1.0000000,0.0000000,1.0000000,0,'Nấm đối kháng Trichoderma spp. phát huy hiệu quả tốt nhất khi xử lý bệnh nào vùng rễ?\n: Phòng trừ nấm đất Phytophthora, Fusarium, Pythium gây lở cổ rễ và thối rễ; Trị sâu đục quả trưởng thành bay trên ngọn; Thay thế hoàn toàn phân Kali; Làm chín ép trái cây trong 2 giờ','Phòng trừ nấm đất Phytophthora, Fusarium, Pythium gây lở cổ rễ và thối rễ','Phòng trừ nấm đất Phytophthora, Fusarium, Pythium gây lở cổ rễ và thối rễ',1794030799),
(514,43,10,'deferredfeedback',10,1,1.0000000,0.0000000,1.0000000,0,'Vì sao nên kết thúc chu kỳ tưới nhỏ giọt cuối cùng trong ngày trước 15:30–16:00 chiều đối với dưa lưới/cà chua?\n: Để giá thể thông thoáng đủ oxy cho rễ ban đêm, hạn chế ẩm độ cao gây nấm và nứt trái; Vì máy bơm không hoạt động buổi chiều; Để tăng EC vùng rễ lên 10 mS/cm; Để lá cây héo rũ qua đêm','Để giá thể thông thoáng đủ oxy cho rễ ban đêm, hạn chế ẩm độ cao gây nấm và nứt trái','Để giá thể thông thoáng đủ oxy cho rễ ban đêm, hạn chế ẩm độ cao gây nấm và nứt trái',1794030799),
(515,43,11,'deferredfeedback',11,1,1.0000000,0.0000000,1.0000000,0,'Theo quy định VietGAP, chỉ số PHI (Pre-Harvest Interval) trên nhật ký canh tác có ý nghĩa là gì?\n: Thời gian cách ly an toàn từ lần phun cuối cùng đến khi được phép thu hoạch; Tổng diện tích nhà màng tính bằng ha; Áp suất đường ống chính tính bằng bar; Số lượng béc tưới trên một hàng','Thời gian cách ly an toàn từ lần phun cuối cùng đến khi được phép thu hoạch','Tổng diện tích nhà màng tính bằng ha',1794030799),
(516,43,12,'deferredfeedback',12,1,1.0000000,0.0000000,1.0000000,0,'Tiêu chuẩn cây giống khỏe trước khi đem trồng ra nhà màng công nghệ cao gồm đặc điểm nào sau đây?\n: Thân mập thẳng, bầu rễ trắng phát triển mạnh, sạch sâu bệnh và đã huấn luyện thích nghi ánh sáng; Rễ thâm nâu có mùi chua và lá non xoăn vàng; Cây vươn lóng dài yếu ớt do thiếu sáng; Giá thể nhiễm mặn EC > 4.0 mS/cm','Thân mập thẳng, bầu rễ trắng phát triển mạnh, sạch sâu bệnh và đã huấn luyện thích nghi ánh sáng','Rễ thâm nâu có mùi chua và lá non xoăn vàng',1794030799),
(517,44,1,'deferredfeedback',13,1,1.0000000,0.0000000,1.0000000,0,'Mục đích cốt lõi của công đoạn làm mát sơ bộ (Pre-cooling) trong vòng 2 giờ đầu sau thu hoạch là gì?\n: Nhanh chóng rút nhiệt đồng ruộng, giảm cường độ hô hấp và sự mất nước của nông sản; Làm chín nhanh toàn bộ lô hàng trong 1 giờ; Tăng hàm lượng nước tự do đọng trên mặt lá; Làm đông cứng rau ăn lá ở -20°C','Nhanh chóng rút nhiệt đồng ruộng, giảm cường độ hô hấp và sự mất nước của nông sản','Nhanh chóng rút nhiệt đồng ruộng, giảm cường độ hô hấp và sự mất nước của nông sản',1794030800),
(518,44,2,'deferredfeedback',14,1,1.0000000,0.0000000,1.0000000,0,'Phương pháp làm mát sơ bộ nào giúp hạ nhiệt rau ăn lá (xà lách, cải bó xôi) từ 28°C xuống 3°C nhanh nhất (chỉ 20–30 phút)?\n: Làm mát chân không (Vacuum Cooling); Phơi ngoài sân nắng; Ủ kín trong bao tải dứa; Đặt cạnh lò sấy nhiệt','Làm mát chân không (Vacuum Cooling)','Làm mát chân không (Vacuum Cooling)',1794030800),
(519,44,3,'deferredfeedback',15,1,1.0000000,0.0000000,1.0000000,0,'Nhiệt độ và ẩm độ kho mát tiêu chuẩn để bảo quản tươi nhóm rau ăn lá ôn đới (xà lách, cải thảo, bông cải) là bao nhiêu?\n: 2°C – 5°C và ẩm độ 90% – 95%; 22°C – 28°C và ẩm độ 40%; -18°C đóng băng hoàn toàn; 35°C và ẩm độ 99%','2°C – 5°C và ẩm độ 90% – 95%','2°C – 5°C và ẩm độ 90% – 95%',1794030800),
(520,44,4,'deferredfeedback',16,1,1.0000000,0.0000000,1.0000000,0,'Vì sao không được bảo quản trái cây nhiệt đới tươi nguyên quả (xoài, chuối, sầu riêng tươi) ở nhiệt độ quá thấp 0–4°C?\n: Gây hiện tượng tổn thương lạnh (Chilling Injury) làm thâm đen vỏ và sượng thịt quả; Làm trái nổ vỡ ngay lập tức; Làm tăng trọng lượng trái lên 200%; Vì kho lạnh không thể chỉnh dưới 15°C','Gây hiện tượng tổn thương lạnh (Chilling Injury) làm thâm đen vỏ và sượng thịt quả','Gây hiện tượng tổn thương lạnh (Chilling Injury) làm thâm đen vỏ và sượng thịt quả',1794030800),
(521,44,5,'deferredfeedback',17,1,1.0000000,0.0000000,1.0000000,0,'Nguyên lý chính của bao bì khí quyển biến đổi MAP (Modified Atmosphere Packaging) trong bảo quản rau quả tươi là gì?\n: Giảm nồng độ O2 (3–5%) và nâng nhẹ CO2 (5–8%) để làm chậm hô hấp và ức chế vi sinh gây hư hỏng; Bơm 100% khí Ethylene vào túi để thúc chín; Hút kiệt tạo áp suất nén nát lá rau; Bơm không khí nóng 60°C vào bao bì','Giảm nồng độ O2 (3–5%) và nâng nhẹ CO2 (5–8%) để làm chậm hô hấp và ức chế vi sinh gây hư hỏng','Giảm nồng độ O2 (3–5%) và nâng nhẹ CO2 (5–8%) để làm chậm hô hấp và ức chế vi sinh gây hư hỏng',1794030800),
(522,44,6,'deferredfeedback',18,1,1.0000000,0.0000000,1.0000000,0,'Công nghệ sấy lạnh bơm nhiệt (Heat-Pump Drying) vận hành ở dải nhiệt độ nào để bảo toàn màu sắc và Vitamin?\n: 25°C – 42°C với không khí tách ẩm khô tuần hoàn kín; 120°C – 180°C bằng than đá; 95°C – 110°C ngoài trời; -40°C không tách ẩm','25°C – 42°C với không khí tách ẩm khô tuần hoàn kín','25°C – 42°C với không khí tách ẩm khô tuần hoàn kín',1794030800),
(523,44,7,'deferredfeedback',19,1,1.0000000,0.0000000,1.0000000,0,'Tại sao không nên xếp chung kho lạnh giữa các trái sinh nhiều khí Ethylene (chuối chín, sầu riêng) với rau ăn lá hoặc dưa leo?\n: Khí Ethylene kích thích vàng lá, rụng cuống và làm già hóa hư hỏng nhanh rau ăn lá; Làm kho lạnh tiêu tốn ít điện hơn; Làm dưa leo ngọt thành dưa lưới; Không có bất kỳ tác động sinh lý nào','Khí Ethylene kích thích vàng lá, rụng cuống và làm già hóa hư hỏng nhanh rau ăn lá','Khí Ethylene kích thích vàng lá, rụng cuống và làm già hóa hư hỏng nhanh rau ăn lá',1794030800),
(524,44,8,'deferredfeedback',20,1,1.0000000,0.0000000,1.0000000,0,'Công nghệ cấp đông siêu tốc IQF (-35°C đến -40°C) giúp múi sầu riêng xuất khẩu đạt chất lượng vượt trội nhờ cơ chế nào?\n: Hình thành vi tinh thể băng cực nhỏ không phá vỡ màng tế bào, không chảy dịch khi rã đông; Rút hết toàn bộ hương thơm của sầu riêng; Biến tinh bột thành chất xơ gỗ; Không cần bảo quản lạnh sau cấp đông','Hình thành vi tinh thể băng cực nhỏ không phá vỡ màng tế bào, không chảy dịch khi rã đông','Hình thành vi tinh thể băng cực nhỏ không phá vỡ màng tế bào, không chảy dịch khi rã đông',1794030800),
(525,44,9,'deferredfeedback',21,1,1.0000000,0.0000000,1.0000000,0,'Nguyên tắc thiết kế mặt bằng nhà xưởng sơ chế nông sản đạt chuẩn HACCP / ISO 22000 là gì?\n: Nguyên tắc dòng chảy 1 chiều từ khu nguyên liệu sang khu sạch đóng gói, không nhiễm chéo; Nhập nguyên liệu và xuất thành phẩm chung một bàn sơ chế đất; Đặt kho thuốc BVTV ngay trong phòng đóng gói; Không cần khử trùng dao kéo thu hoạch','Nguyên tắc dòng chảy 1 chiều từ khu nguyên liệu sang khu sạch đóng gói, không nhiễm chéo','Nguyên tắc dòng chảy 1 chiều từ khu nguyên liệu sang khu sạch đóng gói, không nhiễm chéo',1794030800),
(526,44,10,'deferredfeedback',22,1,1.0000000,0.0000000,1.0000000,0,'Trước khi đóng gói rau ăn lá vào túi màng MAP, yêu cầu bắt buộc đối với bề mặt lá sau khi rửa là gì?\n: Phải làm ráo hoàn toàn nước tự do đọng trên lá (ly tâm/quạt lạnh) để ngừa thối nhũn vi khuẩn; Để nguyên nước ướt sũng trong túi kín; Phun nước đường lên mặt lá; Phơi nắng trưa 35°C trong 2 giờ','Phải làm ráo hoàn toàn nước tự do đọng trên lá (ly tâm/quạt lạnh) để ngừa thối nhũn vi khuẩn','Phải làm ráo hoàn toàn nước tự do đọng trên lá (ly tâm/quạt lạnh) để ngừa thối nhũn vi khuẩn',1794030800),
(527,44,11,'deferredfeedback',23,1,1.0000000,0.0000000,1.0000000,0,'Thiết bị nào bắt buộc gắn trong container lạnh xuất khẩu đường biển để minh chứng chuỗi lạnh không bị đứt gãy?\n: Thiết bị ghi hành trình nhiệt độ - ẩm độ tự động (DataLogger); Bình tưới cây cầm tay; Bẫy dính côn trùng màu vàng; Bút thử độ mặn đất','Thiết bị ghi hành trình nhiệt độ - ẩm độ tự động (DataLogger)','Thiết bị ghi hành trình nhiệt độ - ẩm độ tự động (DataLogger)',1794030800),
(528,44,12,'deferredfeedback',24,1,1.0000000,0.0000000,1.0000000,0,'Thông tin nào cần hiển thị công khai khi người tiêu dùng quét mã QR truy xuất nguồn gốc trên bao bì nông sản VietGAP?\n: Mã lô sản xuất, tên nông hộ & tọa độ vùng trồng, lịch sử nhật ký canh tác, ngày thu hoạch & chuẩn an toàn; Mật khẩu quản trị hệ thống của nông trại; Số tài khoản cá nhân của tài xế; Chỉ hiển thị một bức ảnh tĩnh không có dữ liệu lô','Mã lô sản xuất, tên nông hộ & tọa độ vùng trồng, lịch sử nhật ký canh tác, ngày thu hoạch & chuẩn an toàn','Mật khẩu quản trị hệ thống của nông trại',1794030800),
(529,45,1,'deferredfeedback',61,1,1.0000000,0.0000000,1.0000000,0,'Tỷ lệ Carbon / Nitơ (C/N) lý tưởng nhất của hỗn hợp nguyên liệu ban đầu khi ủ phân hữu cơ vi sinh là bao nhiêu?\n: 25:1 đến 30:1; 500:1 (chỉ toàn mùn cưa khô không có đạm); 2:1 (chỉ toàn đạm đặc); 0:0','25:1 đến 30:1','25:1 đến 30:1',1794030800),
(530,45,2,'deferredfeedback',62,1,1.0000000,0.0000000,1.0000000,0,'Độ ẩm nguyên liệu chuẩn khi bắt đầu đánh đống ủ phân hữu cơ hiếu khí (kiểm tra nắm chặt rỉ nước kẽ tay không nhỏ giọt) là bao nhiêu?\n: 55% – 60%; 5% khô rang như cát; 95% ngập sũng như cháo loãng; 0%','55% – 60%','55% – 60%',1794030800),
(531,45,3,'deferredfeedback',63,1,1.0000000,0.0000000,1.0000000,0,'Nhiệt độ ở giai đoạn ưa nhiệt (Thermophilic phase) trong tâm đống ủ đạt 55–65°C kéo dài nhiều ngày có tác dụng quan trọng gì?\n: Tiêu diệt vi khuẩn gây bệnh (E.coli, Salmonella), trứng tuyến trùng, nấm hại và làm mất sức nảy mầm hạt cỏ dại; Làm phân biến thành nhựa tổng hợp; Giữ sống toàn bộ hạt cỏ dại để mọc nhiều hơn; Đóng băng đống phân','Tiêu diệt vi khuẩn gây bệnh (E.coli, Salmonella), trứng tuyến trùng, nấm hại và làm mất sức nảy mầm hạt cỏ dại','Tiêu diệt vi khuẩn gây bệnh (E.coli, Salmonella), trứng tuyến trùng, nấm hại và làm mất sức nảy mầm hạt cỏ dại',1794030800),
(532,45,4,'deferredfeedback',64,1,1.0000000,0.0000000,1.0000000,0,'Vì sao nên cấy bổ sung chủng nấm đối kháng Trichoderma vào giai đoạn đống ủ đã hạ nhiệt nguội (<38°C) thay vì lúc đang nóng 65°C?\n: Tránh nhiệt độ quá cao 65°C tiêu diệt bào tử Trichoderma, giúp nấm nhân sinh khối tối đa trong phân thành phẩm; Vì Trichoderma chỉ sống ở 100°C; Để làm phân bốc mùi khai; Không có lý do kỹ thuật nào','Tránh nhiệt độ quá cao 65°C tiêu diệt bào tử Trichoderma, giúp nấm nhân sinh khối tối đa trong phân thành phẩm','Tránh nhiệt độ quá cao 65°C tiêu diệt bào tử Trichoderma, giúp nấm nhân sinh khối tối đa trong phân thành phẩm',1794030800),
(533,45,5,'deferredfeedback',65,1,1.0000000,0.0000000,1.0000000,0,'Theo tiêu chuẩn VietGAP, vì sao nghiêm cấm bón phân chuồng tươi chưa qua ủ hoai mục trực tiếp cho rau quả?\n: Nguy cơ nhiễm vi sinh vật gây bệnh đường ruột (E.coli, Salmonella), tuyến trùng rễ và sinh nhiệt độc rễ; Vì phân tươi quá đắt tiền; Vì phân tươi có màu quá đẹp; Vì phân tươi làm tăng oxy đất quá mức','Nguy cơ nhiễm vi sinh vật gây bệnh đường ruột (E.coli, Salmonella), tuyến trùng rễ và sinh nhiệt độc rễ','Nguy cơ nhiễm vi sinh vật gây bệnh đường ruột (E.coli, Salmonella), tuyến trùng rễ và sinh nhiệt độc rễ',1794030800),
(534,45,6,'deferredfeedback',66,1,1.0000000,0.0000000,1.0000000,0,'Khi đống ủ phân hữu cơ bốc mùi trứng thối (H2S) và chua gắt, nguyên nhân kỹ thuật là do đâu và xử lý thế nào?\n: Đống ủ quá ướt thiếu oxy (yếm khí); cần đảo trộn tơi xốp và bổ sung chất độn khô giàu Carbon (trấu, mùn dừa); Đống ủ quá giàu oxy; cần đổ ngập nước kín; Nhiệt độ ngoài trời 25°C; Do có nhiều xạ khuẩn thơm','Đống ủ quá ướt thiếu oxy (yếm khí); cần đảo trộn tơi xốp và bổ sung chất độn khô giàu Carbon (trấu, mùn dừa)','Đống ủ quá ướt thiếu oxy (yếm khí); cần đảo trộn tơi xốp và bổ sung chất độn khô giàu Carbon (trấu, mùn dừa)',1794030800),
(535,45,7,'deferredfeedback',67,1,1.0000000,0.0000000,1.0000000,0,'Dấu hiệu cảm quan chính xác chứng tỏ mẻ phân hữu cơ vi sinh đã chín hoai hoàn toàn sẵn sàng đem bón là gì?\n: Màu nâu đen tơi xốp, nhiệt độ hạ bằng môi trường và có mùi thơm dịu của đất rừng (xạ khuẩn); Tâm đống ủ vẫn nóng bỏng 65°C và bốc mùi khai nồng; Nguyên liệu còn nguyên màu xanh tươi; Chảy nước đen hôi thối','Màu nâu đen tơi xốp, nhiệt độ hạ bằng môi trường và có mùi thơm dịu của đất rừng (xạ khuẩn)','Màu nâu đen tơi xốp, nhiệt độ hạ bằng môi trường và có mùi thơm dịu của đất rừng (xạ khuẩn)',1794030800),
(536,45,8,'deferredfeedback',68,1,1.0000000,0.0000000,1.0000000,0,'Nhóm vi sinh vật có ích Bacillus megaterium / Bacillus subtilis bổ sung trong phân hữu cơ vi sinh có khả năng nổi bật nào?\n: Tiết enzyme và axit hữu cơ phân giải Lân khó tan trong đất thành dạng cây dễ hấp thu và đối kháng nấm khuẩn hại; Biến đất cát thành đá tảng; Hút hết oxy làm ngạt rễ cây; Làm chua đất xuống pH 2.0','Tiết enzyme và axit hữu cơ phân giải Lân khó tan trong đất thành dạng cây dễ hấp thu và đối kháng nấm khuẩn hại','Tiết enzyme và axit hữu cơ phân giải Lân khó tan trong đất thành dạng cây dễ hấp thu và đối kháng nấm khuẩn hại',1794030800),
(537,45,9,'deferredfeedback',69,1,1.0000000,0.0000000,1.0000000,0,'Vị trí và cách bón phân hữu cơ vi sinh cho cây ăn quả lâu năm (Sầu riêng, Bưởi) đạt hiệu quả cao nhất là gì?\n: Bón theo hình chiếu rìa tán lá (vùng rễ tơ), lấp đất mỏng hoặc tủ rơm giữ ẩm tránh nắng UV chiếu chết vi sinh; Đổ thành đống dày 50cm ốp sát vào cổ thân gốc cây; Rải phơi khô trắng trên mặt cỏ giữa trưa nắng gắt không tưới; Pha nguyên xác phân thô vào ống nhỏ giọt bù áp','Bón theo hình chiếu rìa tán lá (vùng rễ tơ), lấp đất mỏng hoặc tủ rơm giữ ẩm tránh nắng UV chiếu chết vi sinh','Bón theo hình chiếu rìa tán lá (vùng rễ tơ), lấp đất mỏng hoặc tủ rơm giữ ẩm tránh nắng UV chiếu chết vi sinh',1794030800),
(538,45,10,'deferredfeedback',70,1,1.0000000,0.0000000,1.0000000,0,'Khi thủy phân đạm cá / bánh dầu sinh học làm phân tưới gốc không mùi hôi, nguyên liệu nào cung cấp nguồn đường nuôi khuẩn Lactic & Bacillus?\n: Rỉ mật đường (Molasses) kết hợp chế phẩm men vi sinh EM / Protease; Dầu hỏa công nghiệp; Vôi nung CaO liều cao; Muối hột bão hòa','Rỉ mật đường (Molasses) kết hợp chế phẩm men vi sinh EM / Protease','Rỉ mật đường (Molasses) kết hợp chế phẩm men vi sinh EM / Protease',1794030800),
(539,45,11,'deferredfeedback',71,1,1.0000000,0.0000000,1.0000000,0,'Tác dụng cải tạo vật lý - hóa học quan trọng nhất của mùn hữu cơ đối với đất đỏ bazan Tây Nguyên và đất xám Đông Nam Bộ là gì?\n: Tăng khả năng giữ phân CEC, đệm ổn định pH đất, tạo cấu trúc tơi xốp giàu oxy và nuôi hệ thiên địch đất; Làm đất nén chặt không thấm nước; Làm tăng độc tố Nhôm di động Al3+; Tiêu diệt hết giun đất','Tăng khả năng giữ phân CEC, đệm ổn định pH đất, tạo cấu trúc tơi xốp giàu oxy và nuôi hệ thiên địch đất','Làm đất nén chặt không thấm nước',1794030800),
(540,45,12,'deferredfeedback',72,1,1.0000000,0.0000000,1.0000000,0,'Mật độ vi sinh vật hữu ích tối thiểu trên nhãn/mẻ phân hữu cơ vi sinh chất lượng cao thường đạt ngưỡng nào?\n: Từ 10^6 đến 10^8 CFU/g trở lên; 0 CFU/g (vô trùng tuyệt đối); 1 tế bào trên 1 tấn phân; Chỉ chứa cát sỏi khoáng','Từ 10^6 đến 10^8 CFU/g trở lên','0 CFU/g (vô trùng tuyệt đối)',1794030800),
(541,46,1,'deferredfeedback',1,1,1.0000000,0.0000000,1.0000000,0,'Khoảng pH dung dịch dinh dưỡng tối ưu giúp rễ cây trồng giá thể/nhà màng hấp thu cân đối đa-trung-vi lượng là bao nhiêu?\n: 5.8 – 6.2; 3.5 – 4.2; 7.5 – 8.5; 8.5 – 9.2','5.8 – 6.2','5.8 – 6.2',1794030801),
(542,46,2,'deferredfeedback',2,1,1.0000000,0.0000000,1.0000000,0,'Vì sao tuyệt đối KHÔNG pha chung đậm đặc phân Canxi Nitrat (Bồn A) với phân chứa gốc Sunfat/Photphat (Bồn B)?\n: Gây kết tủa CaSO4 / Ca3(PO4)2 làm mất dinh dưỡng và tắc béc nhỏ giọt; Làm dung dịch bay hơi hết nước; Làm giảm nhiệt độ nhà màng xuống 0°C; Không có ảnh hưởng gì','Gây kết tủa CaSO4 / Ca3(PO4)2 làm mất dinh dưỡng và tắc béc nhỏ giọt','Gây kết tủa CaSO4 / Ca3(PO4)2 làm mất dinh dưỡng và tắc béc nhỏ giọt',1794030801),
(543,46,3,'deferredfeedback',3,1,1.0000000,0.0000000,1.0000000,0,'Khi trời nắng gắt nhiệt độ >33°C, người trồng cần điều chỉnh chế độ tưới Fertigation như thế nào là đúng kỹ thuật?\n: Chia nhiều lần tưới ngắn hơn và giảm nhẹ EC 0.2–0.3 mS/cm để tránh sốc mặn vùng rễ; Tăng gấp đôi EC lên 5.0 mS/cm; Ngừng tưới hoàn toàn từ sáng đến tối; Chỉ tưới 1 lần duy nhất lúc 21h đêm','Chia nhiều lần tưới ngắn hơn và giảm nhẹ EC 0.2–0.3 mS/cm để tránh sốc mặn vùng rễ','Chia nhiều lần tưới ngắn hơn và giảm nhẹ EC 0.2–0.3 mS/cm để tránh sốc mặn vùng rễ',1794030801),
(544,46,4,'deferredfeedback',4,1,1.0000000,0.0000000,1.0000000,0,'Tỷ lệ nước rỉ thoát đáy bầu giá thể (Drainage %) tiêu chuẩn trong canh tác nhà màng nhằm ngăn tích tụ muối là bao nhiêu?\n: 15% – 25%; 0% (không cho chảy giọt nào); 80% – 95%; 100%','15% – 25%','15% – 25%',1794030801),
(545,46,5,'deferredfeedback',5,1,1.0000000,0.0000000,1.0000000,0,'Triệu chứng cháy khô mép lá non xà lách (Tipburn) và thối đít trái cà chua/dưa lưới liên quan trực tiếp đến thiếu hụt nguyên tố nào?\n: Canxi (Ca); Đạm (N); Clo (Cl); Natri (Na)','Canxi (Ca)','Canxi (Ca)',1794030801),
(546,46,6,'deferredfeedback',6,1,1.0000000,0.0000000,1.0000000,0,'Bộ lọc đĩa trong hệ thống tưới nhỏ giọt công nghệ cao cần cấp độ mịn tối thiểu bao nhiêu để bảo vệ đầu nhỏ giọt bù áp?\n: 120 – 150 mesh; 10 mesh; 20 mesh; Không cần lắp bộ lọc','120 – 150 mesh','120 – 150 mesh',1794030801),
(547,46,7,'deferredfeedback',7,1,1.0000000,0.0000000,1.0000000,0,'Biện pháp giám sát và phòng trừ sinh học hiệu quả nhất đối với Bọ trĩ (Thrips) hại đọt non trong nhà màng là gì?\n: Treo bẫy dính xanh dương/vàng kết hợp phun nấm ký sinh Beauveria/Metarhizium và dầu Neem; Phun thuốc diệt cỏ liều cao; Đóng kín toàn bộ quạt thông gió tăng nhiệt lên 48°C; Tưới nước mặn vào ngọn cây','Treo bẫy dính xanh dương/vàng kết hợp phun nấm ký sinh Beauveria/Metarhizium và dầu Neem','Treo bẫy dính xanh dương/vàng kết hợp phun nấm ký sinh Beauveria/Metarhizium và dầu Neem',1794030801),
(548,46,8,'deferredfeedback',8,1,1.0000000,0.0000000,1.0000000,0,'Để xử lý lớp sáp trắng bảo vệ trên cơ thể Rệp sáp theo hướng an toàn VietGAP, nên phối hợp vật tư sinh học nào?\n: Dầu khoáng sinh học 0.3% kết hợp nấm trắng Beauveria bassiana và chặn kiến cộng sinh; Bón thật nhiều phân Urê vào lá; Tưới nước đá lạnh buổi trưa; Chỉ phun nước lã không cần vệ sinh cành','Dầu khoáng sinh học 0.3% kết hợp nấm trắng Beauveria bassiana và chặn kiến cộng sinh','Dầu khoáng sinh học 0.3% kết hợp nấm trắng Beauveria bassiana và chặn kiến cộng sinh',1794030801),
(549,46,9,'deferredfeedback',9,1,1.0000000,0.0000000,1.0000000,0,'Nấm đối kháng Trichoderma spp. phát huy hiệu quả tốt nhất khi xử lý bệnh nào vùng rễ?\n: Phòng trừ nấm đất Phytophthora, Fusarium, Pythium gây lở cổ rễ và thối rễ; Trị sâu đục quả trưởng thành bay trên ngọn; Thay thế hoàn toàn phân Kali; Làm chín ép trái cây trong 2 giờ','Phòng trừ nấm đất Phytophthora, Fusarium, Pythium gây lở cổ rễ và thối rễ','Phòng trừ nấm đất Phytophthora, Fusarium, Pythium gây lở cổ rễ và thối rễ',1794030801),
(550,46,10,'deferredfeedback',10,1,1.0000000,0.0000000,1.0000000,0,'Vì sao nên kết thúc chu kỳ tưới nhỏ giọt cuối cùng trong ngày trước 15:30–16:00 chiều đối với dưa lưới/cà chua?\n: Để giá thể thông thoáng đủ oxy cho rễ ban đêm, hạn chế ẩm độ cao gây nấm và nứt trái; Vì máy bơm không hoạt động buổi chiều; Để tăng EC vùng rễ lên 10 mS/cm; Để lá cây héo rũ qua đêm','Để giá thể thông thoáng đủ oxy cho rễ ban đêm, hạn chế ẩm độ cao gây nấm và nứt trái','Để giá thể thông thoáng đủ oxy cho rễ ban đêm, hạn chế ẩm độ cao gây nấm và nứt trái',1794030801),
(551,46,11,'deferredfeedback',11,1,1.0000000,0.0000000,1.0000000,0,'Theo quy định VietGAP, chỉ số PHI (Pre-Harvest Interval) trên nhật ký canh tác có ý nghĩa là gì?\n: Thời gian cách ly an toàn từ lần phun cuối cùng đến khi được phép thu hoạch; Tổng diện tích nhà màng tính bằng ha; Áp suất đường ống chính tính bằng bar; Số lượng béc tưới trên một hàng','Thời gian cách ly an toàn từ lần phun cuối cùng đến khi được phép thu hoạch','Tổng diện tích nhà màng tính bằng ha',1794030801),
(552,46,12,'deferredfeedback',12,1,1.0000000,0.0000000,1.0000000,0,'Tiêu chuẩn cây giống khỏe trước khi đem trồng ra nhà màng công nghệ cao gồm đặc điểm nào sau đây?\n: Thân mập thẳng, bầu rễ trắng phát triển mạnh, sạch sâu bệnh và đã huấn luyện thích nghi ánh sáng; Rễ thâm nâu có mùi chua và lá non xoăn vàng; Cây vươn lóng dài yếu ớt do thiếu sáng; Giá thể nhiễm mặn EC > 4.0 mS/cm','Thân mập thẳng, bầu rễ trắng phát triển mạnh, sạch sâu bệnh và đã huấn luyện thích nghi ánh sáng','Rễ thâm nâu có mùi chua và lá non xoăn vàng',1794030801),
(553,47,1,'deferredfeedback',13,1,1.0000000,0.0000000,1.0000000,0,'Mục đích cốt lõi của công đoạn làm mát sơ bộ (Pre-cooling) trong vòng 2 giờ đầu sau thu hoạch là gì?\n: Nhanh chóng rút nhiệt đồng ruộng, giảm cường độ hô hấp và sự mất nước của nông sản; Làm chín nhanh toàn bộ lô hàng trong 1 giờ; Tăng hàm lượng nước tự do đọng trên mặt lá; Làm đông cứng rau ăn lá ở -20°C','Nhanh chóng rút nhiệt đồng ruộng, giảm cường độ hô hấp và sự mất nước của nông sản','Nhanh chóng rút nhiệt đồng ruộng, giảm cường độ hô hấp và sự mất nước của nông sản',1794030801),
(554,47,2,'deferredfeedback',14,1,1.0000000,0.0000000,1.0000000,0,'Phương pháp làm mát sơ bộ nào giúp hạ nhiệt rau ăn lá (xà lách, cải bó xôi) từ 28°C xuống 3°C nhanh nhất (chỉ 20–30 phút)?\n: Làm mát chân không (Vacuum Cooling); Phơi ngoài sân nắng; Ủ kín trong bao tải dứa; Đặt cạnh lò sấy nhiệt','Làm mát chân không (Vacuum Cooling)','Làm mát chân không (Vacuum Cooling)',1794030801),
(555,47,3,'deferredfeedback',15,1,1.0000000,0.0000000,1.0000000,0,'Nhiệt độ và ẩm độ kho mát tiêu chuẩn để bảo quản tươi nhóm rau ăn lá ôn đới (xà lách, cải thảo, bông cải) là bao nhiêu?\n: 2°C – 5°C và ẩm độ 90% – 95%; 22°C – 28°C và ẩm độ 40%; -18°C đóng băng hoàn toàn; 35°C và ẩm độ 99%','2°C – 5°C và ẩm độ 90% – 95%','2°C – 5°C và ẩm độ 90% – 95%',1794030801),
(556,47,4,'deferredfeedback',16,1,1.0000000,0.0000000,1.0000000,0,'Vì sao không được bảo quản trái cây nhiệt đới tươi nguyên quả (xoài, chuối, sầu riêng tươi) ở nhiệt độ quá thấp 0–4°C?\n: Gây hiện tượng tổn thương lạnh (Chilling Injury) làm thâm đen vỏ và sượng thịt quả; Làm trái nổ vỡ ngay lập tức; Làm tăng trọng lượng trái lên 200%; Vì kho lạnh không thể chỉnh dưới 15°C','Gây hiện tượng tổn thương lạnh (Chilling Injury) làm thâm đen vỏ và sượng thịt quả','Gây hiện tượng tổn thương lạnh (Chilling Injury) làm thâm đen vỏ và sượng thịt quả',1794030801),
(557,47,5,'deferredfeedback',17,1,1.0000000,0.0000000,1.0000000,0,'Nguyên lý chính của bao bì khí quyển biến đổi MAP (Modified Atmosphere Packaging) trong bảo quản rau quả tươi là gì?\n: Giảm nồng độ O2 (3–5%) và nâng nhẹ CO2 (5–8%) để làm chậm hô hấp và ức chế vi sinh gây hư hỏng; Bơm 100% khí Ethylene vào túi để thúc chín; Hút kiệt tạo áp suất nén nát lá rau; Bơm không khí nóng 60°C vào bao bì','Giảm nồng độ O2 (3–5%) và nâng nhẹ CO2 (5–8%) để làm chậm hô hấp và ức chế vi sinh gây hư hỏng','Giảm nồng độ O2 (3–5%) và nâng nhẹ CO2 (5–8%) để làm chậm hô hấp và ức chế vi sinh gây hư hỏng',1794030801),
(558,47,6,'deferredfeedback',18,1,1.0000000,0.0000000,1.0000000,0,'Công nghệ sấy lạnh bơm nhiệt (Heat-Pump Drying) vận hành ở dải nhiệt độ nào để bảo toàn màu sắc và Vitamin?\n: 25°C – 42°C với không khí tách ẩm khô tuần hoàn kín; 120°C – 180°C bằng than đá; 95°C – 110°C ngoài trời; -40°C không tách ẩm','25°C – 42°C với không khí tách ẩm khô tuần hoàn kín','25°C – 42°C với không khí tách ẩm khô tuần hoàn kín',1794030801),
(559,47,7,'deferredfeedback',19,1,1.0000000,0.0000000,1.0000000,0,'Tại sao không nên xếp chung kho lạnh giữa các trái sinh nhiều khí Ethylene (chuối chín, sầu riêng) với rau ăn lá hoặc dưa leo?\n: Khí Ethylene kích thích vàng lá, rụng cuống và làm già hóa hư hỏng nhanh rau ăn lá; Làm kho lạnh tiêu tốn ít điện hơn; Làm dưa leo ngọt thành dưa lưới; Không có bất kỳ tác động sinh lý nào','Khí Ethylene kích thích vàng lá, rụng cuống và làm già hóa hư hỏng nhanh rau ăn lá','Khí Ethylene kích thích vàng lá, rụng cuống và làm già hóa hư hỏng nhanh rau ăn lá',1794030801),
(560,47,8,'deferredfeedback',20,1,1.0000000,0.0000000,1.0000000,0,'Công nghệ cấp đông siêu tốc IQF (-35°C đến -40°C) giúp múi sầu riêng xuất khẩu đạt chất lượng vượt trội nhờ cơ chế nào?\n: Hình thành vi tinh thể băng cực nhỏ không phá vỡ màng tế bào, không chảy dịch khi rã đông; Rút hết toàn bộ hương thơm của sầu riêng; Biến tinh bột thành chất xơ gỗ; Không cần bảo quản lạnh sau cấp đông','Hình thành vi tinh thể băng cực nhỏ không phá vỡ màng tế bào, không chảy dịch khi rã đông','Hình thành vi tinh thể băng cực nhỏ không phá vỡ màng tế bào, không chảy dịch khi rã đông',1794030801),
(561,47,9,'deferredfeedback',21,1,1.0000000,0.0000000,1.0000000,0,'Nguyên tắc thiết kế mặt bằng nhà xưởng sơ chế nông sản đạt chuẩn HACCP / ISO 22000 là gì?\n: Nguyên tắc dòng chảy 1 chiều từ khu nguyên liệu sang khu sạch đóng gói, không nhiễm chéo; Nhập nguyên liệu và xuất thành phẩm chung một bàn sơ chế đất; Đặt kho thuốc BVTV ngay trong phòng đóng gói; Không cần khử trùng dao kéo thu hoạch','Nguyên tắc dòng chảy 1 chiều từ khu nguyên liệu sang khu sạch đóng gói, không nhiễm chéo','Nguyên tắc dòng chảy 1 chiều từ khu nguyên liệu sang khu sạch đóng gói, không nhiễm chéo',1794030801),
(562,47,10,'deferredfeedback',22,1,1.0000000,0.0000000,1.0000000,0,'Trước khi đóng gói rau ăn lá vào túi màng MAP, yêu cầu bắt buộc đối với bề mặt lá sau khi rửa là gì?\n: Phải làm ráo hoàn toàn nước tự do đọng trên lá (ly tâm/quạt lạnh) để ngừa thối nhũn vi khuẩn; Để nguyên nước ướt sũng trong túi kín; Phun nước đường lên mặt lá; Phơi nắng trưa 35°C trong 2 giờ','Phải làm ráo hoàn toàn nước tự do đọng trên lá (ly tâm/quạt lạnh) để ngừa thối nhũn vi khuẩn','Phải làm ráo hoàn toàn nước tự do đọng trên lá (ly tâm/quạt lạnh) để ngừa thối nhũn vi khuẩn',1794030801),
(563,47,11,'deferredfeedback',23,1,1.0000000,0.0000000,1.0000000,0,'Thiết bị nào bắt buộc gắn trong container lạnh xuất khẩu đường biển để minh chứng chuỗi lạnh không bị đứt gãy?\n: Thiết bị ghi hành trình nhiệt độ - ẩm độ tự động (DataLogger); Bình tưới cây cầm tay; Bẫy dính côn trùng màu vàng; Bút thử độ mặn đất','Thiết bị ghi hành trình nhiệt độ - ẩm độ tự động (DataLogger)','Bình tưới cây cầm tay',1794030801),
(564,47,12,'deferredfeedback',24,1,1.0000000,0.0000000,1.0000000,0,'Thông tin nào cần hiển thị công khai khi người tiêu dùng quét mã QR truy xuất nguồn gốc trên bao bì nông sản VietGAP?\n: Mã lô sản xuất, tên nông hộ & tọa độ vùng trồng, lịch sử nhật ký canh tác, ngày thu hoạch & chuẩn an toàn; Mật khẩu quản trị hệ thống của nông trại; Số tài khoản cá nhân của tài xế; Chỉ hiển thị một bức ảnh tĩnh không có dữ liệu lô','Mã lô sản xuất, tên nông hộ & tọa độ vùng trồng, lịch sử nhật ký canh tác, ngày thu hoạch & chuẩn an toàn','Mật khẩu quản trị hệ thống của nông trại',1794030801),
(565,48,1,'deferredfeedback',25,1,1.0000000,0.0000000,1.0000000,0,'Chỉ số VPD (Vapor Pressure Deficit) tối ưu cho giai đoạn sinh trưởng và nuôi trái trong nhà màng nằm trong khoảng nào?\n: 0.8 – 1.2 kPa; 0.0 – 0.1 kPa; 3.5 – 5.0 kPa; 8.0 – 10.0 kPa','0.8 – 1.2 kPa','0.8 – 1.2 kPa',1794030802),
(566,48,2,'deferredfeedback',26,1,1.0000000,0.0000000,1.0000000,0,'Vị trí lắp đặt cảm biến nhiệt độ - ẩm độ trong nhà màng như thế nào là đúng chuẩn kỹ thuật?\n: Đặt trong hộp chắn bức xạ thông gió ở ngang tầm ngọn cây đang phát triển; Phơi trần trực tiếp dưới nắng trưa sát mái nilon; Ngâm ngập dưới đáy bể chứa nước; Đặt bên ngoài nhà văn phòng cách vườn 500m','Đặt trong hộp chắn bức xạ thông gió ở ngang tầm ngọn cây đang phát triển','Đặt trong hộp chắn bức xạ thông gió ở ngang tầm ngọn cây đang phát triển',1794030802),
(567,48,3,'deferredfeedback',27,1,1.0000000,0.0000000,1.0000000,0,'Mục đích thiết kế buồng đệm 2 cửa so le (Double-door airlock) ở lối vào nhà màng là gì?\n: Ngăn côn trùng chích hút (bọ trĩ, bọ phấn) bay theo người lao động xâm nhập vào nhà màng; Để trang trí cho đẹp mắt; Để giữ nhiệt độ nhà màng luôn ở 45°C; Thay thế hoàn toàn hệ thống tưới','Ngăn côn trùng chích hút (bọ trĩ, bọ phấn) bay theo người lao động xâm nhập vào nhà màng','Ngăn côn trùng chích hút (bọ trĩ, bọ phấn) bay theo người lao động xâm nhập vào nhà màng',1794030802),
(568,48,4,'deferredfeedback',28,1,1.0000000,0.0000000,1.0000000,0,'Cấp độ mắt lưới chắn côn trùng tiêu chuẩn dùng cho vách nhà màng trồng dưa lưới/rau công nghệ cao để chặn bọ trĩ là bao nhiêu?\n: 50 mesh; 4 mesh; 10 mesh; Không dùng lưới vách','50 mesh','50 mesh',1794030802),
(569,48,5,'deferredfeedback',29,1,1.0000000,0.0000000,1.0000000,0,'Khi ẩm độ trong nhà màng lên quá cao >92% vào sáng sớm (VPD < 0.3 kPa), nguy cơ lớn nhất đối với cây trồng là gì?\n: Đọng sương trên lá làm bùng phát nấm Sương mai, Gỉ sắt, Mốc xám Botrytis và giảm hút Canxi; Cây hút quá nhiều Canxi; Béc tưới chạy nhanh gấp đôi; Độ đường trái tăng đột biến','Đọng sương trên lá làm bùng phát nấm Sương mai, Gỉ sắt, Mốc xám Botrytis và giảm hút Canxi','Đọng sương trên lá làm bùng phát nấm Sương mai, Gỉ sắt, Mốc xám Botrytis và giảm hút Canxi',1794030802),
(570,48,6,'deferredfeedback',30,1,1.0000000,0.0000000,1.0000000,0,'Hệ thống rèm lưới cắt nắng tự động nên được lập trình đóng lại khi nào?\n: Khi bức xạ nắng trưa vượt ngưỡng cao (>45.000 Lux / nhiệt >33°C) và mở ra khi nắng dịu; Đóng kín suốt 24/24 giờ cả ngày lẫn đêm; Chỉ đóng vào ban đêm lúc 22h; Chỉ đóng khi trời mưa râm mát','Khi bức xạ nắng trưa vượt ngưỡng cao (>45.000 Lux / nhiệt >33°C) và mở ra khi nắng dịu','Khi bức xạ nắng trưa vượt ngưỡng cao (>45.000 Lux / nhiệt >33°C) và mở ra khi nắng dịu',1794030802),
(571,48,7,'deferredfeedback',31,1,1.0000000,0.0000000,1.0000000,0,'Ưu điểm của hệ thống phun sương cao áp (70 bar, hạt <10 micron) so với vòi phun nước hạt lớn thông thường là gì?\n: Hạt sương siêu mịn bay hơi làm mát không khí tức thì mà không làm đọng nước ướt lá gây bệnh; Làm ngập sũng lối đi nhà màng; Tốn nước gấp 10 lần tưới tràn; Không làm giảm nhiệt độ','Hạt sương siêu mịn bay hơi làm mát không khí tức thì mà không làm đọng nước ướt lá gây bệnh','Hạt sương siêu mịn bay hơi làm mát không khí tức thì mà không làm đọng nước ướt lá gây bệnh',1794030802),
(572,48,8,'deferredfeedback',32,1,1.0000000,0.0000000,1.0000000,0,'Trong tủ điện điều khiển nhà màng IoT, vì sao bắt buộc phải thiết kế công tắc chuyển mạch AUTO - OFF - MANUAL?\n: Đảm bảo vẫn vận hành tay được bơm tưới và quạt thông gió an toàn khi mất mạng hoặc bảo trì PLC; Để tăng tiền điện hàng tháng; Để vô hiệu hóa cảm biến vĩnh viễn; Chỉ dùng để bật đèn chiếu sáng văn phòng','Đảm bảo vẫn vận hành tay được bơm tưới và quạt thông gió an toàn khi mất mạng hoặc bảo trì PLC','Đảm bảo vẫn vận hành tay được bơm tưới và quạt thông gió an toàn khi mất mạng hoặc bảo trì PLC',1794030802),
(573,48,9,'deferredfeedback',33,1,1.0000000,0.0000000,1.0000000,0,'Nếu nhà màng đóng kín hoàn toàn không trao đổi khí suốt buổi sáng nắng đẹp, yếu tố nào giảm mạnh làm chậm quang hợp?\n: Nồng độ khí CO2 trong nhà màng sụt giảm dưới ngưỡng tự nhiên (<250 ppm); Khí Nitơ biến mất hoàn toàn; Độ pH nước tăng lên 14; Trọng lực giảm','Nồng độ khí CO2 trong nhà màng sụt giảm dưới ngưỡng tự nhiên (<250 ppm)','Nồng độ khí CO2 trong nhà màng sụt giảm dưới ngưỡng tự nhiên (<250 ppm)',1794030802),
(574,48,10,'deferredfeedback',34,1,1.0000000,0.0000000,1.0000000,0,'Cài đặt khoảng trễ (Hysteresis, ví dụ bật quạt ở 31°C và tắt ở 29.5°C) trong bộ điều khiển tự động nhằm mục đích gì?\n: Chống đóng/ngắt rơ-le liên tục (chattering) giúp bảo vệ tuổi thọ động cơ quạt và khởi động từ; Làm hỏng cảm biến nhanh hơn; Tăng sai số đo nhiệt độ lên 10°C; Tắt toàn bộ cảnh báo điện thoại','Chống đóng/ngắt rơ-le liên tục (chattering) giúp bảo vệ tuổi thọ động cơ quạt và khởi động từ','Làm hỏng cảm biến nhanh hơn',1794030802),
(575,48,11,'deferredfeedback',35,1,1.0000000,0.0000000,1.0000000,0,'Bao lâu cần vệ sinh bụi bẩn bám trên mái màng PE nhà màng để duy trì hiệu suất truyền ánh sáng PAR?\n: Định kỳ mỗi 3–6 tháng (đặc biệt trong mùa khô bụi) để giữ độ truyền sáng >85%; Không bao giờ rửa trong 10 năm; Sơn đen kín toàn bộ mái màng PE; Mỗi giờ rửa 1 lần bằng axit đặc','Định kỳ mỗi 3–6 tháng (đặc biệt trong mùa khô bụi) để giữ độ truyền sáng >85%','Không bao giờ rửa trong 10 năm',1794030802),
(576,48,12,'deferredfeedback',36,1,1.0000000,0.0000000,1.0000000,0,'Khi nhận tin nhắn cảnh báo mất áp suất đường ống chính từ bộ điều khiển IoT lúc đang tưới, cần kiểm tra ngay điều gì?\n: Kiểm tra nguồn nước cấp, rò rỉ vỡ ống chính hoặc nghẹt bầu lọc đĩa đầu nguồn; Xóa ứng dụng cảnh báo trên điện thoại; Bón thêm phân đạm vào gốc; Cắt bỏ toàn bộ lá non','Kiểm tra nguồn nước cấp, rò rỉ vỡ ống chính hoặc nghẹt bầu lọc đĩa đầu nguồn','Xóa ứng dụng cảnh báo trên điện thoại',1794030802),
(577,49,1,'deferredfeedback',1,1,1.0000000,0.0000000,1.0000000,0,'Khoảng pH dung dịch dinh dưỡng tối ưu giúp rễ cây trồng giá thể/nhà màng hấp thu cân đối đa-trung-vi lượng là bao nhiêu?\n: 5.8 – 6.2; 3.5 – 4.2; 7.5 – 8.5; 8.5 – 9.2','5.8 – 6.2','5.8 – 6.2',1794030802),
(578,49,2,'deferredfeedback',2,1,1.0000000,0.0000000,1.0000000,0,'Vì sao tuyệt đối KHÔNG pha chung đậm đặc phân Canxi Nitrat (Bồn A) với phân chứa gốc Sunfat/Photphat (Bồn B)?\n: Gây kết tủa CaSO4 / Ca3(PO4)2 làm mất dinh dưỡng và tắc béc nhỏ giọt; Làm dung dịch bay hơi hết nước; Làm giảm nhiệt độ nhà màng xuống 0°C; Không có ảnh hưởng gì','Gây kết tủa CaSO4 / Ca3(PO4)2 làm mất dinh dưỡng và tắc béc nhỏ giọt','Gây kết tủa CaSO4 / Ca3(PO4)2 làm mất dinh dưỡng và tắc béc nhỏ giọt',1794030802),
(579,49,3,'deferredfeedback',3,1,1.0000000,0.0000000,1.0000000,0,'Khi trời nắng gắt nhiệt độ >33°C, người trồng cần điều chỉnh chế độ tưới Fertigation như thế nào là đúng kỹ thuật?\n: Chia nhiều lần tưới ngắn hơn và giảm nhẹ EC 0.2–0.3 mS/cm để tránh sốc mặn vùng rễ; Tăng gấp đôi EC lên 5.0 mS/cm; Ngừng tưới hoàn toàn từ sáng đến tối; Chỉ tưới 1 lần duy nhất lúc 21h đêm','Chia nhiều lần tưới ngắn hơn và giảm nhẹ EC 0.2–0.3 mS/cm để tránh sốc mặn vùng rễ','Chia nhiều lần tưới ngắn hơn và giảm nhẹ EC 0.2–0.3 mS/cm để tránh sốc mặn vùng rễ',1794030802),
(580,49,4,'deferredfeedback',4,1,1.0000000,0.0000000,1.0000000,0,'Tỷ lệ nước rỉ thoát đáy bầu giá thể (Drainage %) tiêu chuẩn trong canh tác nhà màng nhằm ngăn tích tụ muối là bao nhiêu?\n: 15% – 25%; 0% (không cho chảy giọt nào); 80% – 95%; 100%','15% – 25%','15% – 25%',1794030802),
(581,49,5,'deferredfeedback',5,1,1.0000000,0.0000000,1.0000000,0,'Triệu chứng cháy khô mép lá non xà lách (Tipburn) và thối đít trái cà chua/dưa lưới liên quan trực tiếp đến thiếu hụt nguyên tố nào?\n: Canxi (Ca); Đạm (N); Clo (Cl); Natri (Na)','Canxi (Ca)','Canxi (Ca)',1794030802),
(582,49,6,'deferredfeedback',6,1,1.0000000,0.0000000,1.0000000,0,'Bộ lọc đĩa trong hệ thống tưới nhỏ giọt công nghệ cao cần cấp độ mịn tối thiểu bao nhiêu để bảo vệ đầu nhỏ giọt bù áp?\n: 120 – 150 mesh; 10 mesh; 20 mesh; Không cần lắp bộ lọc','120 – 150 mesh','120 – 150 mesh',1794030802),
(583,49,7,'deferredfeedback',7,1,1.0000000,0.0000000,1.0000000,0,'Biện pháp giám sát và phòng trừ sinh học hiệu quả nhất đối với Bọ trĩ (Thrips) hại đọt non trong nhà màng là gì?\n: Treo bẫy dính xanh dương/vàng kết hợp phun nấm ký sinh Beauveria/Metarhizium và dầu Neem; Phun thuốc diệt cỏ liều cao; Đóng kín toàn bộ quạt thông gió tăng nhiệt lên 48°C; Tưới nước mặn vào ngọn cây','Treo bẫy dính xanh dương/vàng kết hợp phun nấm ký sinh Beauveria/Metarhizium và dầu Neem','Treo bẫy dính xanh dương/vàng kết hợp phun nấm ký sinh Beauveria/Metarhizium và dầu Neem',1794030802),
(584,49,8,'deferredfeedback',8,1,1.0000000,0.0000000,1.0000000,0,'Để xử lý lớp sáp trắng bảo vệ trên cơ thể Rệp sáp theo hướng an toàn VietGAP, nên phối hợp vật tư sinh học nào?\n: Dầu khoáng sinh học 0.3% kết hợp nấm trắng Beauveria bassiana và chặn kiến cộng sinh; Bón thật nhiều phân Urê vào lá; Tưới nước đá lạnh buổi trưa; Chỉ phun nước lã không cần vệ sinh cành','Dầu khoáng sinh học 0.3% kết hợp nấm trắng Beauveria bassiana và chặn kiến cộng sinh','Dầu khoáng sinh học 0.3% kết hợp nấm trắng Beauveria bassiana và chặn kiến cộng sinh',1794030802),
(585,49,9,'deferredfeedback',9,1,1.0000000,0.0000000,1.0000000,0,'Nấm đối kháng Trichoderma spp. phát huy hiệu quả tốt nhất khi xử lý bệnh nào vùng rễ?\n: Phòng trừ nấm đất Phytophthora, Fusarium, Pythium gây lở cổ rễ và thối rễ; Trị sâu đục quả trưởng thành bay trên ngọn; Thay thế hoàn toàn phân Kali; Làm chín ép trái cây trong 2 giờ','Phòng trừ nấm đất Phytophthora, Fusarium, Pythium gây lở cổ rễ và thối rễ','Phòng trừ nấm đất Phytophthora, Fusarium, Pythium gây lở cổ rễ và thối rễ',1794030802),
(586,49,10,'deferredfeedback',10,1,1.0000000,0.0000000,1.0000000,0,'Vì sao nên kết thúc chu kỳ tưới nhỏ giọt cuối cùng trong ngày trước 15:30–16:00 chiều đối với dưa lưới/cà chua?\n: Để giá thể thông thoáng đủ oxy cho rễ ban đêm, hạn chế ẩm độ cao gây nấm và nứt trái; Vì máy bơm không hoạt động buổi chiều; Để tăng EC vùng rễ lên 10 mS/cm; Để lá cây héo rũ qua đêm','Để giá thể thông thoáng đủ oxy cho rễ ban đêm, hạn chế ẩm độ cao gây nấm và nứt trái','Để giá thể thông thoáng đủ oxy cho rễ ban đêm, hạn chế ẩm độ cao gây nấm và nứt trái',1794030802),
(587,49,11,'deferredfeedback',11,1,1.0000000,0.0000000,1.0000000,0,'Theo quy định VietGAP, chỉ số PHI (Pre-Harvest Interval) trên nhật ký canh tác có ý nghĩa là gì?\n: Thời gian cách ly an toàn từ lần phun cuối cùng đến khi được phép thu hoạch; Tổng diện tích nhà màng tính bằng ha; Áp suất đường ống chính tính bằng bar; Số lượng béc tưới trên một hàng','Thời gian cách ly an toàn từ lần phun cuối cùng đến khi được phép thu hoạch','Thời gian cách ly an toàn từ lần phun cuối cùng đến khi được phép thu hoạch',1794030802),
(588,49,12,'deferredfeedback',12,1,1.0000000,0.0000000,1.0000000,0,'Tiêu chuẩn cây giống khỏe trước khi đem trồng ra nhà màng công nghệ cao gồm đặc điểm nào sau đây?\n: Thân mập thẳng, bầu rễ trắng phát triển mạnh, sạch sâu bệnh và đã huấn luyện thích nghi ánh sáng; Rễ thâm nâu có mùi chua và lá non xoăn vàng; Cây vươn lóng dài yếu ớt do thiếu sáng; Giá thể nhiễm mặn EC > 4.0 mS/cm','Thân mập thẳng, bầu rễ trắng phát triển mạnh, sạch sâu bệnh và đã huấn luyện thích nghi ánh sáng','Rễ thâm nâu có mùi chua và lá non xoăn vàng',1794030802),
(589,50,1,'deferredfeedback',25,1,1.0000000,0.0000000,1.0000000,0,'Chỉ số VPD (Vapor Pressure Deficit) tối ưu cho giai đoạn sinh trưởng và nuôi trái trong nhà màng nằm trong khoảng nào?\n: 0.8 – 1.2 kPa; 0.0 – 0.1 kPa; 3.5 – 5.0 kPa; 8.0 – 10.0 kPa','0.8 – 1.2 kPa','0.8 – 1.2 kPa',1794030803),
(590,50,2,'deferredfeedback',26,1,1.0000000,0.0000000,1.0000000,0,'Vị trí lắp đặt cảm biến nhiệt độ - ẩm độ trong nhà màng như thế nào là đúng chuẩn kỹ thuật?\n: Đặt trong hộp chắn bức xạ thông gió ở ngang tầm ngọn cây đang phát triển; Phơi trần trực tiếp dưới nắng trưa sát mái nilon; Ngâm ngập dưới đáy bể chứa nước; Đặt bên ngoài nhà văn phòng cách vườn 500m','Đặt trong hộp chắn bức xạ thông gió ở ngang tầm ngọn cây đang phát triển','Đặt trong hộp chắn bức xạ thông gió ở ngang tầm ngọn cây đang phát triển',1794030803),
(591,50,3,'deferredfeedback',27,1,1.0000000,0.0000000,1.0000000,0,'Mục đích thiết kế buồng đệm 2 cửa so le (Double-door airlock) ở lối vào nhà màng là gì?\n: Ngăn côn trùng chích hút (bọ trĩ, bọ phấn) bay theo người lao động xâm nhập vào nhà màng; Để trang trí cho đẹp mắt; Để giữ nhiệt độ nhà màng luôn ở 45°C; Thay thế hoàn toàn hệ thống tưới','Ngăn côn trùng chích hút (bọ trĩ, bọ phấn) bay theo người lao động xâm nhập vào nhà màng','Ngăn côn trùng chích hút (bọ trĩ, bọ phấn) bay theo người lao động xâm nhập vào nhà màng',1794030803),
(592,50,4,'deferredfeedback',28,1,1.0000000,0.0000000,1.0000000,0,'Cấp độ mắt lưới chắn côn trùng tiêu chuẩn dùng cho vách nhà màng trồng dưa lưới/rau công nghệ cao để chặn bọ trĩ là bao nhiêu?\n: 50 mesh; 4 mesh; 10 mesh; Không dùng lưới vách','50 mesh','50 mesh',1794030803),
(593,50,5,'deferredfeedback',29,1,1.0000000,0.0000000,1.0000000,0,'Khi ẩm độ trong nhà màng lên quá cao >92% vào sáng sớm (VPD < 0.3 kPa), nguy cơ lớn nhất đối với cây trồng là gì?\n: Đọng sương trên lá làm bùng phát nấm Sương mai, Gỉ sắt, Mốc xám Botrytis và giảm hút Canxi; Cây hút quá nhiều Canxi; Béc tưới chạy nhanh gấp đôi; Độ đường trái tăng đột biến','Đọng sương trên lá làm bùng phát nấm Sương mai, Gỉ sắt, Mốc xám Botrytis và giảm hút Canxi','Đọng sương trên lá làm bùng phát nấm Sương mai, Gỉ sắt, Mốc xám Botrytis và giảm hút Canxi',1794030803),
(594,50,6,'deferredfeedback',30,1,1.0000000,0.0000000,1.0000000,0,'Hệ thống rèm lưới cắt nắng tự động nên được lập trình đóng lại khi nào?\n: Khi bức xạ nắng trưa vượt ngưỡng cao (>45.000 Lux / nhiệt >33°C) và mở ra khi nắng dịu; Đóng kín suốt 24/24 giờ cả ngày lẫn đêm; Chỉ đóng vào ban đêm lúc 22h; Chỉ đóng khi trời mưa râm mát','Khi bức xạ nắng trưa vượt ngưỡng cao (>45.000 Lux / nhiệt >33°C) và mở ra khi nắng dịu','Khi bức xạ nắng trưa vượt ngưỡng cao (>45.000 Lux / nhiệt >33°C) và mở ra khi nắng dịu',1794030803),
(595,50,7,'deferredfeedback',31,1,1.0000000,0.0000000,1.0000000,0,'Ưu điểm của hệ thống phun sương cao áp (70 bar, hạt <10 micron) so với vòi phun nước hạt lớn thông thường là gì?\n: Hạt sương siêu mịn bay hơi làm mát không khí tức thì mà không làm đọng nước ướt lá gây bệnh; Làm ngập sũng lối đi nhà màng; Tốn nước gấp 10 lần tưới tràn; Không làm giảm nhiệt độ','Hạt sương siêu mịn bay hơi làm mát không khí tức thì mà không làm đọng nước ướt lá gây bệnh','Hạt sương siêu mịn bay hơi làm mát không khí tức thì mà không làm đọng nước ướt lá gây bệnh',1794030803),
(596,50,8,'deferredfeedback',32,1,1.0000000,0.0000000,1.0000000,0,'Trong tủ điện điều khiển nhà màng IoT, vì sao bắt buộc phải thiết kế công tắc chuyển mạch AUTO - OFF - MANUAL?\n: Đảm bảo vẫn vận hành tay được bơm tưới và quạt thông gió an toàn khi mất mạng hoặc bảo trì PLC; Để tăng tiền điện hàng tháng; Để vô hiệu hóa cảm biến vĩnh viễn; Chỉ dùng để bật đèn chiếu sáng văn phòng','Đảm bảo vẫn vận hành tay được bơm tưới và quạt thông gió an toàn khi mất mạng hoặc bảo trì PLC','Đảm bảo vẫn vận hành tay được bơm tưới và quạt thông gió an toàn khi mất mạng hoặc bảo trì PLC',1794030803),
(597,50,9,'deferredfeedback',33,1,1.0000000,0.0000000,1.0000000,0,'Nếu nhà màng đóng kín hoàn toàn không trao đổi khí suốt buổi sáng nắng đẹp, yếu tố nào giảm mạnh làm chậm quang hợp?\n: Nồng độ khí CO2 trong nhà màng sụt giảm dưới ngưỡng tự nhiên (<250 ppm); Khí Nitơ biến mất hoàn toàn; Độ pH nước tăng lên 14; Trọng lực giảm','Nồng độ khí CO2 trong nhà màng sụt giảm dưới ngưỡng tự nhiên (<250 ppm)','Nồng độ khí CO2 trong nhà màng sụt giảm dưới ngưỡng tự nhiên (<250 ppm)',1794030803),
(598,50,10,'deferredfeedback',34,1,1.0000000,0.0000000,1.0000000,0,'Cài đặt khoảng trễ (Hysteresis, ví dụ bật quạt ở 31°C và tắt ở 29.5°C) trong bộ điều khiển tự động nhằm mục đích gì?\n: Chống đóng/ngắt rơ-le liên tục (chattering) giúp bảo vệ tuổi thọ động cơ quạt và khởi động từ; Làm hỏng cảm biến nhanh hơn; Tăng sai số đo nhiệt độ lên 10°C; Tắt toàn bộ cảnh báo điện thoại','Chống đóng/ngắt rơ-le liên tục (chattering) giúp bảo vệ tuổi thọ động cơ quạt và khởi động từ','Chống đóng/ngắt rơ-le liên tục (chattering) giúp bảo vệ tuổi thọ động cơ quạt và khởi động từ',1794030803),
(599,50,11,'deferredfeedback',35,1,1.0000000,0.0000000,1.0000000,0,'Bao lâu cần vệ sinh bụi bẩn bám trên mái màng PE nhà màng để duy trì hiệu suất truyền ánh sáng PAR?\n: Định kỳ mỗi 3–6 tháng (đặc biệt trong mùa khô bụi) để giữ độ truyền sáng >85%; Không bao giờ rửa trong 10 năm; Sơn đen kín toàn bộ mái màng PE; Mỗi giờ rửa 1 lần bằng axit đặc','Định kỳ mỗi 3–6 tháng (đặc biệt trong mùa khô bụi) để giữ độ truyền sáng >85%','Định kỳ mỗi 3–6 tháng (đặc biệt trong mùa khô bụi) để giữ độ truyền sáng >85%',1794030803),
(600,50,12,'deferredfeedback',36,1,1.0000000,0.0000000,1.0000000,0,'Khi nhận tin nhắn cảnh báo mất áp suất đường ống chính từ bộ điều khiển IoT lúc đang tưới, cần kiểm tra ngay điều gì?\n: Kiểm tra nguồn nước cấp, rò rỉ vỡ ống chính hoặc nghẹt bầu lọc đĩa đầu nguồn; Xóa ứng dụng cảnh báo trên điện thoại; Bón thêm phân đạm vào gốc; Cắt bỏ toàn bộ lá non','Kiểm tra nguồn nước cấp, rò rỉ vỡ ống chính hoặc nghẹt bầu lọc đĩa đầu nguồn','Kiểm tra nguồn nước cấp, rò rỉ vỡ ống chính hoặc nghẹt bầu lọc đĩa đầu nguồn',1794030803),
(601,51,1,'deferredfeedback',37,1,1.0000000,0.0000000,1.0000000,0,'Độ dốc lắp đặt tiêu chuẩn của máng thủy canh hồi lưu NFT để tạo màng dinh dưỡng chảy đều không đọng vũng là bao nhiêu?\n: 2.0% – 2.5% (tỷ lệ khoảng 1:40); 0% (nằm ngang hoàn toàn đọng đầy nước); 45% (dốc đứng); 80%','2.0% – 2.5% (tỷ lệ khoảng 1:40)','2.0% – 2.5% (tỷ lệ khoảng 1:40)',1794030803),
(602,51,2,'deferredfeedback',38,1,1.0000000,0.0000000,1.0000000,0,'Hàm lượng Oxy hòa tan (DO) tối thiểu cần duy trì trong dung dịch thủy canh để bộ rễ trắng khỏe không bị thối ngạt là bao nhiêu?\n: >= 6.0 mg/L; 0.0 mg/L; 0.5 mg/L; Chỉ cần khí CO2 không cần Oxy','>= 6.0 mg/L','>= 6.0 mg/L',1794030803),
(603,51,3,'deferredfeedback',39,1,1.0000000,0.0000000,1.0000000,0,'Vì sao chiều dài mỗi máng thủy canh NFT thương mại không nên vượt quá 12–15 mét?\n: Tránh chênh lệch nhiệt độ tăng cao và cạn kiệt oxy hòa tan ở các hốc cây cuối máng; Vì ống nhựa không thể nối dài hơn 2m; Để giảm ánh sáng mặt trời; Vì cây đầu máng không hút được nước','Tránh chênh lệch nhiệt độ tăng cao và cạn kiệt oxy hòa tan ở các hốc cây cuối máng','Tránh chênh lệch nhiệt độ tăng cao và cạn kiệt oxy hòa tan ở các hốc cây cuối máng',1794030803),
(604,51,4,'deferredfeedback',40,1,1.0000000,0.0000000,1.0000000,0,'Khi xử lý giá thể mụn xơ dừa trước khi trồng dưa lưới/cà chua, chỉ số EC nước xả cuối cùng cần đạt mức nào?\n: EC < 0.5 mS/cm và đã ngâm đệm loại bỏ Tanin/muối Na+; EC > 5.0 mS/cm; Giữ nguyên toàn bộ muối chát tự nhiên; Trộn thêm muối ăn NaCl vào xơ dừa','EC < 0.5 mS/cm và đã ngâm đệm loại bỏ Tanin/muối Na+','EC < 0.5 mS/cm và đã ngâm đệm loại bỏ Tanin/muối Na+',1794030803),
(605,51,5,'deferredfeedback',41,1,1.0000000,0.0000000,1.0000000,0,'Nguyên nhân hàng đầu làm bùng phát nấm nước Pythium gây thối tuột rễ trên giàn thủy canh vào mùa nắng nóng là gì?\n: Nhiệt độ dung dịch dinh dưỡng tăng cao (>30°C) làm giảm mạnh nồng độ oxy hòa tan DO; Nhiệt độ nước mát 22°C giàu oxy; Độ pH ổn định ở 6.0; Ánh sáng buổi sáng dịu nhẹ','Nhiệt độ dung dịch dinh dưỡng tăng cao (>30°C) làm giảm mạnh nồng độ oxy hòa tan DO','Nhiệt độ dung dịch dinh dưỡng tăng cao (>30°C) làm giảm mạnh nồng độ oxy hòa tan DO',1794030803),
(606,51,6,'deferredfeedback',42,1,1.0000000,0.0000000,1.0000000,0,'Vi lượng nào đóng vai trò thiết yếu cấu tạo enzyme Nitrate Reductase giúp cây rau chuyển hóa Nitrat (NO3-) giảm tồn dư trong lá?\n: Molypden (Mo) kết hợp đủ ánh sáng quang hợp; Chì (Pb); Thủy ngân (Hg); Nhôm (Al)','Molypden (Mo) kết hợp đủ ánh sáng quang hợp','Molypden (Mo) kết hợp đủ ánh sáng quang hợp',1794030803),
(607,51,7,'deferredfeedback',43,1,1.0000000,0.0000000,1.0000000,0,'Máng nhựa dùng trong hệ thống thủy canh rau ăn lá chuẩn VietGAP phải đáp ứng yêu cầu vật liệu nào?\n: Nhựa uPVC chuyên dụng an toàn thực phẩm, không thôi nhiễm chì/kim loại nặng, lòng tối chống rêu; Ống nhựa tái chế phế thải công nghiệp chứa chì; Máng tôn gỉ sét; Máng gỗ mục tẩm dầu nhớt','Nhựa uPVC chuyên dụng an toàn thực phẩm, không thôi nhiễm chì/kim loại nặng, lòng tối chống rêu','Nhựa uPVC chuyên dụng an toàn thực phẩm, không thôi nhiễm chì/kim loại nặng, lòng tối chống rêu',1794030803),
(608,51,8,'deferredfeedback',44,1,1.0000000,0.0000000,1.0000000,0,'Để giảm thiểu hàm lượng Nitrat tự do trong rau thủy canh trước khi thu hoạch 3–5 ngày, kỹ thuật nào được áp dụng?\n: Hạ nhẹ nồng độ EC dung dịch (0.8–1.0 mS/cm) và đảm bảo cây nhận đủ ánh sáng chuyển hóa đạm; Tăng gấp 3 lần đạm Urê vào bồn trước giờ cắt 1 tiếng; Che tối đen toàn bộ giàn rau 5 ngày; Ngâm ngập lá rau vào dung dịch Bồn A','Hạ nhẹ nồng độ EC dung dịch (0.8–1.0 mS/cm) và đảm bảo cây nhận đủ ánh sáng chuyển hóa đạm','Hạ nhẹ nồng độ EC dung dịch (0.8–1.0 mS/cm) và đảm bảo cây nhận đủ ánh sáng chuyển hóa đạm',1794030803),
(609,51,9,'deferredfeedback',45,1,1.0000000,0.0000000,1.0000000,0,'Hiện tượng rêu tảo xanh phát triển dày đặc trong bồn chứa và rãnh máng thủy canh gây tác hại gì?\n: Cạnh tranh oxy hòa tan, làm biến động pH, bít nghẹt bơm lọc và sinh độc tố hại rễ non; Giúp cây lớn nhanh gấp 3 lần; Thay thế hoàn toàn phân bón A-B; Tự động làm lạnh dung dịch','Cạnh tranh oxy hòa tan, làm biến động pH, bít nghẹt bơm lọc và sinh độc tố hại rễ non','Cạnh tranh oxy hòa tan, làm biến động pH, bít nghẹt bơm lọc và sinh độc tố hại rễ non',1794030803),
(610,51,10,'deferredfeedback',46,1,1.0000000,0.0000000,1.0000000,0,'Lưu lượng cấp dung dịch dinh dưỡng tiêu chuẩn ở đầu mỗi máng thủy canh NFT là khoảng bao nhiêu?\n: 1.5 – 2.0 Lít/phút; 0.01 Lít/ngày; 500 Lít/phút xối bật gốc cây; Chỉ cấp 1 lần duy nhất mỗi tháng','1.5 – 2.0 Lít/phút','1.5 – 2.0 Lít/phút',1794030803),
(611,51,11,'deferredfeedback',47,1,1.0000000,0.0000000,1.0000000,0,'Biện pháp thiết kế nào giúp giữ dung dịch thủy canh luôn mát mẻ ổn định ở 22–25°C trong điều kiện khí hậu Việt Nam?\n: Hạ ngầm bồn chứa dinh dưỡng dưới mặt đất có nắp đậy kín cách nhiệt và mái máng trắng phản xạ nhiệt; Đặt bồn nhựa màu đen ngoài trời nắng trưa không mái che; Đun nóng bồn dinh dưỡng bằng điện trở; Dùng máng kim loại hấp nhiệt','Hạ ngầm bồn chứa dinh dưỡng dưới mặt đất có nắp đậy kín cách nhiệt và mái máng trắng phản xạ nhiệt','Đặt bồn nhựa màu đen ngoài trời nắng trưa không mái che',1794030803),
(612,51,12,'deferredfeedback',48,1,1.0000000,0.0000000,1.0000000,0,'Khi cây con xà lách mới gieo bị vươn cổ thân dài mảnh yếu ớt (leggy), nguyên nhân kỹ thuật là do đâu?\n: Thiếu ánh sáng ngay sau khi hạt nứt nanh nảy mầm hoặc nhiệt độ ươm quá cao; Đủ nắng sáng sớm thông thoáng; Độ pH nước tưới chuẩn 6.0; Mút xốp sạch vô trùng','Thiếu ánh sáng ngay sau khi hạt nứt nanh nảy mầm hoặc nhiệt độ ươm quá cao','Đủ nắng sáng sớm thông thoáng',1794030803),
(613,52,1,'deferredfeedback',1,1,1.0000000,0.0000000,1.0000000,0,'Khoảng pH dung dịch dinh dưỡng tối ưu giúp rễ cây trồng giá thể/nhà màng hấp thu cân đối đa-trung-vi lượng là bao nhiêu?\n: 5.8 – 6.2; 3.5 – 4.2; 7.5 – 8.5; 8.5 – 9.2','5.8 – 6.2','5.8 – 6.2',1794030804),
(614,52,2,'deferredfeedback',2,1,1.0000000,0.0000000,1.0000000,0,'Vì sao tuyệt đối KHÔNG pha chung đậm đặc phân Canxi Nitrat (Bồn A) với phân chứa gốc Sunfat/Photphat (Bồn B)?\n: Gây kết tủa CaSO4 / Ca3(PO4)2 làm mất dinh dưỡng và tắc béc nhỏ giọt; Làm dung dịch bay hơi hết nước; Làm giảm nhiệt độ nhà màng xuống 0°C; Không có ảnh hưởng gì','Gây kết tủa CaSO4 / Ca3(PO4)2 làm mất dinh dưỡng và tắc béc nhỏ giọt','Gây kết tủa CaSO4 / Ca3(PO4)2 làm mất dinh dưỡng và tắc béc nhỏ giọt',1794030804),
(615,52,3,'deferredfeedback',3,1,1.0000000,0.0000000,1.0000000,0,'Khi trời nắng gắt nhiệt độ >33°C, người trồng cần điều chỉnh chế độ tưới Fertigation như thế nào là đúng kỹ thuật?\n: Chia nhiều lần tưới ngắn hơn và giảm nhẹ EC 0.2–0.3 mS/cm để tránh sốc mặn vùng rễ; Tăng gấp đôi EC lên 5.0 mS/cm; Ngừng tưới hoàn toàn từ sáng đến tối; Chỉ tưới 1 lần duy nhất lúc 21h đêm','Chia nhiều lần tưới ngắn hơn và giảm nhẹ EC 0.2–0.3 mS/cm để tránh sốc mặn vùng rễ','Chia nhiều lần tưới ngắn hơn và giảm nhẹ EC 0.2–0.3 mS/cm để tránh sốc mặn vùng rễ',1794030804),
(616,52,4,'deferredfeedback',4,1,1.0000000,0.0000000,1.0000000,0,'Tỷ lệ nước rỉ thoát đáy bầu giá thể (Drainage %) tiêu chuẩn trong canh tác nhà màng nhằm ngăn tích tụ muối là bao nhiêu?\n: 15% – 25%; 0% (không cho chảy giọt nào); 80% – 95%; 100%','15% – 25%','15% – 25%',1794030804),
(617,52,5,'deferredfeedback',5,1,1.0000000,0.0000000,1.0000000,0,'Triệu chứng cháy khô mép lá non xà lách (Tipburn) và thối đít trái cà chua/dưa lưới liên quan trực tiếp đến thiếu hụt nguyên tố nào?\n: Canxi (Ca); Đạm (N); Clo (Cl); Natri (Na)','Canxi (Ca)','Canxi (Ca)',1794030804),
(618,52,6,'deferredfeedback',6,1,1.0000000,0.0000000,1.0000000,0,'Bộ lọc đĩa trong hệ thống tưới nhỏ giọt công nghệ cao cần cấp độ mịn tối thiểu bao nhiêu để bảo vệ đầu nhỏ giọt bù áp?\n: 120 – 150 mesh; 10 mesh; 20 mesh; Không cần lắp bộ lọc','120 – 150 mesh','120 – 150 mesh',1794030804),
(619,52,7,'deferredfeedback',7,1,1.0000000,0.0000000,1.0000000,0,'Biện pháp giám sát và phòng trừ sinh học hiệu quả nhất đối với Bọ trĩ (Thrips) hại đọt non trong nhà màng là gì?\n: Treo bẫy dính xanh dương/vàng kết hợp phun nấm ký sinh Beauveria/Metarhizium và dầu Neem; Phun thuốc diệt cỏ liều cao; Đóng kín toàn bộ quạt thông gió tăng nhiệt lên 48°C; Tưới nước mặn vào ngọn cây','Treo bẫy dính xanh dương/vàng kết hợp phun nấm ký sinh Beauveria/Metarhizium và dầu Neem','Treo bẫy dính xanh dương/vàng kết hợp phun nấm ký sinh Beauveria/Metarhizium và dầu Neem',1794030804),
(620,52,8,'deferredfeedback',8,1,1.0000000,0.0000000,1.0000000,0,'Để xử lý lớp sáp trắng bảo vệ trên cơ thể Rệp sáp theo hướng an toàn VietGAP, nên phối hợp vật tư sinh học nào?\n: Dầu khoáng sinh học 0.3% kết hợp nấm trắng Beauveria bassiana và chặn kiến cộng sinh; Bón thật nhiều phân Urê vào lá; Tưới nước đá lạnh buổi trưa; Chỉ phun nước lã không cần vệ sinh cành','Dầu khoáng sinh học 0.3% kết hợp nấm trắng Beauveria bassiana và chặn kiến cộng sinh','Dầu khoáng sinh học 0.3% kết hợp nấm trắng Beauveria bassiana và chặn kiến cộng sinh',1794030804),
(621,52,9,'deferredfeedback',9,1,1.0000000,0.0000000,1.0000000,0,'Nấm đối kháng Trichoderma spp. phát huy hiệu quả tốt nhất khi xử lý bệnh nào vùng rễ?\n: Phòng trừ nấm đất Phytophthora, Fusarium, Pythium gây lở cổ rễ và thối rễ; Trị sâu đục quả trưởng thành bay trên ngọn; Thay thế hoàn toàn phân Kali; Làm chín ép trái cây trong 2 giờ','Phòng trừ nấm đất Phytophthora, Fusarium, Pythium gây lở cổ rễ và thối rễ','Phòng trừ nấm đất Phytophthora, Fusarium, Pythium gây lở cổ rễ và thối rễ',1794030804),
(622,52,10,'deferredfeedback',10,1,1.0000000,0.0000000,1.0000000,0,'Vì sao nên kết thúc chu kỳ tưới nhỏ giọt cuối cùng trong ngày trước 15:30–16:00 chiều đối với dưa lưới/cà chua?\n: Để giá thể thông thoáng đủ oxy cho rễ ban đêm, hạn chế ẩm độ cao gây nấm và nứt trái; Vì máy bơm không hoạt động buổi chiều; Để tăng EC vùng rễ lên 10 mS/cm; Để lá cây héo rũ qua đêm','Để giá thể thông thoáng đủ oxy cho rễ ban đêm, hạn chế ẩm độ cao gây nấm và nứt trái','Vì máy bơm không hoạt động buổi chiều',1794030804),
(623,52,11,'deferredfeedback',11,1,1.0000000,0.0000000,1.0000000,0,'Theo quy định VietGAP, chỉ số PHI (Pre-Harvest Interval) trên nhật ký canh tác có ý nghĩa là gì?\n: Thời gian cách ly an toàn từ lần phun cuối cùng đến khi được phép thu hoạch; Tổng diện tích nhà màng tính bằng ha; Áp suất đường ống chính tính bằng bar; Số lượng béc tưới trên một hàng','Thời gian cách ly an toàn từ lần phun cuối cùng đến khi được phép thu hoạch','Tổng diện tích nhà màng tính bằng ha',1794030804),
(624,52,12,'deferredfeedback',12,1,1.0000000,0.0000000,1.0000000,0,'Tiêu chuẩn cây giống khỏe trước khi đem trồng ra nhà màng công nghệ cao gồm đặc điểm nào sau đây?\n: Thân mập thẳng, bầu rễ trắng phát triển mạnh, sạch sâu bệnh và đã huấn luyện thích nghi ánh sáng; Rễ thâm nâu có mùi chua và lá non xoăn vàng; Cây vươn lóng dài yếu ớt do thiếu sáng; Giá thể nhiễm mặn EC > 4.0 mS/cm','Thân mập thẳng, bầu rễ trắng phát triển mạnh, sạch sâu bệnh và đã huấn luyện thích nghi ánh sáng','Rễ thâm nâu có mùi chua và lá non xoăn vàng',1794030804),
(625,53,1,'deferredfeedback',13,1,1.0000000,0.0000000,1.0000000,0,'Mục đích cốt lõi của công đoạn làm mát sơ bộ (Pre-cooling) trong vòng 2 giờ đầu sau thu hoạch là gì?\n: Nhanh chóng rút nhiệt đồng ruộng, giảm cường độ hô hấp và sự mất nước của nông sản; Làm chín nhanh toàn bộ lô hàng trong 1 giờ; Tăng hàm lượng nước tự do đọng trên mặt lá; Làm đông cứng rau ăn lá ở -20°C','Nhanh chóng rút nhiệt đồng ruộng, giảm cường độ hô hấp và sự mất nước của nông sản','Nhanh chóng rút nhiệt đồng ruộng, giảm cường độ hô hấp và sự mất nước của nông sản',1794030804),
(626,53,2,'deferredfeedback',14,1,1.0000000,0.0000000,1.0000000,0,'Phương pháp làm mát sơ bộ nào giúp hạ nhiệt rau ăn lá (xà lách, cải bó xôi) từ 28°C xuống 3°C nhanh nhất (chỉ 20–30 phút)?\n: Làm mát chân không (Vacuum Cooling); Phơi ngoài sân nắng; Ủ kín trong bao tải dứa; Đặt cạnh lò sấy nhiệt','Làm mát chân không (Vacuum Cooling)','Làm mát chân không (Vacuum Cooling)',1794030804),
(627,53,3,'deferredfeedback',15,1,1.0000000,0.0000000,1.0000000,0,'Nhiệt độ và ẩm độ kho mát tiêu chuẩn để bảo quản tươi nhóm rau ăn lá ôn đới (xà lách, cải thảo, bông cải) là bao nhiêu?\n: 2°C – 5°C và ẩm độ 90% – 95%; 22°C – 28°C và ẩm độ 40%; -18°C đóng băng hoàn toàn; 35°C và ẩm độ 99%','2°C – 5°C và ẩm độ 90% – 95%','2°C – 5°C và ẩm độ 90% – 95%',1794030804),
(628,53,4,'deferredfeedback',16,1,1.0000000,0.0000000,1.0000000,0,'Vì sao không được bảo quản trái cây nhiệt đới tươi nguyên quả (xoài, chuối, sầu riêng tươi) ở nhiệt độ quá thấp 0–4°C?\n: Gây hiện tượng tổn thương lạnh (Chilling Injury) làm thâm đen vỏ và sượng thịt quả; Làm trái nổ vỡ ngay lập tức; Làm tăng trọng lượng trái lên 200%; Vì kho lạnh không thể chỉnh dưới 15°C','Gây hiện tượng tổn thương lạnh (Chilling Injury) làm thâm đen vỏ và sượng thịt quả','Gây hiện tượng tổn thương lạnh (Chilling Injury) làm thâm đen vỏ và sượng thịt quả',1794030804),
(629,53,5,'deferredfeedback',17,1,1.0000000,0.0000000,1.0000000,0,'Nguyên lý chính của bao bì khí quyển biến đổi MAP (Modified Atmosphere Packaging) trong bảo quản rau quả tươi là gì?\n: Giảm nồng độ O2 (3–5%) và nâng nhẹ CO2 (5–8%) để làm chậm hô hấp và ức chế vi sinh gây hư hỏng; Bơm 100% khí Ethylene vào túi để thúc chín; Hút kiệt tạo áp suất nén nát lá rau; Bơm không khí nóng 60°C vào bao bì','Giảm nồng độ O2 (3–5%) và nâng nhẹ CO2 (5–8%) để làm chậm hô hấp và ức chế vi sinh gây hư hỏng','Giảm nồng độ O2 (3–5%) và nâng nhẹ CO2 (5–8%) để làm chậm hô hấp và ức chế vi sinh gây hư hỏng',1794030804),
(630,53,6,'deferredfeedback',18,1,1.0000000,0.0000000,1.0000000,0,'Công nghệ sấy lạnh bơm nhiệt (Heat-Pump Drying) vận hành ở dải nhiệt độ nào để bảo toàn màu sắc và Vitamin?\n: 25°C – 42°C với không khí tách ẩm khô tuần hoàn kín; 120°C – 180°C bằng than đá; 95°C – 110°C ngoài trời; -40°C không tách ẩm','25°C – 42°C với không khí tách ẩm khô tuần hoàn kín','25°C – 42°C với không khí tách ẩm khô tuần hoàn kín',1794030804),
(631,53,7,'deferredfeedback',19,1,1.0000000,0.0000000,1.0000000,0,'Tại sao không nên xếp chung kho lạnh giữa các trái sinh nhiều khí Ethylene (chuối chín, sầu riêng) với rau ăn lá hoặc dưa leo?\n: Khí Ethylene kích thích vàng lá, rụng cuống và làm già hóa hư hỏng nhanh rau ăn lá; Làm kho lạnh tiêu tốn ít điện hơn; Làm dưa leo ngọt thành dưa lưới; Không có bất kỳ tác động sinh lý nào','Khí Ethylene kích thích vàng lá, rụng cuống và làm già hóa hư hỏng nhanh rau ăn lá','Khí Ethylene kích thích vàng lá, rụng cuống và làm già hóa hư hỏng nhanh rau ăn lá',1794030804),
(632,53,8,'deferredfeedback',20,1,1.0000000,0.0000000,1.0000000,0,'Công nghệ cấp đông siêu tốc IQF (-35°C đến -40°C) giúp múi sầu riêng xuất khẩu đạt chất lượng vượt trội nhờ cơ chế nào?\n: Hình thành vi tinh thể băng cực nhỏ không phá vỡ màng tế bào, không chảy dịch khi rã đông; Rút hết toàn bộ hương thơm của sầu riêng; Biến tinh bột thành chất xơ gỗ; Không cần bảo quản lạnh sau cấp đông','Hình thành vi tinh thể băng cực nhỏ không phá vỡ màng tế bào, không chảy dịch khi rã đông','Hình thành vi tinh thể băng cực nhỏ không phá vỡ màng tế bào, không chảy dịch khi rã đông',1794030804),
(633,53,9,'deferredfeedback',21,1,1.0000000,0.0000000,1.0000000,0,'Nguyên tắc thiết kế mặt bằng nhà xưởng sơ chế nông sản đạt chuẩn HACCP / ISO 22000 là gì?\n: Nguyên tắc dòng chảy 1 chiều từ khu nguyên liệu sang khu sạch đóng gói, không nhiễm chéo; Nhập nguyên liệu và xuất thành phẩm chung một bàn sơ chế đất; Đặt kho thuốc BVTV ngay trong phòng đóng gói; Không cần khử trùng dao kéo thu hoạch','Nguyên tắc dòng chảy 1 chiều từ khu nguyên liệu sang khu sạch đóng gói, không nhiễm chéo','Nguyên tắc dòng chảy 1 chiều từ khu nguyên liệu sang khu sạch đóng gói, không nhiễm chéo',1794030804),
(634,53,10,'deferredfeedback',22,1,1.0000000,0.0000000,1.0000000,0,'Trước khi đóng gói rau ăn lá vào túi màng MAP, yêu cầu bắt buộc đối với bề mặt lá sau khi rửa là gì?\n: Phải làm ráo hoàn toàn nước tự do đọng trên lá (ly tâm/quạt lạnh) để ngừa thối nhũn vi khuẩn; Để nguyên nước ướt sũng trong túi kín; Phun nước đường lên mặt lá; Phơi nắng trưa 35°C trong 2 giờ','Phải làm ráo hoàn toàn nước tự do đọng trên lá (ly tâm/quạt lạnh) để ngừa thối nhũn vi khuẩn','Phải làm ráo hoàn toàn nước tự do đọng trên lá (ly tâm/quạt lạnh) để ngừa thối nhũn vi khuẩn',1794030804),
(635,53,11,'deferredfeedback',23,1,1.0000000,0.0000000,1.0000000,0,'Thiết bị nào bắt buộc gắn trong container lạnh xuất khẩu đường biển để minh chứng chuỗi lạnh không bị đứt gãy?\n: Thiết bị ghi hành trình nhiệt độ - ẩm độ tự động (DataLogger); Bình tưới cây cầm tay; Bẫy dính côn trùng màu vàng; Bút thử độ mặn đất','Thiết bị ghi hành trình nhiệt độ - ẩm độ tự động (DataLogger)','Thiết bị ghi hành trình nhiệt độ - ẩm độ tự động (DataLogger)',1794030804),
(636,53,12,'deferredfeedback',24,1,1.0000000,0.0000000,1.0000000,0,'Thông tin nào cần hiển thị công khai khi người tiêu dùng quét mã QR truy xuất nguồn gốc trên bao bì nông sản VietGAP?\n: Mã lô sản xuất, tên nông hộ & tọa độ vùng trồng, lịch sử nhật ký canh tác, ngày thu hoạch & chuẩn an toàn; Mật khẩu quản trị hệ thống của nông trại; Số tài khoản cá nhân của tài xế; Chỉ hiển thị một bức ảnh tĩnh không có dữ liệu lô','Mã lô sản xuất, tên nông hộ & tọa độ vùng trồng, lịch sử nhật ký canh tác, ngày thu hoạch & chuẩn an toàn','Mật khẩu quản trị hệ thống của nông trại',1794030804),
(637,54,1,'deferredfeedback',61,1,1.0000000,0.0000000,1.0000000,0,'Tỷ lệ Carbon / Nitơ (C/N) lý tưởng nhất của hỗn hợp nguyên liệu ban đầu khi ủ phân hữu cơ vi sinh là bao nhiêu?\n: 25:1 đến 30:1; 500:1 (chỉ toàn mùn cưa khô không có đạm); 2:1 (chỉ toàn đạm đặc); 0:0','25:1 đến 30:1','25:1 đến 30:1',1794030805),
(638,54,2,'deferredfeedback',62,1,1.0000000,0.0000000,1.0000000,0,'Độ ẩm nguyên liệu chuẩn khi bắt đầu đánh đống ủ phân hữu cơ hiếu khí (kiểm tra nắm chặt rỉ nước kẽ tay không nhỏ giọt) là bao nhiêu?\n: 55% – 60%; 5% khô rang như cát; 95% ngập sũng như cháo loãng; 0%','55% – 60%','55% – 60%',1794030805),
(639,54,3,'deferredfeedback',63,1,1.0000000,0.0000000,1.0000000,0,'Nhiệt độ ở giai đoạn ưa nhiệt (Thermophilic phase) trong tâm đống ủ đạt 55–65°C kéo dài nhiều ngày có tác dụng quan trọng gì?\n: Tiêu diệt vi khuẩn gây bệnh (E.coli, Salmonella), trứng tuyến trùng, nấm hại và làm mất sức nảy mầm hạt cỏ dại; Làm phân biến thành nhựa tổng hợp; Giữ sống toàn bộ hạt cỏ dại để mọc nhiều hơn; Đóng băng đống phân','Tiêu diệt vi khuẩn gây bệnh (E.coli, Salmonella), trứng tuyến trùng, nấm hại và làm mất sức nảy mầm hạt cỏ dại','Tiêu diệt vi khuẩn gây bệnh (E.coli, Salmonella), trứng tuyến trùng, nấm hại và làm mất sức nảy mầm hạt cỏ dại',1794030805),
(640,54,4,'deferredfeedback',64,1,1.0000000,0.0000000,1.0000000,0,'Vì sao nên cấy bổ sung chủng nấm đối kháng Trichoderma vào giai đoạn đống ủ đã hạ nhiệt nguội (<38°C) thay vì lúc đang nóng 65°C?\n: Tránh nhiệt độ quá cao 65°C tiêu diệt bào tử Trichoderma, giúp nấm nhân sinh khối tối đa trong phân thành phẩm; Vì Trichoderma chỉ sống ở 100°C; Để làm phân bốc mùi khai; Không có lý do kỹ thuật nào','Tránh nhiệt độ quá cao 65°C tiêu diệt bào tử Trichoderma, giúp nấm nhân sinh khối tối đa trong phân thành phẩm','Tránh nhiệt độ quá cao 65°C tiêu diệt bào tử Trichoderma, giúp nấm nhân sinh khối tối đa trong phân thành phẩm',1794030805),
(641,54,5,'deferredfeedback',65,1,1.0000000,0.0000000,1.0000000,0,'Theo tiêu chuẩn VietGAP, vì sao nghiêm cấm bón phân chuồng tươi chưa qua ủ hoai mục trực tiếp cho rau quả?\n: Nguy cơ nhiễm vi sinh vật gây bệnh đường ruột (E.coli, Salmonella), tuyến trùng rễ và sinh nhiệt độc rễ; Vì phân tươi quá đắt tiền; Vì phân tươi có màu quá đẹp; Vì phân tươi làm tăng oxy đất quá mức','Nguy cơ nhiễm vi sinh vật gây bệnh đường ruột (E.coli, Salmonella), tuyến trùng rễ và sinh nhiệt độc rễ','Nguy cơ nhiễm vi sinh vật gây bệnh đường ruột (E.coli, Salmonella), tuyến trùng rễ và sinh nhiệt độc rễ',1794030805),
(642,54,6,'deferredfeedback',66,1,1.0000000,0.0000000,1.0000000,0,'Khi đống ủ phân hữu cơ bốc mùi trứng thối (H2S) và chua gắt, nguyên nhân kỹ thuật là do đâu và xử lý thế nào?\n: Đống ủ quá ướt thiếu oxy (yếm khí); cần đảo trộn tơi xốp và bổ sung chất độn khô giàu Carbon (trấu, mùn dừa); Đống ủ quá giàu oxy; cần đổ ngập nước kín; Nhiệt độ ngoài trời 25°C; Do có nhiều xạ khuẩn thơm','Đống ủ quá ướt thiếu oxy (yếm khí); cần đảo trộn tơi xốp và bổ sung chất độn khô giàu Carbon (trấu, mùn dừa)','Đống ủ quá ướt thiếu oxy (yếm khí); cần đảo trộn tơi xốp và bổ sung chất độn khô giàu Carbon (trấu, mùn dừa)',1794030805),
(643,54,7,'deferredfeedback',67,1,1.0000000,0.0000000,1.0000000,0,'Dấu hiệu cảm quan chính xác chứng tỏ mẻ phân hữu cơ vi sinh đã chín hoai hoàn toàn sẵn sàng đem bón là gì?\n: Màu nâu đen tơi xốp, nhiệt độ hạ bằng môi trường và có mùi thơm dịu của đất rừng (xạ khuẩn); Tâm đống ủ vẫn nóng bỏng 65°C và bốc mùi khai nồng; Nguyên liệu còn nguyên màu xanh tươi; Chảy nước đen hôi thối','Màu nâu đen tơi xốp, nhiệt độ hạ bằng môi trường và có mùi thơm dịu của đất rừng (xạ khuẩn)','Màu nâu đen tơi xốp, nhiệt độ hạ bằng môi trường và có mùi thơm dịu của đất rừng (xạ khuẩn)',1794030805),
(644,54,8,'deferredfeedback',68,1,1.0000000,0.0000000,1.0000000,0,'Nhóm vi sinh vật có ích Bacillus megaterium / Bacillus subtilis bổ sung trong phân hữu cơ vi sinh có khả năng nổi bật nào?\n: Tiết enzyme và axit hữu cơ phân giải Lân khó tan trong đất thành dạng cây dễ hấp thu và đối kháng nấm khuẩn hại; Biến đất cát thành đá tảng; Hút hết oxy làm ngạt rễ cây; Làm chua đất xuống pH 2.0','Tiết enzyme và axit hữu cơ phân giải Lân khó tan trong đất thành dạng cây dễ hấp thu và đối kháng nấm khuẩn hại','Tiết enzyme và axit hữu cơ phân giải Lân khó tan trong đất thành dạng cây dễ hấp thu và đối kháng nấm khuẩn hại',1794030805),
(645,54,9,'deferredfeedback',69,1,1.0000000,0.0000000,1.0000000,0,'Vị trí và cách bón phân hữu cơ vi sinh cho cây ăn quả lâu năm (Sầu riêng, Bưởi) đạt hiệu quả cao nhất là gì?\n: Bón theo hình chiếu rìa tán lá (vùng rễ tơ), lấp đất mỏng hoặc tủ rơm giữ ẩm tránh nắng UV chiếu chết vi sinh; Đổ thành đống dày 50cm ốp sát vào cổ thân gốc cây; Rải phơi khô trắng trên mặt cỏ giữa trưa nắng gắt không tưới; Pha nguyên xác phân thô vào ống nhỏ giọt bù áp','Bón theo hình chiếu rìa tán lá (vùng rễ tơ), lấp đất mỏng hoặc tủ rơm giữ ẩm tránh nắng UV chiếu chết vi sinh','Bón theo hình chiếu rìa tán lá (vùng rễ tơ), lấp đất mỏng hoặc tủ rơm giữ ẩm tránh nắng UV chiếu chết vi sinh',1794030805),
(646,54,10,'deferredfeedback',70,1,1.0000000,0.0000000,1.0000000,0,'Khi thủy phân đạm cá / bánh dầu sinh học làm phân tưới gốc không mùi hôi, nguyên liệu nào cung cấp nguồn đường nuôi khuẩn Lactic & Bacillus?\n: Rỉ mật đường (Molasses) kết hợp chế phẩm men vi sinh EM / Protease; Dầu hỏa công nghiệp; Vôi nung CaO liều cao; Muối hột bão hòa','Rỉ mật đường (Molasses) kết hợp chế phẩm men vi sinh EM / Protease','Rỉ mật đường (Molasses) kết hợp chế phẩm men vi sinh EM / Protease',1794030805),
(647,54,11,'deferredfeedback',71,1,1.0000000,0.0000000,1.0000000,0,'Tác dụng cải tạo vật lý - hóa học quan trọng nhất của mùn hữu cơ đối với đất đỏ bazan Tây Nguyên và đất xám Đông Nam Bộ là gì?\n: Tăng khả năng giữ phân CEC, đệm ổn định pH đất, tạo cấu trúc tơi xốp giàu oxy và nuôi hệ thiên địch đất; Làm đất nén chặt không thấm nước; Làm tăng độc tố Nhôm di động Al3+; Tiêu diệt hết giun đất','Tăng khả năng giữ phân CEC, đệm ổn định pH đất, tạo cấu trúc tơi xốp giàu oxy và nuôi hệ thiên địch đất','Tăng khả năng giữ phân CEC, đệm ổn định pH đất, tạo cấu trúc tơi xốp giàu oxy và nuôi hệ thiên địch đất',1794030805),
(648,54,12,'deferredfeedback',72,1,1.0000000,0.0000000,1.0000000,0,'Mật độ vi sinh vật hữu ích tối thiểu trên nhãn/mẻ phân hữu cơ vi sinh chất lượng cao thường đạt ngưỡng nào?\n: Từ 10^6 đến 10^8 CFU/g trở lên; 0 CFU/g (vô trùng tuyệt đối); 1 tế bào trên 1 tấn phân; Chỉ chứa cát sỏi khoáng','Từ 10^6 đến 10^8 CFU/g trở lên','0 CFU/g (vô trùng tuyệt đối)',1794030805),
(649,55,1,'deferredfeedback',37,1,1.0000000,0.0000000,1.0000000,0,'Độ dốc lắp đặt tiêu chuẩn của máng thủy canh hồi lưu NFT để tạo màng dinh dưỡng chảy đều không đọng vũng là bao nhiêu?\n: 2.0% – 2.5% (tỷ lệ khoảng 1:40); 0% (nằm ngang hoàn toàn đọng đầy nước); 45% (dốc đứng); 80%','2.0% – 2.5% (tỷ lệ khoảng 1:40)','2.0% – 2.5% (tỷ lệ khoảng 1:40)',1794030805),
(650,55,2,'deferredfeedback',38,1,1.0000000,0.0000000,1.0000000,0,'Hàm lượng Oxy hòa tan (DO) tối thiểu cần duy trì trong dung dịch thủy canh để bộ rễ trắng khỏe không bị thối ngạt là bao nhiêu?\n: >= 6.0 mg/L; 0.0 mg/L; 0.5 mg/L; Chỉ cần khí CO2 không cần Oxy','>= 6.0 mg/L','>= 6.0 mg/L',1794030805),
(651,55,3,'deferredfeedback',39,1,1.0000000,0.0000000,1.0000000,0,'Vì sao chiều dài mỗi máng thủy canh NFT thương mại không nên vượt quá 12–15 mét?\n: Tránh chênh lệch nhiệt độ tăng cao và cạn kiệt oxy hòa tan ở các hốc cây cuối máng; Vì ống nhựa không thể nối dài hơn 2m; Để giảm ánh sáng mặt trời; Vì cây đầu máng không hút được nước','Tránh chênh lệch nhiệt độ tăng cao và cạn kiệt oxy hòa tan ở các hốc cây cuối máng','Tránh chênh lệch nhiệt độ tăng cao và cạn kiệt oxy hòa tan ở các hốc cây cuối máng',1794030805),
(652,55,4,'deferredfeedback',40,1,1.0000000,0.0000000,1.0000000,0,'Khi xử lý giá thể mụn xơ dừa trước khi trồng dưa lưới/cà chua, chỉ số EC nước xả cuối cùng cần đạt mức nào?\n: EC < 0.5 mS/cm và đã ngâm đệm loại bỏ Tanin/muối Na+; EC > 5.0 mS/cm; Giữ nguyên toàn bộ muối chát tự nhiên; Trộn thêm muối ăn NaCl vào xơ dừa','EC < 0.5 mS/cm và đã ngâm đệm loại bỏ Tanin/muối Na+','EC < 0.5 mS/cm và đã ngâm đệm loại bỏ Tanin/muối Na+',1794030805),
(653,55,5,'deferredfeedback',41,1,1.0000000,0.0000000,1.0000000,0,'Nguyên nhân hàng đầu làm bùng phát nấm nước Pythium gây thối tuột rễ trên giàn thủy canh vào mùa nắng nóng là gì?\n: Nhiệt độ dung dịch dinh dưỡng tăng cao (>30°C) làm giảm mạnh nồng độ oxy hòa tan DO; Nhiệt độ nước mát 22°C giàu oxy; Độ pH ổn định ở 6.0; Ánh sáng buổi sáng dịu nhẹ','Nhiệt độ dung dịch dinh dưỡng tăng cao (>30°C) làm giảm mạnh nồng độ oxy hòa tan DO','Nhiệt độ dung dịch dinh dưỡng tăng cao (>30°C) làm giảm mạnh nồng độ oxy hòa tan DO',1794030805),
(654,55,6,'deferredfeedback',42,1,1.0000000,0.0000000,1.0000000,0,'Vi lượng nào đóng vai trò thiết yếu cấu tạo enzyme Nitrate Reductase giúp cây rau chuyển hóa Nitrat (NO3-) giảm tồn dư trong lá?\n: Molypden (Mo) kết hợp đủ ánh sáng quang hợp; Chì (Pb); Thủy ngân (Hg); Nhôm (Al)','Molypden (Mo) kết hợp đủ ánh sáng quang hợp','Molypden (Mo) kết hợp đủ ánh sáng quang hợp',1794030805),
(655,55,7,'deferredfeedback',43,1,1.0000000,0.0000000,1.0000000,0,'Máng nhựa dùng trong hệ thống thủy canh rau ăn lá chuẩn VietGAP phải đáp ứng yêu cầu vật liệu nào?\n: Nhựa uPVC chuyên dụng an toàn thực phẩm, không thôi nhiễm chì/kim loại nặng, lòng tối chống rêu; Ống nhựa tái chế phế thải công nghiệp chứa chì; Máng tôn gỉ sét; Máng gỗ mục tẩm dầu nhớt','Nhựa uPVC chuyên dụng an toàn thực phẩm, không thôi nhiễm chì/kim loại nặng, lòng tối chống rêu','Nhựa uPVC chuyên dụng an toàn thực phẩm, không thôi nhiễm chì/kim loại nặng, lòng tối chống rêu',1794030805),
(656,55,8,'deferredfeedback',44,1,1.0000000,0.0000000,1.0000000,0,'Để giảm thiểu hàm lượng Nitrat tự do trong rau thủy canh trước khi thu hoạch 3–5 ngày, kỹ thuật nào được áp dụng?\n: Hạ nhẹ nồng độ EC dung dịch (0.8–1.0 mS/cm) và đảm bảo cây nhận đủ ánh sáng chuyển hóa đạm; Tăng gấp 3 lần đạm Urê vào bồn trước giờ cắt 1 tiếng; Che tối đen toàn bộ giàn rau 5 ngày; Ngâm ngập lá rau vào dung dịch Bồn A','Hạ nhẹ nồng độ EC dung dịch (0.8–1.0 mS/cm) và đảm bảo cây nhận đủ ánh sáng chuyển hóa đạm','Hạ nhẹ nồng độ EC dung dịch (0.8–1.0 mS/cm) và đảm bảo cây nhận đủ ánh sáng chuyển hóa đạm',1794030805),
(657,55,9,'deferredfeedback',45,1,1.0000000,0.0000000,1.0000000,0,'Hiện tượng rêu tảo xanh phát triển dày đặc trong bồn chứa và rãnh máng thủy canh gây tác hại gì?\n: Cạnh tranh oxy hòa tan, làm biến động pH, bít nghẹt bơm lọc và sinh độc tố hại rễ non; Giúp cây lớn nhanh gấp 3 lần; Thay thế hoàn toàn phân bón A-B; Tự động làm lạnh dung dịch','Cạnh tranh oxy hòa tan, làm biến động pH, bít nghẹt bơm lọc và sinh độc tố hại rễ non','Cạnh tranh oxy hòa tan, làm biến động pH, bít nghẹt bơm lọc và sinh độc tố hại rễ non',1794030805),
(658,55,10,'deferredfeedback',46,1,1.0000000,0.0000000,1.0000000,0,'Lưu lượng cấp dung dịch dinh dưỡng tiêu chuẩn ở đầu mỗi máng thủy canh NFT là khoảng bao nhiêu?\n: 1.5 – 2.0 Lít/phút; 0.01 Lít/ngày; 500 Lít/phút xối bật gốc cây; Chỉ cấp 1 lần duy nhất mỗi tháng','1.5 – 2.0 Lít/phút','1.5 – 2.0 Lít/phút',1794030805),
(659,55,11,'deferredfeedback',47,1,1.0000000,0.0000000,1.0000000,0,'Biện pháp thiết kế nào giúp giữ dung dịch thủy canh luôn mát mẻ ổn định ở 22–25°C trong điều kiện khí hậu Việt Nam?\n: Hạ ngầm bồn chứa dinh dưỡng dưới mặt đất có nắp đậy kín cách nhiệt và mái máng trắng phản xạ nhiệt; Đặt bồn nhựa màu đen ngoài trời nắng trưa không mái che; Đun nóng bồn dinh dưỡng bằng điện trở; Dùng máng kim loại hấp nhiệt','Hạ ngầm bồn chứa dinh dưỡng dưới mặt đất có nắp đậy kín cách nhiệt và mái máng trắng phản xạ nhiệt','Hạ ngầm bồn chứa dinh dưỡng dưới mặt đất có nắp đậy kín cách nhiệt và mái máng trắng phản xạ nhiệt',1794030805),
(660,55,12,'deferredfeedback',48,1,1.0000000,0.0000000,1.0000000,0,'Khi cây con xà lách mới gieo bị vươn cổ thân dài mảnh yếu ớt (leggy), nguyên nhân kỹ thuật là do đâu?\n: Thiếu ánh sáng ngay sau khi hạt nứt nanh nảy mầm hoặc nhiệt độ ươm quá cao; Đủ nắng sáng sớm thông thoáng; Độ pH nước tưới chuẩn 6.0; Mút xốp sạch vô trùng','Thiếu ánh sáng ngay sau khi hạt nứt nanh nảy mầm hoặc nhiệt độ ươm quá cao','Đủ nắng sáng sớm thông thoáng',1794030805),
(661,56,1,'deferredfeedback',25,1,1.0000000,0.0000000,1.0000000,0,'Chỉ số VPD (Vapor Pressure Deficit) tối ưu cho giai đoạn sinh trưởng và nuôi trái trong nhà màng nằm trong khoảng nào?\n: 0.8 – 1.2 kPa; 0.0 – 0.1 kPa; 3.5 – 5.0 kPa; 8.0 – 10.0 kPa','0.8 – 1.2 kPa','0.8 – 1.2 kPa',1794030806),
(662,56,2,'deferredfeedback',26,1,1.0000000,0.0000000,1.0000000,0,'Vị trí lắp đặt cảm biến nhiệt độ - ẩm độ trong nhà màng như thế nào là đúng chuẩn kỹ thuật?\n: Đặt trong hộp chắn bức xạ thông gió ở ngang tầm ngọn cây đang phát triển; Phơi trần trực tiếp dưới nắng trưa sát mái nilon; Ngâm ngập dưới đáy bể chứa nước; Đặt bên ngoài nhà văn phòng cách vườn 500m','Đặt trong hộp chắn bức xạ thông gió ở ngang tầm ngọn cây đang phát triển','Đặt trong hộp chắn bức xạ thông gió ở ngang tầm ngọn cây đang phát triển',1794030806),
(663,56,3,'deferredfeedback',27,1,1.0000000,0.0000000,1.0000000,0,'Mục đích thiết kế buồng đệm 2 cửa so le (Double-door airlock) ở lối vào nhà màng là gì?\n: Ngăn côn trùng chích hút (bọ trĩ, bọ phấn) bay theo người lao động xâm nhập vào nhà màng; Để trang trí cho đẹp mắt; Để giữ nhiệt độ nhà màng luôn ở 45°C; Thay thế hoàn toàn hệ thống tưới','Ngăn côn trùng chích hút (bọ trĩ, bọ phấn) bay theo người lao động xâm nhập vào nhà màng','Ngăn côn trùng chích hút (bọ trĩ, bọ phấn) bay theo người lao động xâm nhập vào nhà màng',1794030806),
(664,56,4,'deferredfeedback',28,1,1.0000000,0.0000000,1.0000000,0,'Cấp độ mắt lưới chắn côn trùng tiêu chuẩn dùng cho vách nhà màng trồng dưa lưới/rau công nghệ cao để chặn bọ trĩ là bao nhiêu?\n: 50 mesh; 4 mesh; 10 mesh; Không dùng lưới vách','50 mesh','50 mesh',1794030806),
(665,56,5,'deferredfeedback',29,1,1.0000000,0.0000000,1.0000000,0,'Khi ẩm độ trong nhà màng lên quá cao >92% vào sáng sớm (VPD < 0.3 kPa), nguy cơ lớn nhất đối với cây trồng là gì?\n: Đọng sương trên lá làm bùng phát nấm Sương mai, Gỉ sắt, Mốc xám Botrytis và giảm hút Canxi; Cây hút quá nhiều Canxi; Béc tưới chạy nhanh gấp đôi; Độ đường trái tăng đột biến','Đọng sương trên lá làm bùng phát nấm Sương mai, Gỉ sắt, Mốc xám Botrytis và giảm hút Canxi','Đọng sương trên lá làm bùng phát nấm Sương mai, Gỉ sắt, Mốc xám Botrytis và giảm hút Canxi',1794030806),
(666,56,6,'deferredfeedback',30,1,1.0000000,0.0000000,1.0000000,0,'Hệ thống rèm lưới cắt nắng tự động nên được lập trình đóng lại khi nào?\n: Khi bức xạ nắng trưa vượt ngưỡng cao (>45.000 Lux / nhiệt >33°C) và mở ra khi nắng dịu; Đóng kín suốt 24/24 giờ cả ngày lẫn đêm; Chỉ đóng vào ban đêm lúc 22h; Chỉ đóng khi trời mưa râm mát','Khi bức xạ nắng trưa vượt ngưỡng cao (>45.000 Lux / nhiệt >33°C) và mở ra khi nắng dịu','Khi bức xạ nắng trưa vượt ngưỡng cao (>45.000 Lux / nhiệt >33°C) và mở ra khi nắng dịu',1794030806),
(667,56,7,'deferredfeedback',31,1,1.0000000,0.0000000,1.0000000,0,'Ưu điểm của hệ thống phun sương cao áp (70 bar, hạt <10 micron) so với vòi phun nước hạt lớn thông thường là gì?\n: Hạt sương siêu mịn bay hơi làm mát không khí tức thì mà không làm đọng nước ướt lá gây bệnh; Làm ngập sũng lối đi nhà màng; Tốn nước gấp 10 lần tưới tràn; Không làm giảm nhiệt độ','Hạt sương siêu mịn bay hơi làm mát không khí tức thì mà không làm đọng nước ướt lá gây bệnh','Hạt sương siêu mịn bay hơi làm mát không khí tức thì mà không làm đọng nước ướt lá gây bệnh',1794030806),
(668,56,8,'deferredfeedback',32,1,1.0000000,0.0000000,1.0000000,0,'Trong tủ điện điều khiển nhà màng IoT, vì sao bắt buộc phải thiết kế công tắc chuyển mạch AUTO - OFF - MANUAL?\n: Đảm bảo vẫn vận hành tay được bơm tưới và quạt thông gió an toàn khi mất mạng hoặc bảo trì PLC; Để tăng tiền điện hàng tháng; Để vô hiệu hóa cảm biến vĩnh viễn; Chỉ dùng để bật đèn chiếu sáng văn phòng','Đảm bảo vẫn vận hành tay được bơm tưới và quạt thông gió an toàn khi mất mạng hoặc bảo trì PLC','Đảm bảo vẫn vận hành tay được bơm tưới và quạt thông gió an toàn khi mất mạng hoặc bảo trì PLC',1794030806),
(669,56,9,'deferredfeedback',33,1,1.0000000,0.0000000,1.0000000,0,'Nếu nhà màng đóng kín hoàn toàn không trao đổi khí suốt buổi sáng nắng đẹp, yếu tố nào giảm mạnh làm chậm quang hợp?\n: Nồng độ khí CO2 trong nhà màng sụt giảm dưới ngưỡng tự nhiên (<250 ppm); Khí Nitơ biến mất hoàn toàn; Độ pH nước tăng lên 14; Trọng lực giảm','Nồng độ khí CO2 trong nhà màng sụt giảm dưới ngưỡng tự nhiên (<250 ppm)','Nồng độ khí CO2 trong nhà màng sụt giảm dưới ngưỡng tự nhiên (<250 ppm)',1794030806),
(670,56,10,'deferredfeedback',34,1,1.0000000,0.0000000,1.0000000,0,'Cài đặt khoảng trễ (Hysteresis, ví dụ bật quạt ở 31°C và tắt ở 29.5°C) trong bộ điều khiển tự động nhằm mục đích gì?\n: Chống đóng/ngắt rơ-le liên tục (chattering) giúp bảo vệ tuổi thọ động cơ quạt và khởi động từ; Làm hỏng cảm biến nhanh hơn; Tăng sai số đo nhiệt độ lên 10°C; Tắt toàn bộ cảnh báo điện thoại','Chống đóng/ngắt rơ-le liên tục (chattering) giúp bảo vệ tuổi thọ động cơ quạt và khởi động từ','Chống đóng/ngắt rơ-le liên tục (chattering) giúp bảo vệ tuổi thọ động cơ quạt và khởi động từ',1794030806),
(671,56,11,'deferredfeedback',35,1,1.0000000,0.0000000,1.0000000,0,'Bao lâu cần vệ sinh bụi bẩn bám trên mái màng PE nhà màng để duy trì hiệu suất truyền ánh sáng PAR?\n: Định kỳ mỗi 3–6 tháng (đặc biệt trong mùa khô bụi) để giữ độ truyền sáng >85%; Không bao giờ rửa trong 10 năm; Sơn đen kín toàn bộ mái màng PE; Mỗi giờ rửa 1 lần bằng axit đặc','Định kỳ mỗi 3–6 tháng (đặc biệt trong mùa khô bụi) để giữ độ truyền sáng >85%','Không bao giờ rửa trong 10 năm',1794030806),
(672,56,12,'deferredfeedback',36,1,1.0000000,0.0000000,1.0000000,0,'Khi nhận tin nhắn cảnh báo mất áp suất đường ống chính từ bộ điều khiển IoT lúc đang tưới, cần kiểm tra ngay điều gì?\n: Kiểm tra nguồn nước cấp, rò rỉ vỡ ống chính hoặc nghẹt bầu lọc đĩa đầu nguồn; Xóa ứng dụng cảnh báo trên điện thoại; Bón thêm phân đạm vào gốc; Cắt bỏ toàn bộ lá non','Kiểm tra nguồn nước cấp, rò rỉ vỡ ống chính hoặc nghẹt bầu lọc đĩa đầu nguồn','Xóa ứng dụng cảnh báo trên điện thoại',1794030806),
(673,57,1,'deferredfeedback',13,1,1.0000000,0.0000000,1.0000000,0,'Mục đích cốt lõi của công đoạn làm mát sơ bộ (Pre-cooling) trong vòng 2 giờ đầu sau thu hoạch là gì?\n: Nhanh chóng rút nhiệt đồng ruộng, giảm cường độ hô hấp và sự mất nước của nông sản; Làm chín nhanh toàn bộ lô hàng trong 1 giờ; Tăng hàm lượng nước tự do đọng trên mặt lá; Làm đông cứng rau ăn lá ở -20°C','Nhanh chóng rút nhiệt đồng ruộng, giảm cường độ hô hấp và sự mất nước của nông sản','Nhanh chóng rút nhiệt đồng ruộng, giảm cường độ hô hấp và sự mất nước của nông sản',1794030807),
(674,57,2,'deferredfeedback',14,1,1.0000000,0.0000000,1.0000000,0,'Phương pháp làm mát sơ bộ nào giúp hạ nhiệt rau ăn lá (xà lách, cải bó xôi) từ 28°C xuống 3°C nhanh nhất (chỉ 20–30 phút)?\n: Làm mát chân không (Vacuum Cooling); Phơi ngoài sân nắng; Ủ kín trong bao tải dứa; Đặt cạnh lò sấy nhiệt','Làm mát chân không (Vacuum Cooling)','Làm mát chân không (Vacuum Cooling)',1794030807),
(675,57,3,'deferredfeedback',15,1,1.0000000,0.0000000,1.0000000,0,'Nhiệt độ và ẩm độ kho mát tiêu chuẩn để bảo quản tươi nhóm rau ăn lá ôn đới (xà lách, cải thảo, bông cải) là bao nhiêu?\n: 2°C – 5°C và ẩm độ 90% – 95%; 22°C – 28°C và ẩm độ 40%; -18°C đóng băng hoàn toàn; 35°C và ẩm độ 99%','2°C – 5°C và ẩm độ 90% – 95%','2°C – 5°C và ẩm độ 90% – 95%',1794030807),
(676,57,4,'deferredfeedback',16,1,1.0000000,0.0000000,1.0000000,0,'Vì sao không được bảo quản trái cây nhiệt đới tươi nguyên quả (xoài, chuối, sầu riêng tươi) ở nhiệt độ quá thấp 0–4°C?\n: Gây hiện tượng tổn thương lạnh (Chilling Injury) làm thâm đen vỏ và sượng thịt quả; Làm trái nổ vỡ ngay lập tức; Làm tăng trọng lượng trái lên 200%; Vì kho lạnh không thể chỉnh dưới 15°C','Gây hiện tượng tổn thương lạnh (Chilling Injury) làm thâm đen vỏ và sượng thịt quả','Gây hiện tượng tổn thương lạnh (Chilling Injury) làm thâm đen vỏ và sượng thịt quả',1794030807),
(677,57,5,'deferredfeedback',17,1,1.0000000,0.0000000,1.0000000,0,'Nguyên lý chính của bao bì khí quyển biến đổi MAP (Modified Atmosphere Packaging) trong bảo quản rau quả tươi là gì?\n: Giảm nồng độ O2 (3–5%) và nâng nhẹ CO2 (5–8%) để làm chậm hô hấp và ức chế vi sinh gây hư hỏng; Bơm 100% khí Ethylene vào túi để thúc chín; Hút kiệt tạo áp suất nén nát lá rau; Bơm không khí nóng 60°C vào bao bì','Giảm nồng độ O2 (3–5%) và nâng nhẹ CO2 (5–8%) để làm chậm hô hấp và ức chế vi sinh gây hư hỏng','Giảm nồng độ O2 (3–5%) và nâng nhẹ CO2 (5–8%) để làm chậm hô hấp và ức chế vi sinh gây hư hỏng',1794030807),
(678,57,6,'deferredfeedback',18,1,1.0000000,0.0000000,1.0000000,0,'Công nghệ sấy lạnh bơm nhiệt (Heat-Pump Drying) vận hành ở dải nhiệt độ nào để bảo toàn màu sắc và Vitamin?\n: 25°C – 42°C với không khí tách ẩm khô tuần hoàn kín; 120°C – 180°C bằng than đá; 95°C – 110°C ngoài trời; -40°C không tách ẩm','25°C – 42°C với không khí tách ẩm khô tuần hoàn kín','25°C – 42°C với không khí tách ẩm khô tuần hoàn kín',1794030807),
(679,57,7,'deferredfeedback',19,1,1.0000000,0.0000000,1.0000000,0,'Tại sao không nên xếp chung kho lạnh giữa các trái sinh nhiều khí Ethylene (chuối chín, sầu riêng) với rau ăn lá hoặc dưa leo?\n: Khí Ethylene kích thích vàng lá, rụng cuống và làm già hóa hư hỏng nhanh rau ăn lá; Làm kho lạnh tiêu tốn ít điện hơn; Làm dưa leo ngọt thành dưa lưới; Không có bất kỳ tác động sinh lý nào','Khí Ethylene kích thích vàng lá, rụng cuống và làm già hóa hư hỏng nhanh rau ăn lá','Khí Ethylene kích thích vàng lá, rụng cuống và làm già hóa hư hỏng nhanh rau ăn lá',1794030807),
(680,57,8,'deferredfeedback',20,1,1.0000000,0.0000000,1.0000000,0,'Công nghệ cấp đông siêu tốc IQF (-35°C đến -40°C) giúp múi sầu riêng xuất khẩu đạt chất lượng vượt trội nhờ cơ chế nào?\n: Hình thành vi tinh thể băng cực nhỏ không phá vỡ màng tế bào, không chảy dịch khi rã đông; Rút hết toàn bộ hương thơm của sầu riêng; Biến tinh bột thành chất xơ gỗ; Không cần bảo quản lạnh sau cấp đông','Hình thành vi tinh thể băng cực nhỏ không phá vỡ màng tế bào, không chảy dịch khi rã đông','Hình thành vi tinh thể băng cực nhỏ không phá vỡ màng tế bào, không chảy dịch khi rã đông',1794030807),
(681,57,9,'deferredfeedback',21,1,1.0000000,0.0000000,1.0000000,0,'Nguyên tắc thiết kế mặt bằng nhà xưởng sơ chế nông sản đạt chuẩn HACCP / ISO 22000 là gì?\n: Nguyên tắc dòng chảy 1 chiều từ khu nguyên liệu sang khu sạch đóng gói, không nhiễm chéo; Nhập nguyên liệu và xuất thành phẩm chung một bàn sơ chế đất; Đặt kho thuốc BVTV ngay trong phòng đóng gói; Không cần khử trùng dao kéo thu hoạch','Nguyên tắc dòng chảy 1 chiều từ khu nguyên liệu sang khu sạch đóng gói, không nhiễm chéo','Nguyên tắc dòng chảy 1 chiều từ khu nguyên liệu sang khu sạch đóng gói, không nhiễm chéo',1794030807),
(682,57,10,'deferredfeedback',22,1,1.0000000,0.0000000,1.0000000,0,'Trước khi đóng gói rau ăn lá vào túi màng MAP, yêu cầu bắt buộc đối với bề mặt lá sau khi rửa là gì?\n: Phải làm ráo hoàn toàn nước tự do đọng trên lá (ly tâm/quạt lạnh) để ngừa thối nhũn vi khuẩn; Để nguyên nước ướt sũng trong túi kín; Phun nước đường lên mặt lá; Phơi nắng trưa 35°C trong 2 giờ','Phải làm ráo hoàn toàn nước tự do đọng trên lá (ly tâm/quạt lạnh) để ngừa thối nhũn vi khuẩn','Phải làm ráo hoàn toàn nước tự do đọng trên lá (ly tâm/quạt lạnh) để ngừa thối nhũn vi khuẩn',1794030807),
(683,57,11,'deferredfeedback',23,1,1.0000000,0.0000000,1.0000000,0,'Thiết bị nào bắt buộc gắn trong container lạnh xuất khẩu đường biển để minh chứng chuỗi lạnh không bị đứt gãy?\n: Thiết bị ghi hành trình nhiệt độ - ẩm độ tự động (DataLogger); Bình tưới cây cầm tay; Bẫy dính côn trùng màu vàng; Bút thử độ mặn đất','Thiết bị ghi hành trình nhiệt độ - ẩm độ tự động (DataLogger)','Thiết bị ghi hành trình nhiệt độ - ẩm độ tự động (DataLogger)',1794030807),
(684,57,12,'deferredfeedback',24,1,1.0000000,0.0000000,1.0000000,0,'Thông tin nào cần hiển thị công khai khi người tiêu dùng quét mã QR truy xuất nguồn gốc trên bao bì nông sản VietGAP?\n: Mã lô sản xuất, tên nông hộ & tọa độ vùng trồng, lịch sử nhật ký canh tác, ngày thu hoạch & chuẩn an toàn; Mật khẩu quản trị hệ thống của nông trại; Số tài khoản cá nhân của tài xế; Chỉ hiển thị một bức ảnh tĩnh không có dữ liệu lô','Mã lô sản xuất, tên nông hộ & tọa độ vùng trồng, lịch sử nhật ký canh tác, ngày thu hoạch & chuẩn an toàn','Mã lô sản xuất, tên nông hộ & tọa độ vùng trồng, lịch sử nhật ký canh tác, ngày thu hoạch & chuẩn an toàn',1794030807),
(685,58,1,'deferredfeedback',61,1,1.0000000,0.0000000,1.0000000,0,'Tỷ lệ Carbon / Nitơ (C/N) lý tưởng nhất của hỗn hợp nguyên liệu ban đầu khi ủ phân hữu cơ vi sinh là bao nhiêu?\n: 25:1 đến 30:1; 500:1 (chỉ toàn mùn cưa khô không có đạm); 2:1 (chỉ toàn đạm đặc); 0:0','25:1 đến 30:1','25:1 đến 30:1',1794030807),
(686,58,2,'deferredfeedback',62,1,1.0000000,0.0000000,1.0000000,0,'Độ ẩm nguyên liệu chuẩn khi bắt đầu đánh đống ủ phân hữu cơ hiếu khí (kiểm tra nắm chặt rỉ nước kẽ tay không nhỏ giọt) là bao nhiêu?\n: 55% – 60%; 5% khô rang như cát; 95% ngập sũng như cháo loãng; 0%','55% – 60%','55% – 60%',1794030807),
(687,58,3,'deferredfeedback',63,1,1.0000000,0.0000000,1.0000000,0,'Nhiệt độ ở giai đoạn ưa nhiệt (Thermophilic phase) trong tâm đống ủ đạt 55–65°C kéo dài nhiều ngày có tác dụng quan trọng gì?\n: Tiêu diệt vi khuẩn gây bệnh (E.coli, Salmonella), trứng tuyến trùng, nấm hại và làm mất sức nảy mầm hạt cỏ dại; Làm phân biến thành nhựa tổng hợp; Giữ sống toàn bộ hạt cỏ dại để mọc nhiều hơn; Đóng băng đống phân','Tiêu diệt vi khuẩn gây bệnh (E.coli, Salmonella), trứng tuyến trùng, nấm hại và làm mất sức nảy mầm hạt cỏ dại','Tiêu diệt vi khuẩn gây bệnh (E.coli, Salmonella), trứng tuyến trùng, nấm hại và làm mất sức nảy mầm hạt cỏ dại',1794030807),
(688,58,4,'deferredfeedback',64,1,1.0000000,0.0000000,1.0000000,0,'Vì sao nên cấy bổ sung chủng nấm đối kháng Trichoderma vào giai đoạn đống ủ đã hạ nhiệt nguội (<38°C) thay vì lúc đang nóng 65°C?\n: Tránh nhiệt độ quá cao 65°C tiêu diệt bào tử Trichoderma, giúp nấm nhân sinh khối tối đa trong phân thành phẩm; Vì Trichoderma chỉ sống ở 100°C; Để làm phân bốc mùi khai; Không có lý do kỹ thuật nào','Tránh nhiệt độ quá cao 65°C tiêu diệt bào tử Trichoderma, giúp nấm nhân sinh khối tối đa trong phân thành phẩm','Tránh nhiệt độ quá cao 65°C tiêu diệt bào tử Trichoderma, giúp nấm nhân sinh khối tối đa trong phân thành phẩm',1794030807),
(689,58,5,'deferredfeedback',65,1,1.0000000,0.0000000,1.0000000,0,'Theo tiêu chuẩn VietGAP, vì sao nghiêm cấm bón phân chuồng tươi chưa qua ủ hoai mục trực tiếp cho rau quả?\n: Nguy cơ nhiễm vi sinh vật gây bệnh đường ruột (E.coli, Salmonella), tuyến trùng rễ và sinh nhiệt độc rễ; Vì phân tươi quá đắt tiền; Vì phân tươi có màu quá đẹp; Vì phân tươi làm tăng oxy đất quá mức','Nguy cơ nhiễm vi sinh vật gây bệnh đường ruột (E.coli, Salmonella), tuyến trùng rễ và sinh nhiệt độc rễ','Nguy cơ nhiễm vi sinh vật gây bệnh đường ruột (E.coli, Salmonella), tuyến trùng rễ và sinh nhiệt độc rễ',1794030807),
(690,58,6,'deferredfeedback',66,1,1.0000000,0.0000000,1.0000000,0,'Khi đống ủ phân hữu cơ bốc mùi trứng thối (H2S) và chua gắt, nguyên nhân kỹ thuật là do đâu và xử lý thế nào?\n: Đống ủ quá ướt thiếu oxy (yếm khí); cần đảo trộn tơi xốp và bổ sung chất độn khô giàu Carbon (trấu, mùn dừa); Đống ủ quá giàu oxy; cần đổ ngập nước kín; Nhiệt độ ngoài trời 25°C; Do có nhiều xạ khuẩn thơm','Đống ủ quá ướt thiếu oxy (yếm khí); cần đảo trộn tơi xốp và bổ sung chất độn khô giàu Carbon (trấu, mùn dừa)','Đống ủ quá ướt thiếu oxy (yếm khí); cần đảo trộn tơi xốp và bổ sung chất độn khô giàu Carbon (trấu, mùn dừa)',1794030807),
(691,58,7,'deferredfeedback',67,1,1.0000000,0.0000000,1.0000000,0,'Dấu hiệu cảm quan chính xác chứng tỏ mẻ phân hữu cơ vi sinh đã chín hoai hoàn toàn sẵn sàng đem bón là gì?\n: Màu nâu đen tơi xốp, nhiệt độ hạ bằng môi trường và có mùi thơm dịu của đất rừng (xạ khuẩn); Tâm đống ủ vẫn nóng bỏng 65°C và bốc mùi khai nồng; Nguyên liệu còn nguyên màu xanh tươi; Chảy nước đen hôi thối','Màu nâu đen tơi xốp, nhiệt độ hạ bằng môi trường và có mùi thơm dịu của đất rừng (xạ khuẩn)','Màu nâu đen tơi xốp, nhiệt độ hạ bằng môi trường và có mùi thơm dịu của đất rừng (xạ khuẩn)',1794030807),
(692,58,8,'deferredfeedback',68,1,1.0000000,0.0000000,1.0000000,0,'Nhóm vi sinh vật có ích Bacillus megaterium / Bacillus subtilis bổ sung trong phân hữu cơ vi sinh có khả năng nổi bật nào?\n: Tiết enzyme và axit hữu cơ phân giải Lân khó tan trong đất thành dạng cây dễ hấp thu và đối kháng nấm khuẩn hại; Biến đất cát thành đá tảng; Hút hết oxy làm ngạt rễ cây; Làm chua đất xuống pH 2.0','Tiết enzyme và axit hữu cơ phân giải Lân khó tan trong đất thành dạng cây dễ hấp thu và đối kháng nấm khuẩn hại','Tiết enzyme và axit hữu cơ phân giải Lân khó tan trong đất thành dạng cây dễ hấp thu và đối kháng nấm khuẩn hại',1794030807),
(693,58,9,'deferredfeedback',69,1,1.0000000,0.0000000,1.0000000,0,'Vị trí và cách bón phân hữu cơ vi sinh cho cây ăn quả lâu năm (Sầu riêng, Bưởi) đạt hiệu quả cao nhất là gì?\n: Bón theo hình chiếu rìa tán lá (vùng rễ tơ), lấp đất mỏng hoặc tủ rơm giữ ẩm tránh nắng UV chiếu chết vi sinh; Đổ thành đống dày 50cm ốp sát vào cổ thân gốc cây; Rải phơi khô trắng trên mặt cỏ giữa trưa nắng gắt không tưới; Pha nguyên xác phân thô vào ống nhỏ giọt bù áp','Bón theo hình chiếu rìa tán lá (vùng rễ tơ), lấp đất mỏng hoặc tủ rơm giữ ẩm tránh nắng UV chiếu chết vi sinh','Bón theo hình chiếu rìa tán lá (vùng rễ tơ), lấp đất mỏng hoặc tủ rơm giữ ẩm tránh nắng UV chiếu chết vi sinh',1794030807),
(694,58,10,'deferredfeedback',70,1,1.0000000,0.0000000,1.0000000,0,'Khi thủy phân đạm cá / bánh dầu sinh học làm phân tưới gốc không mùi hôi, nguyên liệu nào cung cấp nguồn đường nuôi khuẩn Lactic & Bacillus?\n: Rỉ mật đường (Molasses) kết hợp chế phẩm men vi sinh EM / Protease; Dầu hỏa công nghiệp; Vôi nung CaO liều cao; Muối hột bão hòa','Rỉ mật đường (Molasses) kết hợp chế phẩm men vi sinh EM / Protease','Rỉ mật đường (Molasses) kết hợp chế phẩm men vi sinh EM / Protease',1794030807),
(695,58,11,'deferredfeedback',71,1,1.0000000,0.0000000,1.0000000,0,'Tác dụng cải tạo vật lý - hóa học quan trọng nhất của mùn hữu cơ đối với đất đỏ bazan Tây Nguyên và đất xám Đông Nam Bộ là gì?\n: Tăng khả năng giữ phân CEC, đệm ổn định pH đất, tạo cấu trúc tơi xốp giàu oxy và nuôi hệ thiên địch đất; Làm đất nén chặt không thấm nước; Làm tăng độc tố Nhôm di động Al3+; Tiêu diệt hết giun đất','Tăng khả năng giữ phân CEC, đệm ổn định pH đất, tạo cấu trúc tơi xốp giàu oxy và nuôi hệ thiên địch đất','Làm đất nén chặt không thấm nước',1794030807),
(696,58,12,'deferredfeedback',72,1,1.0000000,0.0000000,1.0000000,0,'Mật độ vi sinh vật hữu ích tối thiểu trên nhãn/mẻ phân hữu cơ vi sinh chất lượng cao thường đạt ngưỡng nào?\n: Từ 10^6 đến 10^8 CFU/g trở lên; 0 CFU/g (vô trùng tuyệt đối); 1 tế bào trên 1 tấn phân; Chỉ chứa cát sỏi khoáng','Từ 10^6 đến 10^8 CFU/g trở lên','0 CFU/g (vô trùng tuyệt đối)',1794030807),
(697,59,1,'deferredfeedback',49,1,1.0000000,0.0000000,1.0000000,0,'Loại phân Kali nào bắt buộc sử dụng ở giai đoạn nuôi cơm sầu riêng để cơm vàng ráo, ngọt béo và tránh hiện tượng sượng nước?\n: Kali Sunfat (K2SO4) không chứa Clo; Kali Clorua (KCl - phân muối ớt chứa nhiều Clo); Muối ăn NaCl; Chỉ bón thuần phân đạm Urê','Kali Sunfat (K2SO4) không chứa Clo','Kali Sunfat (K2SO4) không chứa Clo',1794030808),
(698,59,2,'deferredfeedback',50,1,1.0000000,0.0000000,1.0000000,0,'Hoa sầu riêng nở rộ và tiếp nhận hạt phấn tốt nhất vào khung giờ nào trong ngày để thực hiện thụ phấn bổ sung giúp trái tròn đều 5 hộc?\n: Ban đêm từ 19:30 – 21:30; Giữa trưa nắng 12:00 – 13:00; Sáng sớm 05:00 khi hoa đã rụng; Không bao giờ mở cánh hoa','Ban đêm từ 19:30 – 21:30','Ban đêm từ 19:30 – 21:30',1794030808),
(699,59,3,'deferredfeedback',51,1,1.0000000,0.0000000,1.0000000,0,'Nguyên nhân sinh lý phổ biến nhất gây rụng trái non hàng loạt khi trái sầu riêng mới bằng quả trứng gà là gì?\n: Cây phóng cơi đọt non mạnh cạnh tranh dinh dưỡng/Canxi-Bo với trái non hoặc sốc nước mưa đầu mùa; Bộ lá già khỏe mạnh quang hợp tốt; Thụ phấn chéo ban đêm đầy đủ; Độ pH đất ổn định 6.2','Cây phóng cơi đọt non mạnh cạnh tranh dinh dưỡng/Canxi-Bo với trái non hoặc sốc nước mưa đầu mùa','Cây phóng cơi đọt non mạnh cạnh tranh dinh dưỡng/Canxi-Bo với trái non hoặc sốc nước mưa đầu mùa',1794030808),
(700,59,4,'deferredfeedback',52,1,1.0000000,0.0000000,1.0000000,0,'Đối tượng dịch hại kiểm dịch thực vật hàng đầu trên trái sầu riêng xuất khẩu cần làm sạch tuyệt đối 100% là loài nào?\n: Rệp sáp phấn trắng (Planococcus / Pseudococcus) và sâu đục quả/hạt; Giun đất có ích trong đất; Ong mật thụ phấn; Vi khuẩn cố định đạm','Rệp sáp phấn trắng (Planococcus / Pseudococcus) và sâu đục quả/hạt','Rệp sáp phấn trắng (Planococcus / Pseudococcus) và sâu đục quả/hạt',1794030808),
(701,59,5,'deferredfeedback',53,1,1.0000000,0.0000000,1.0000000,0,'Biện pháp canh tác căn cơ giúp giảm độ linh động và ngăn rễ sầu riêng hấp thu kim loại nặng Cadimi (Cd) vượt ngưỡng là gì?\n: Nâng pH đất lên 5.8–6.5, tăng chất hữu cơ vi sinh cố định Cd và chọn phân lân sạch kiểm định Cd; Hạ pH đất thật chua xuống 3.8; Ngưng bón toàn bộ phân hữu cơ; Tưới nước thải công nghiệp chưa xử lý','Nâng pH đất lên 5.8–6.5, tăng chất hữu cơ vi sinh cố định Cd và chọn phân lân sạch kiểm định Cd','Nâng pH đất lên 5.8–6.5, tăng chất hữu cơ vi sinh cố định Cd và chọn phân lân sạch kiểm định Cd',1794030808),
(702,59,6,'deferredfeedback',54,1,1.0000000,0.0000000,1.0000000,0,'Tác nhân nấm nguy hiểm nhất gây bệnh nứt thân xì mủ và thối rễ vàng lá trên cây sầu riêng mùa mưa là loài nào?\n: Phytophthora palmivora; Nấm men Saccharomyces; Nấm đối kháng Trichoderma; Nấm rơm Volvariella','Phytophthora palmivora','Phytophthora palmivora',1794030808),
(703,59,7,'deferredfeedback',55,1,1.0000000,0.0000000,1.0000000,0,'Chỉ tiêu hàm lượng chất khô tối thiểu trong cơm sầu riêng Dona (Monthong) để đảm bảo đủ độ già chín sinh lý khi thu hoạch xuất khẩu là bao nhiêu?\n: Đạt tối thiểu >= 32%; Chỉ cần 12% (trái non trắng); 5%; 98% khô cứng như đá','Đạt tối thiểu >= 32%','Đạt tối thiểu >= 32%',1794030808),
(704,59,8,'deferredfeedback',56,1,1.0000000,0.0000000,1.0000000,0,'Mỗi trái sầu riêng thương phẩm 3 kg cần trung bình bao nhiêu lá trưởng thành khỏe mạnh trên cành để nuôi trái đạt chuẩn?\n: Khoảng 300 – 400 lá khỏe mạnh không sâu bệnh; Chỉ cần 3 lá trên cả cây; Vặt trụi hết lá để trái phơi nắng; 10 lá','Khoảng 300 – 400 lá khỏe mạnh không sâu bệnh','Khoảng 300 – 400 lá khỏe mạnh không sâu bệnh',1794030808),
(705,59,9,'deferredfeedback',57,1,1.0000000,0.0000000,1.0000000,0,'Khi sử dụng nấm đối kháng Trichoderma tưới gốc phòng bệnh thối rễ sầu riêng, cần lưu ý nguyên tắc nào?\n: Đất đủ ẩm, giàu mùn hữu cơ và cách ly việc rải vôi nóng hoặc tưới thuốc nấm hóa học gốc đồng ít nhất 10–14 ngày; Pha chung trực tiếp với thuốc trừ nấm gốc đồng đậm đặc trong cùng một phi; Rải trên mặt bê tông khô nắng gắt 45°C; Chỉ phun lên ngọn lá lúc 12h trưa','Đất đủ ẩm, giàu mùn hữu cơ và cách ly việc rải vôi nóng hoặc tưới thuốc nấm hóa học gốc đồng ít nhất 10–14 ngày','Đất đủ ẩm, giàu mùn hữu cơ và cách ly việc rải vôi nóng hoặc tưới thuốc nấm hóa học gốc đồng ít nhất 10–14 ngày',1794030808),
(706,59,10,'deferredfeedback',58,1,1.0000000,0.0000000,1.0000000,0,'Mã số vùng trồng (PUC - Production Unit Code) của vườn sầu riêng xuất khẩu có thể bị đình chỉ thu hồi trong trường hợp nào?\n: Vi phạm kiểm dịch thực vật (nhiễm rệp sáp), vượt dư lượng BVTV/Cadimi hoặc gian lận mượn mã vùng trồng; Ghi chép nhật ký VietGAP đầy đủ chính xác; Áp dụng tưới tiết kiệm và IPM sinh học; Thu hoạch đúng độ chín chuẩn','Vi phạm kiểm dịch thực vật (nhiễm rệp sáp), vượt dư lượng BVTV/Cadimi hoặc gian lận mượn mã vùng trồng','Vi phạm kiểm dịch thực vật (nhiễm rệp sáp), vượt dư lượng BVTV/Cadimi hoặc gian lận mượn mã vùng trồng',1794030808),
(707,59,11,'deferredfeedback',59,1,1.0000000,0.0000000,1.0000000,0,'Vì sao khi trồng sầu riêng ở vùng đất thấp hoặc mưa nhiều bắt buộc phải đắp mô nổi và xẻ rãnh thoát nước?\n: Bộ rễ sầu riêng rất mẫn cảm ngập úng thiếu oxy; đọng nước làm thối rễ tơ và kích hoạt nấm Phytophthora; Vì sầu riêng là cây thủy sinh ưa ngập nước sâu; Để không phải tưới nước mùa khô; Để ngăn ánh sáng chiếu vào tán cây','Bộ rễ sầu riêng rất mẫn cảm ngập úng thiếu oxy; đọng nước làm thối rễ tơ và kích hoạt nấm Phytophthora','Bộ rễ sầu riêng rất mẫn cảm ngập úng thiếu oxy; đọng nước làm thối rễ tơ và kích hoạt nấm Phytophthora',1794030808),
(708,59,12,'deferredfeedback',60,1,1.0000000,0.0000000,1.0000000,0,'Khoảng thời gian cách ly và nguyên tắc ghi nhật ký đối với vườn sầu riêng có Mã số vùng trồng xuất khẩu là gì?\n: Chỉ dùng hoạt chất được nước nhập khẩu cho phép, ghi chép đầy đủ 100% và tuân thủ nghiêm ngặt thời gian cách ly PHI; Phun bất kỳ thuốc cấm nào sát ngày cắt trái; Không cần lưu hồ sơ vật tư đầu vào; Thu gom trái không rõ nguồn gốc đóng chung lô','Chỉ dùng hoạt chất được nước nhập khẩu cho phép, ghi chép đầy đủ 100% và tuân thủ nghiêm ngặt thời gian cách ly PHI','Phun bất kỳ thuốc cấm nào sát ngày cắt trái',1794030808),
(709,60,1,'deferredfeedback',13,1,1.0000000,0.0000000,1.0000000,0,'Mục đích cốt lõi của công đoạn làm mát sơ bộ (Pre-cooling) trong vòng 2 giờ đầu sau thu hoạch là gì?\n: Nhanh chóng rút nhiệt đồng ruộng, giảm cường độ hô hấp và sự mất nước của nông sản; Làm chín nhanh toàn bộ lô hàng trong 1 giờ; Tăng hàm lượng nước tự do đọng trên mặt lá; Làm đông cứng rau ăn lá ở -20°C','Nhanh chóng rút nhiệt đồng ruộng, giảm cường độ hô hấp và sự mất nước của nông sản','Nhanh chóng rút nhiệt đồng ruộng, giảm cường độ hô hấp và sự mất nước của nông sản',1794030808),
(710,60,2,'deferredfeedback',14,1,1.0000000,0.0000000,1.0000000,0,'Phương pháp làm mát sơ bộ nào giúp hạ nhiệt rau ăn lá (xà lách, cải bó xôi) từ 28°C xuống 3°C nhanh nhất (chỉ 20–30 phút)?\n: Làm mát chân không (Vacuum Cooling); Phơi ngoài sân nắng; Ủ kín trong bao tải dứa; Đặt cạnh lò sấy nhiệt','Làm mát chân không (Vacuum Cooling)','Làm mát chân không (Vacuum Cooling)',1794030808),
(711,60,3,'deferredfeedback',15,1,1.0000000,0.0000000,1.0000000,0,'Nhiệt độ và ẩm độ kho mát tiêu chuẩn để bảo quản tươi nhóm rau ăn lá ôn đới (xà lách, cải thảo, bông cải) là bao nhiêu?\n: 2°C – 5°C và ẩm độ 90% – 95%; 22°C – 28°C và ẩm độ 40%; -18°C đóng băng hoàn toàn; 35°C và ẩm độ 99%','2°C – 5°C và ẩm độ 90% – 95%','2°C – 5°C và ẩm độ 90% – 95%',1794030808),
(712,60,4,'deferredfeedback',16,1,1.0000000,0.0000000,1.0000000,0,'Vì sao không được bảo quản trái cây nhiệt đới tươi nguyên quả (xoài, chuối, sầu riêng tươi) ở nhiệt độ quá thấp 0–4°C?\n: Gây hiện tượng tổn thương lạnh (Chilling Injury) làm thâm đen vỏ và sượng thịt quả; Làm trái nổ vỡ ngay lập tức; Làm tăng trọng lượng trái lên 200%; Vì kho lạnh không thể chỉnh dưới 15°C','Gây hiện tượng tổn thương lạnh (Chilling Injury) làm thâm đen vỏ và sượng thịt quả','Gây hiện tượng tổn thương lạnh (Chilling Injury) làm thâm đen vỏ và sượng thịt quả',1794030808),
(713,60,5,'deferredfeedback',17,1,1.0000000,0.0000000,1.0000000,0,'Nguyên lý chính của bao bì khí quyển biến đổi MAP (Modified Atmosphere Packaging) trong bảo quản rau quả tươi là gì?\n: Giảm nồng độ O2 (3–5%) và nâng nhẹ CO2 (5–8%) để làm chậm hô hấp và ức chế vi sinh gây hư hỏng; Bơm 100% khí Ethylene vào túi để thúc chín; Hút kiệt tạo áp suất nén nát lá rau; Bơm không khí nóng 60°C vào bao bì','Giảm nồng độ O2 (3–5%) và nâng nhẹ CO2 (5–8%) để làm chậm hô hấp và ức chế vi sinh gây hư hỏng','Giảm nồng độ O2 (3–5%) và nâng nhẹ CO2 (5–8%) để làm chậm hô hấp và ức chế vi sinh gây hư hỏng',1794030808),
(714,60,6,'deferredfeedback',18,1,1.0000000,0.0000000,1.0000000,0,'Công nghệ sấy lạnh bơm nhiệt (Heat-Pump Drying) vận hành ở dải nhiệt độ nào để bảo toàn màu sắc và Vitamin?\n: 25°C – 42°C với không khí tách ẩm khô tuần hoàn kín; 120°C – 180°C bằng than đá; 95°C – 110°C ngoài trời; -40°C không tách ẩm','25°C – 42°C với không khí tách ẩm khô tuần hoàn kín','25°C – 42°C với không khí tách ẩm khô tuần hoàn kín',1794030808),
(715,60,7,'deferredfeedback',19,1,1.0000000,0.0000000,1.0000000,0,'Tại sao không nên xếp chung kho lạnh giữa các trái sinh nhiều khí Ethylene (chuối chín, sầu riêng) với rau ăn lá hoặc dưa leo?\n: Khí Ethylene kích thích vàng lá, rụng cuống và làm già hóa hư hỏng nhanh rau ăn lá; Làm kho lạnh tiêu tốn ít điện hơn; Làm dưa leo ngọt thành dưa lưới; Không có bất kỳ tác động sinh lý nào','Khí Ethylene kích thích vàng lá, rụng cuống và làm già hóa hư hỏng nhanh rau ăn lá','Khí Ethylene kích thích vàng lá, rụng cuống và làm già hóa hư hỏng nhanh rau ăn lá',1794030808),
(716,60,8,'deferredfeedback',20,1,1.0000000,0.0000000,1.0000000,0,'Công nghệ cấp đông siêu tốc IQF (-35°C đến -40°C) giúp múi sầu riêng xuất khẩu đạt chất lượng vượt trội nhờ cơ chế nào?\n: Hình thành vi tinh thể băng cực nhỏ không phá vỡ màng tế bào, không chảy dịch khi rã đông; Rút hết toàn bộ hương thơm của sầu riêng; Biến tinh bột thành chất xơ gỗ; Không cần bảo quản lạnh sau cấp đông','Hình thành vi tinh thể băng cực nhỏ không phá vỡ màng tế bào, không chảy dịch khi rã đông','Hình thành vi tinh thể băng cực nhỏ không phá vỡ màng tế bào, không chảy dịch khi rã đông',1794030808),
(717,60,9,'deferredfeedback',21,1,1.0000000,0.0000000,1.0000000,0,'Nguyên tắc thiết kế mặt bằng nhà xưởng sơ chế nông sản đạt chuẩn HACCP / ISO 22000 là gì?\n: Nguyên tắc dòng chảy 1 chiều từ khu nguyên liệu sang khu sạch đóng gói, không nhiễm chéo; Nhập nguyên liệu và xuất thành phẩm chung một bàn sơ chế đất; Đặt kho thuốc BVTV ngay trong phòng đóng gói; Không cần khử trùng dao kéo thu hoạch','Nguyên tắc dòng chảy 1 chiều từ khu nguyên liệu sang khu sạch đóng gói, không nhiễm chéo','Nguyên tắc dòng chảy 1 chiều từ khu nguyên liệu sang khu sạch đóng gói, không nhiễm chéo',1794030808),
(718,60,10,'deferredfeedback',22,1,1.0000000,0.0000000,1.0000000,0,'Trước khi đóng gói rau ăn lá vào túi màng MAP, yêu cầu bắt buộc đối với bề mặt lá sau khi rửa là gì?\n: Phải làm ráo hoàn toàn nước tự do đọng trên lá (ly tâm/quạt lạnh) để ngừa thối nhũn vi khuẩn; Để nguyên nước ướt sũng trong túi kín; Phun nước đường lên mặt lá; Phơi nắng trưa 35°C trong 2 giờ','Phải làm ráo hoàn toàn nước tự do đọng trên lá (ly tâm/quạt lạnh) để ngừa thối nhũn vi khuẩn','Để nguyên nước ướt sũng trong túi kín',1794030808),
(719,60,11,'deferredfeedback',23,1,1.0000000,0.0000000,1.0000000,0,'Thiết bị nào bắt buộc gắn trong container lạnh xuất khẩu đường biển để minh chứng chuỗi lạnh không bị đứt gãy?\n: Thiết bị ghi hành trình nhiệt độ - ẩm độ tự động (DataLogger); Bình tưới cây cầm tay; Bẫy dính côn trùng màu vàng; Bút thử độ mặn đất','Thiết bị ghi hành trình nhiệt độ - ẩm độ tự động (DataLogger)','Bình tưới cây cầm tay',1794030808),
(720,60,12,'deferredfeedback',24,1,1.0000000,0.0000000,1.0000000,0,'Thông tin nào cần hiển thị công khai khi người tiêu dùng quét mã QR truy xuất nguồn gốc trên bao bì nông sản VietGAP?\n: Mã lô sản xuất, tên nông hộ & tọa độ vùng trồng, lịch sử nhật ký canh tác, ngày thu hoạch & chuẩn an toàn; Mật khẩu quản trị hệ thống của nông trại; Số tài khoản cá nhân của tài xế; Chỉ hiển thị một bức ảnh tĩnh không có dữ liệu lô','Mã lô sản xuất, tên nông hộ & tọa độ vùng trồng, lịch sử nhật ký canh tác, ngày thu hoạch & chuẩn an toàn','Mật khẩu quản trị hệ thống của nông trại',1794030808),
(721,61,1,'deferredfeedback',61,1,1.0000000,0.0000000,1.0000000,0,'Tỷ lệ Carbon / Nitơ (C/N) lý tưởng nhất của hỗn hợp nguyên liệu ban đầu khi ủ phân hữu cơ vi sinh là bao nhiêu?\n: 25:1 đến 30:1; 500:1 (chỉ toàn mùn cưa khô không có đạm); 2:1 (chỉ toàn đạm đặc); 0:0','25:1 đến 30:1','25:1 đến 30:1',1794030809),
(722,61,2,'deferredfeedback',62,1,1.0000000,0.0000000,1.0000000,0,'Độ ẩm nguyên liệu chuẩn khi bắt đầu đánh đống ủ phân hữu cơ hiếu khí (kiểm tra nắm chặt rỉ nước kẽ tay không nhỏ giọt) là bao nhiêu?\n: 55% – 60%; 5% khô rang như cát; 95% ngập sũng như cháo loãng; 0%','55% – 60%','55% – 60%',1794030809),
(723,61,3,'deferredfeedback',63,1,1.0000000,0.0000000,1.0000000,0,'Nhiệt độ ở giai đoạn ưa nhiệt (Thermophilic phase) trong tâm đống ủ đạt 55–65°C kéo dài nhiều ngày có tác dụng quan trọng gì?\n: Tiêu diệt vi khuẩn gây bệnh (E.coli, Salmonella), trứng tuyến trùng, nấm hại và làm mất sức nảy mầm hạt cỏ dại; Làm phân biến thành nhựa tổng hợp; Giữ sống toàn bộ hạt cỏ dại để mọc nhiều hơn; Đóng băng đống phân','Tiêu diệt vi khuẩn gây bệnh (E.coli, Salmonella), trứng tuyến trùng, nấm hại và làm mất sức nảy mầm hạt cỏ dại','Tiêu diệt vi khuẩn gây bệnh (E.coli, Salmonella), trứng tuyến trùng, nấm hại và làm mất sức nảy mầm hạt cỏ dại',1794030809),
(724,61,4,'deferredfeedback',64,1,1.0000000,0.0000000,1.0000000,0,'Vì sao nên cấy bổ sung chủng nấm đối kháng Trichoderma vào giai đoạn đống ủ đã hạ nhiệt nguội (<38°C) thay vì lúc đang nóng 65°C?\n: Tránh nhiệt độ quá cao 65°C tiêu diệt bào tử Trichoderma, giúp nấm nhân sinh khối tối đa trong phân thành phẩm; Vì Trichoderma chỉ sống ở 100°C; Để làm phân bốc mùi khai; Không có lý do kỹ thuật nào','Tránh nhiệt độ quá cao 65°C tiêu diệt bào tử Trichoderma, giúp nấm nhân sinh khối tối đa trong phân thành phẩm','Tránh nhiệt độ quá cao 65°C tiêu diệt bào tử Trichoderma, giúp nấm nhân sinh khối tối đa trong phân thành phẩm',1794030809),
(725,61,5,'deferredfeedback',65,1,1.0000000,0.0000000,1.0000000,0,'Theo tiêu chuẩn VietGAP, vì sao nghiêm cấm bón phân chuồng tươi chưa qua ủ hoai mục trực tiếp cho rau quả?\n: Nguy cơ nhiễm vi sinh vật gây bệnh đường ruột (E.coli, Salmonella), tuyến trùng rễ và sinh nhiệt độc rễ; Vì phân tươi quá đắt tiền; Vì phân tươi có màu quá đẹp; Vì phân tươi làm tăng oxy đất quá mức','Nguy cơ nhiễm vi sinh vật gây bệnh đường ruột (E.coli, Salmonella), tuyến trùng rễ và sinh nhiệt độc rễ','Nguy cơ nhiễm vi sinh vật gây bệnh đường ruột (E.coli, Salmonella), tuyến trùng rễ và sinh nhiệt độc rễ',1794030809),
(726,61,6,'deferredfeedback',66,1,1.0000000,0.0000000,1.0000000,0,'Khi đống ủ phân hữu cơ bốc mùi trứng thối (H2S) và chua gắt, nguyên nhân kỹ thuật là do đâu và xử lý thế nào?\n: Đống ủ quá ướt thiếu oxy (yếm khí); cần đảo trộn tơi xốp và bổ sung chất độn khô giàu Carbon (trấu, mùn dừa); Đống ủ quá giàu oxy; cần đổ ngập nước kín; Nhiệt độ ngoài trời 25°C; Do có nhiều xạ khuẩn thơm','Đống ủ quá ướt thiếu oxy (yếm khí); cần đảo trộn tơi xốp và bổ sung chất độn khô giàu Carbon (trấu, mùn dừa)','Đống ủ quá ướt thiếu oxy (yếm khí); cần đảo trộn tơi xốp và bổ sung chất độn khô giàu Carbon (trấu, mùn dừa)',1794030809),
(727,61,7,'deferredfeedback',67,1,1.0000000,0.0000000,1.0000000,0,'Dấu hiệu cảm quan chính xác chứng tỏ mẻ phân hữu cơ vi sinh đã chín hoai hoàn toàn sẵn sàng đem bón là gì?\n: Màu nâu đen tơi xốp, nhiệt độ hạ bằng môi trường và có mùi thơm dịu của đất rừng (xạ khuẩn); Tâm đống ủ vẫn nóng bỏng 65°C và bốc mùi khai nồng; Nguyên liệu còn nguyên màu xanh tươi; Chảy nước đen hôi thối','Màu nâu đen tơi xốp, nhiệt độ hạ bằng môi trường và có mùi thơm dịu của đất rừng (xạ khuẩn)','Màu nâu đen tơi xốp, nhiệt độ hạ bằng môi trường và có mùi thơm dịu của đất rừng (xạ khuẩn)',1794030809),
(728,61,8,'deferredfeedback',68,1,1.0000000,0.0000000,1.0000000,0,'Nhóm vi sinh vật có ích Bacillus megaterium / Bacillus subtilis bổ sung trong phân hữu cơ vi sinh có khả năng nổi bật nào?\n: Tiết enzyme và axit hữu cơ phân giải Lân khó tan trong đất thành dạng cây dễ hấp thu và đối kháng nấm khuẩn hại; Biến đất cát thành đá tảng; Hút hết oxy làm ngạt rễ cây; Làm chua đất xuống pH 2.0','Tiết enzyme và axit hữu cơ phân giải Lân khó tan trong đất thành dạng cây dễ hấp thu và đối kháng nấm khuẩn hại','Tiết enzyme và axit hữu cơ phân giải Lân khó tan trong đất thành dạng cây dễ hấp thu và đối kháng nấm khuẩn hại',1794030809),
(729,61,9,'deferredfeedback',69,1,1.0000000,0.0000000,1.0000000,0,'Vị trí và cách bón phân hữu cơ vi sinh cho cây ăn quả lâu năm (Sầu riêng, Bưởi) đạt hiệu quả cao nhất là gì?\n: Bón theo hình chiếu rìa tán lá (vùng rễ tơ), lấp đất mỏng hoặc tủ rơm giữ ẩm tránh nắng UV chiếu chết vi sinh; Đổ thành đống dày 50cm ốp sát vào cổ thân gốc cây; Rải phơi khô trắng trên mặt cỏ giữa trưa nắng gắt không tưới; Pha nguyên xác phân thô vào ống nhỏ giọt bù áp','Bón theo hình chiếu rìa tán lá (vùng rễ tơ), lấp đất mỏng hoặc tủ rơm giữ ẩm tránh nắng UV chiếu chết vi sinh','Bón theo hình chiếu rìa tán lá (vùng rễ tơ), lấp đất mỏng hoặc tủ rơm giữ ẩm tránh nắng UV chiếu chết vi sinh',1794030809),
(730,61,10,'deferredfeedback',70,1,1.0000000,0.0000000,1.0000000,0,'Khi thủy phân đạm cá / bánh dầu sinh học làm phân tưới gốc không mùi hôi, nguyên liệu nào cung cấp nguồn đường nuôi khuẩn Lactic & Bacillus?\n: Rỉ mật đường (Molasses) kết hợp chế phẩm men vi sinh EM / Protease; Dầu hỏa công nghiệp; Vôi nung CaO liều cao; Muối hột bão hòa','Rỉ mật đường (Molasses) kết hợp chế phẩm men vi sinh EM / Protease','Rỉ mật đường (Molasses) kết hợp chế phẩm men vi sinh EM / Protease',1794030809),
(731,61,11,'deferredfeedback',71,1,1.0000000,0.0000000,1.0000000,0,'Tác dụng cải tạo vật lý - hóa học quan trọng nhất của mùn hữu cơ đối với đất đỏ bazan Tây Nguyên và đất xám Đông Nam Bộ là gì?\n: Tăng khả năng giữ phân CEC, đệm ổn định pH đất, tạo cấu trúc tơi xốp giàu oxy và nuôi hệ thiên địch đất; Làm đất nén chặt không thấm nước; Làm tăng độc tố Nhôm di động Al3+; Tiêu diệt hết giun đất','Tăng khả năng giữ phân CEC, đệm ổn định pH đất, tạo cấu trúc tơi xốp giàu oxy và nuôi hệ thiên địch đất','Tăng khả năng giữ phân CEC, đệm ổn định pH đất, tạo cấu trúc tơi xốp giàu oxy và nuôi hệ thiên địch đất',1794030809),
(732,61,12,'deferredfeedback',72,1,1.0000000,0.0000000,1.0000000,0,'Mật độ vi sinh vật hữu ích tối thiểu trên nhãn/mẻ phân hữu cơ vi sinh chất lượng cao thường đạt ngưỡng nào?\n: Từ 10^6 đến 10^8 CFU/g trở lên; 0 CFU/g (vô trùng tuyệt đối); 1 tế bào trên 1 tấn phân; Chỉ chứa cát sỏi khoáng','Từ 10^6 đến 10^8 CFU/g trở lên','Từ 10^6 đến 10^8 CFU/g trở lên',1794030809),
(733,62,1,'deferredfeedback',61,1,1.0000000,0.0000000,1.0000000,0,'Tỷ lệ Carbon / Nitơ (C/N) lý tưởng nhất của hỗn hợp nguyên liệu ban đầu khi ủ phân hữu cơ vi sinh là bao nhiêu?\n: 25:1 đến 30:1; 500:1 (chỉ toàn mùn cưa khô không có đạm); 2:1 (chỉ toàn đạm đặc); 0:0','25:1 đến 30:1','25:1 đến 30:1',1794030809),
(734,62,2,'deferredfeedback',62,1,1.0000000,0.0000000,1.0000000,0,'Độ ẩm nguyên liệu chuẩn khi bắt đầu đánh đống ủ phân hữu cơ hiếu khí (kiểm tra nắm chặt rỉ nước kẽ tay không nhỏ giọt) là bao nhiêu?\n: 55% – 60%; 5% khô rang như cát; 95% ngập sũng như cháo loãng; 0%','55% – 60%','55% – 60%',1794030809),
(735,62,3,'deferredfeedback',63,1,1.0000000,0.0000000,1.0000000,0,'Nhiệt độ ở giai đoạn ưa nhiệt (Thermophilic phase) trong tâm đống ủ đạt 55–65°C kéo dài nhiều ngày có tác dụng quan trọng gì?\n: Tiêu diệt vi khuẩn gây bệnh (E.coli, Salmonella), trứng tuyến trùng, nấm hại và làm mất sức nảy mầm hạt cỏ dại; Làm phân biến thành nhựa tổng hợp; Giữ sống toàn bộ hạt cỏ dại để mọc nhiều hơn; Đóng băng đống phân','Tiêu diệt vi khuẩn gây bệnh (E.coli, Salmonella), trứng tuyến trùng, nấm hại và làm mất sức nảy mầm hạt cỏ dại','Tiêu diệt vi khuẩn gây bệnh (E.coli, Salmonella), trứng tuyến trùng, nấm hại và làm mất sức nảy mầm hạt cỏ dại',1794030809),
(736,62,4,'deferredfeedback',64,1,1.0000000,0.0000000,1.0000000,0,'Vì sao nên cấy bổ sung chủng nấm đối kháng Trichoderma vào giai đoạn đống ủ đã hạ nhiệt nguội (<38°C) thay vì lúc đang nóng 65°C?\n: Tránh nhiệt độ quá cao 65°C tiêu diệt bào tử Trichoderma, giúp nấm nhân sinh khối tối đa trong phân thành phẩm; Vì Trichoderma chỉ sống ở 100°C; Để làm phân bốc mùi khai; Không có lý do kỹ thuật nào','Tránh nhiệt độ quá cao 65°C tiêu diệt bào tử Trichoderma, giúp nấm nhân sinh khối tối đa trong phân thành phẩm','Tránh nhiệt độ quá cao 65°C tiêu diệt bào tử Trichoderma, giúp nấm nhân sinh khối tối đa trong phân thành phẩm',1794030809),
(737,62,5,'deferredfeedback',65,1,1.0000000,0.0000000,1.0000000,0,'Theo tiêu chuẩn VietGAP, vì sao nghiêm cấm bón phân chuồng tươi chưa qua ủ hoai mục trực tiếp cho rau quả?\n: Nguy cơ nhiễm vi sinh vật gây bệnh đường ruột (E.coli, Salmonella), tuyến trùng rễ và sinh nhiệt độc rễ; Vì phân tươi quá đắt tiền; Vì phân tươi có màu quá đẹp; Vì phân tươi làm tăng oxy đất quá mức','Nguy cơ nhiễm vi sinh vật gây bệnh đường ruột (E.coli, Salmonella), tuyến trùng rễ và sinh nhiệt độc rễ','Nguy cơ nhiễm vi sinh vật gây bệnh đường ruột (E.coli, Salmonella), tuyến trùng rễ và sinh nhiệt độc rễ',1794030809),
(738,62,6,'deferredfeedback',66,1,1.0000000,0.0000000,1.0000000,0,'Khi đống ủ phân hữu cơ bốc mùi trứng thối (H2S) và chua gắt, nguyên nhân kỹ thuật là do đâu và xử lý thế nào?\n: Đống ủ quá ướt thiếu oxy (yếm khí); cần đảo trộn tơi xốp và bổ sung chất độn khô giàu Carbon (trấu, mùn dừa); Đống ủ quá giàu oxy; cần đổ ngập nước kín; Nhiệt độ ngoài trời 25°C; Do có nhiều xạ khuẩn thơm','Đống ủ quá ướt thiếu oxy (yếm khí); cần đảo trộn tơi xốp và bổ sung chất độn khô giàu Carbon (trấu, mùn dừa)','Đống ủ quá ướt thiếu oxy (yếm khí); cần đảo trộn tơi xốp và bổ sung chất độn khô giàu Carbon (trấu, mùn dừa)',1794030809),
(739,62,7,'deferredfeedback',67,1,1.0000000,0.0000000,1.0000000,0,'Dấu hiệu cảm quan chính xác chứng tỏ mẻ phân hữu cơ vi sinh đã chín hoai hoàn toàn sẵn sàng đem bón là gì?\n: Màu nâu đen tơi xốp, nhiệt độ hạ bằng môi trường và có mùi thơm dịu của đất rừng (xạ khuẩn); Tâm đống ủ vẫn nóng bỏng 65°C và bốc mùi khai nồng; Nguyên liệu còn nguyên màu xanh tươi; Chảy nước đen hôi thối','Màu nâu đen tơi xốp, nhiệt độ hạ bằng môi trường và có mùi thơm dịu của đất rừng (xạ khuẩn)','Màu nâu đen tơi xốp, nhiệt độ hạ bằng môi trường và có mùi thơm dịu của đất rừng (xạ khuẩn)',1794030809),
(740,62,8,'deferredfeedback',68,1,1.0000000,0.0000000,1.0000000,0,'Nhóm vi sinh vật có ích Bacillus megaterium / Bacillus subtilis bổ sung trong phân hữu cơ vi sinh có khả năng nổi bật nào?\n: Tiết enzyme và axit hữu cơ phân giải Lân khó tan trong đất thành dạng cây dễ hấp thu và đối kháng nấm khuẩn hại; Biến đất cát thành đá tảng; Hút hết oxy làm ngạt rễ cây; Làm chua đất xuống pH 2.0','Tiết enzyme và axit hữu cơ phân giải Lân khó tan trong đất thành dạng cây dễ hấp thu và đối kháng nấm khuẩn hại','Tiết enzyme và axit hữu cơ phân giải Lân khó tan trong đất thành dạng cây dễ hấp thu và đối kháng nấm khuẩn hại',1794030809),
